INSERT INTO `devops_agent_template` VALUES (1, 'JDK-11', '', '{\n  \"arguments\": [\n    {\n      \"value\": {\n        \"isLiteral\": false,\n        \"value\": \"\\\"${env.runCluster}\\\"\"\n      },\n      \"key\": \"cloud\"\n    },\n    {\n      \"value\": {\n        \"isLiteral\": true,\n        \"value\": \"maven\"\n      },\n      \"key\": \"defaultContainer\"\n    },\n    {\n      \"value\": {\n        \"isLiteral\": true,\n        \"value\": \"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"\n      },\n      \"key\": \"yaml\"\n    }\n  ],\n  \"type\": \"kubernetes\"\n}', '2022-03-25 00:00:00', '2023-01-17 00:00:00', NULL, NULL);
INSERT INTO `devops_agent_template` VALUES (2, 'NORMAL', '', '{\r\n  \"type\": \"label\",\r\n  \"argument\": {\r\n    \"isLiteral\": false,\r\n    \"value\": \"\\\"${env.runLabels}\\\"\"\r\n  }\r\n}', '2022-03-25 17:20:32', '2022-12-26 19:45:48', NULL, NULL);
