INSERT INTO `devops_jenkinsfile` VALUES (1, 1, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"name\":\"代码克隆\",\"branches\":[{\"name\":\"default\",\"steps\":[{\"name\":\"script\",\"stepName\":\"代码克隆\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"echo \'代码克隆\'\\n          try{\\n            if(gitUser&&gitUser!=\\\"-\\\"){\\n              arr = gitRepoUrl.split(\\\"/\\\")\\n              env.project = arr[arr.length -1].replace(\\\".git\\\",\\\"\\\")\\n              projectexit = sh returnStdout: true ,script: \\\"ls|grep ${project}|tr -d \'\\\\n\\\\r\'\\\"\\n\\n              urlHead = gitRepoUrl.split(\\\":\\\")[0]\\n              urlTail = gitRepoUrl.split(\\\"//\\\")[1]\\n              gitUser = gitUser.replace(\\\"@\\\",\\\"@\\\")\\n              gitPassword = gitPassword.replace(\\\"@\\\",\\\"@\\\")\\n              def a = \\\"${urlHead}://${gitUser}:${gitPassword}@${urlTail}\\\"\\n              if(projectexit == \'\'){\\n                sh \\\"git clone -b ${branch} ${a} ./\\\"\\n              }\\n            }else{\\n              checkout([$class: \\\"GitSCM\\\",\\n              branches: [[name: branch]],\\n              userRemoteConfigs: [[\\n                credentialsId: env.gitCreadentId,\\n                url: gitRepoUrl\\n              ]]])\\n            }\\n            if(\\\"${commitId}\\\" != \\\"-\\\"){\\n              sh \\\"git checkout ${commitId} \\\"\\n            }\\n\\n          }catch(Exception e){\\n            echo \\\"克隆代码报错，e:\\\"\\n            echo \\\"${e}\\\"\\n            echo \\\"标记扫描任务执行异常\\\"\\n\\n            sh returnStdout: true, script: \'\'\'\\\"\\\"\\\"\\n            curl -X GET ${codeInspectSvcUrl}/scanTasks/history/${historyId}/error -H \\\"accept: */*\\\" -H \\\"X-SCM-TOKEN: SCM@2023\\\"  -H \\\"Amp-Organ-Id: ${env.tenantId}\\\"\\n            \\\"\\\"\\\"\'\'\'\\n            error \\\"代码克隆异常\\\"\\n          }\"},\"key\":\"scriptBlock\"}]}]}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码克隆\"},\"key\":\"stageName\"}]},{\"name\":\"代码扫描\",\"branches\":[{\"name\":\"default\",\"steps\":[{\"name\":\"script\",\"stepName\":\"sonar扫描\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"echo \'sonar扫描\'\\n          try{\\n            sonarCommit = \\\"\\\"\\n            sonarInclusion = \\\"\\\"\\n            sonarExclusion = \\\"\\\"\\n            compareBaseTime = \\\"\\\"\\n            if(commitId != \\\"-\\\"){\\n              sonarCommit = \\\"sonar.analysis.commitId=${commitId}\\\"\\n              sh \\\"echo sonar.analysis.commitId=${commitId} >> sonar-project.properties\\\"\\n            }else{\\n              commitIdTemp = sh returnStdout: true ,script: \'git rev-parse --verify  HEAD\'\\n              sh \\\"curl ${codeInspectSvcUrl}/scanTasks/history/${historyId}/${commitIdTemp}\\\"\\n              sonarCommit = \\\"sonar.analysis.commitId=${commitIdTemp}\\\"\\n              sh \\\"echo sonar.analysis.commitId=${commitIdTemp} >> sonar-project.properties\\\"\\n            }\\n            if(compareBranch&&compareBranch!=\\\"-\\\"){\\n              sonarInclusion = \\\"sonar.inclusions=-\\\"\\n              changeFile = sh returnStdout: true, script: \\\"git diff ${compareBranch} --name-only\\\"\\n              if(changeFile){\\n                sonarInclusion = \\\"sonar.inclusions=\\\"+changeFile.replaceAll(\\\"\\\\n\\\",\\\",\\\")\\n                sh \\\"echo ${sonarInclusion} >>sonar-project.properties\\\"\\n              }\\n              commitWithDate = sh returnStdout: true, script: \\\"git log --remotes --pretty=%H@%cd --date=iso|grep ${compareBranch}\\\"\\n              compareBaseTime = \\\"sonar.analysis.baseTime=\\\\\\\"\\\"+commitWithDate.split(\\\"@\\\")[1]+\\\"\\\\\\\"\\\"\\n              sh \\\"echo ${compareBaseTime} >>sonar-project.properties\\\"\\n            }\\n\\n            if(excludePath&&excludePath!=\\\"-\\\"){\\n              sonarExclusion = \\\"sonar.exclusions=${excludePath}\\\"\\n              sh \\\"echo sonar.exclusions=${excludePath} >>sonar-project.properties\\\"\\n            }\\n            sh \\\"echo sonar.java.binaries=./>>sonar-project.properties\\\"\\n            sh \\\"echo sonar.analysis.scanTaskId=${scanTaskId}>>sonar-project.properties\\\"\\n            sh \\\"echo sonar.branch.name=${branch}>>sonar-project.properties\\\"\\n            sh \\\"echo sonar.analysis.historyId=${historyId}>>sonar-project.properties\\\"\\n            sh \\\"echo sonar.host.url=${sonarUrl}>>sonar-project.properties\\\"\\n            withCredentials([usernamePassword(credentialsId: \'sonar-username-password\',passwordVariable: \'sonarpassword\', usernameVariable: \'sonarusername\')]) {\\n              sh \'\'\'\\\"\\\"\\\"\\n                set +x\\n                echo sonar.login=${sonarusername}>>sonar-project.properties\\n                echo sonar.password=${sonarpassword}>>sonar-project.properties\\n                set -x\\n                \\\"\\\"\\\"\'\'\'\\n\\n            }\\n\\n\\n            sh \\\"echo sonar.projectKey=${projectKey}>>sonar-project.properties\\\"\\n\\n            withEnv([\\\"PATH+WHATEVER=/usr/local/node-v16.16.0-linux-x64/bin\\\"]) {\\n              sh \\\"/usr/local/sonar-scanner/bin/sonar-scanner\\\"\\n            }\\n\\n          }catch(Exception e){\\n            echo \\\"代码扫描器执行报错，e:\\\"\\n            echo \\\"${e}\\\"\\n            echo \\\"标记扫描任务执行异常\\\"\\n            sh returnStdout: true, script: \'\'\'\\\"\\\"\\\"\\n            curl -X GET ${codeInspectSvcUrl}/scanTasks/history/${historyId}/error -H \\\"accept: */*\\\" -H \\\"X-SCM-TOKEN: SCM@2023\\\"  -H \\\"Amp-Organ-Id: ${env.tenantId}\\\"\\n            \\\"\\\"\\\"\'\'\'\\n            error \\\"代码扫描器执行异常\\\"\\n          }\"},\"key\":\"scriptBlock\"}]}]}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码扫描\"},\"key\":\"stageName\"}]}]}}', 'pipeline {\n  agent {\n    kubernetes {\n      cloud \"${env.runCluster}\"\n      defaultContainer \'maven\'\n      yaml \'\'\'\napiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: jnlp\n    image: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      environment {\n        stageName = \'代码克隆\'\n      }\n      steps {\n        script {\n          echo \'代码克隆\'\n          try{\n            if(gitUser&&gitUser!=\"-\"){\n              arr = gitRepoUrl.split(\"/\")\n              env.project = arr[arr.length -1].replace(\".git\",\"\")\n              projectexit = sh returnStdout: true ,script: \"ls|grep ${project}|tr -d \'\\n\\r\'\"\n\n              urlHead = gitRepoUrl.split(\":\")[0]\n              urlTail = gitRepoUrl.split(\"//\")[1]\n              gitUser = gitUser.replace(\"@\",\"@\")\n              gitPassword = gitPassword.replace(\"@\",\"@\")\n              def a = \"${urlHead}://${gitUser}:${gitPassword}@${urlTail}\"\n              if(projectexit == \'\'){\n                sh \"git clone -b ${branch} ${a} ./\"\n              }\n            }else{\n              checkout([$class: \"GitSCM\",\n              branches: [[name: branch]],\n              userRemoteConfigs: [[\n                credentialsId: env.gitCreadentId,\n                url: gitRepoUrl\n              ]]])\n            }\n            if(\"${commitId}\" != \"-\"){\n              sh \"git checkout ${commitId} \"\n            }\n\n          }catch(Exception e){\n            echo \"克隆代码报错，e:\"\n            echo \"${e}\"\n            echo \"标记扫描任务执行异常\"\n\n            sh returnStdout: true, script: \"\"\"\n            curl -X GET ${codeInspectSvcUrl}/scanTasks/history/${historyId}/error -H \"accept: */*\" -H \"X-SCM-TOKEN: SCM@2023\"  -H \"Amp-Organ-Id: ${env.tenantId}\"\n            \"\"\"\n            error \"代码克隆异常\"\n          }\n        }\n\n      }\n    }\n\n    stage(\'代码扫描\') {\n      environment {\n        stageName = \'代码扫描\'\n      }\n      steps {\n        script {\n          echo \'sonar扫描\'\n          try{\n            sonarCommit = \"\"\n            sonarInclusion = \"\"\n            sonarExclusion = \"\"\n            compareBaseTime = \"\"\n            if(commitId != \"-\"){\n              sonarCommit = \"sonar.analysis.commitId=${commitId}\"\n              sh \"echo sonar.analysis.commitId=${commitId} >> sonar-project.properties\"\n            }else{\n              commitIdTemp = sh returnStdout: true ,script: \'git rev-parse --verify  HEAD\'\n              sh \"curl ${codeInspectSvcUrl}/scanTasks/history/${historyId}/${commitIdTemp}\"\n              sonarCommit = \"sonar.analysis.commitId=${commitIdTemp}\"\n              sh \"echo sonar.analysis.commitId=${commitIdTemp} >> sonar-project.properties\"\n            }\n            if(compareBranch&&compareBranch!=\"-\"){\n              sonarInclusion = \"sonar.inclusions=-\"\n              changeFile = sh returnStdout: true, script: \"git diff ${compareBranch} --name-only\"\n              if(changeFile){\n                sonarInclusion = \"sonar.inclusions=\"+changeFile.replaceAll(\"\\n\",\",\")\n                sh \"echo ${sonarInclusion} >>sonar-project.properties\"\n              }\n              commitWithDate = sh returnStdout: true, script: \"git log --remotes --pretty=%H@%cd --date=iso|grep ${compareBranch}\"\n              compareBaseTime = \"sonar.analysis.baseTime=\\\"\"+commitWithDate.split(\"@\")[1]+\"\\\"\"\n              sh \"echo ${compareBaseTime} >>sonar-project.properties\"\n            }\n\n            if(excludePath&&excludePath!=\"-\"){\n              sonarExclusion = \"sonar.exclusions=${excludePath}\"\n              sh \"echo sonar.exclusions=${excludePath} >>sonar-project.properties\"\n            }\n            sh \"echo sonar.java.binaries=./>>sonar-project.properties\"\n            sh \"echo sonar.analysis.scanTaskId=${scanTaskId}>>sonar-project.properties\"\n            sh \"echo sonar.branch.name=${branch}>>sonar-project.properties\"\n            sh \"echo sonar.analysis.historyId=${historyId}>>sonar-project.properties\"\n            sh \"echo sonar.host.url=${sonarUrl}>>sonar-project.properties\"\n            withCredentials([usernamePassword(credentialsId: \'sonar-username-password\',passwordVariable: \'sonarpassword\', usernameVariable: \'sonarusername\')]) {\n              sh \"\"\"\n                set +x\n                echo sonar.login=${sonarusername}>>sonar-project.properties\n                echo sonar.password=${sonarpassword}>>sonar-project.properties\n                set -x\n                \"\"\"\n\n            }\n\n\n            sh \"echo sonar.projectKey=${projectKey}>>sonar-project.properties\"\n\n            withEnv([\"PATH+WHATEVER=/usr/local/node-v16.16.0-linux-x64/bin\"]) {\n              sh \"/usr/local/sonar-scanner/bin/sonar-scanner\"\n            }\n\n          }catch(Exception e){\n            echo \"代码扫描器执行报错，e:\"\n            echo \"${e}\"\n            echo \"标记扫描任务执行异常\"\n            sh returnStdout: true, script: \"\"\"\n            curl -X GET ${codeInspectSvcUrl}/scanTasks/history/${historyId}/error -H \"accept: */*\" -H \"X-SCM-TOKEN: SCM@2023\"  -H \"Amp-Organ-Id: ${env.tenantId}\"\n            \"\"\"\n            error \"代码扫描器执行异常\"\n          }\n        }\n\n      }\n    }\n\n  }\n}', 0, 0, '2023-02-07 11:06:20', '2025-01-14 09:40:26', 1, 1, '0', NULL, NULL);
