mage: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n      - mountPath: /root/.m2/settings.xml\n        name: config\n        subPath: settings.xml\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      environment {\n        stageName = \'代码克隆\'\n      }\n      steps {\n        gitClone(\'代码克隆\', \'1\', \'\', \'\', \'\', \'1\', \'31|http://10.10.103.229:32280/devops/java11-demo.git\', \'master\', \'\', \'\')\n      }\n    }\n\n    stage(\'代码构建\') {\n      environment {\n        stageName = \'代码构建\'\n      }\n      steps {\n        codeBuild(\'代码构建\', \'java11\', \'maven3.5\', \'mvn clean package -Dmaven.repo.local=repo -DskipTests\', \'\', \'\', \'\')\n      }\n    }\n\n    stage(\'单元测试\') {\n      environment {\n        stageName = \'单元测试\'\n      }\n      steps {\n        shCommand(\'单元测试\', \'mvn test\')\n      }\n    }\n\n    stage(\'构建Docker镜像\') {\n      environment {\n        stageName = \'构建Docker镜像\'\n      }\n      steps {\n        imageBuild(\'镜像构建\', \'10|10.10.102.213:8443/testsystem-02\', \'javadocker\', \'Dockerfile\', \'amd64\', \'defin\', \'app\')\n      }\n    }\n\n    stage(\'部署到云端\') {\n      environment {\n        stageName = \'部署到云端\'\n      }\n      steps {\n        k8sDeploy(\'Kubernetes部署\', \'1\', \'1\', \'deploy\')\n      }\n    }\n\n  }\n}', 0, 0, '2023-03-31 14:02:36', '2023-05-26 17:56:17', 1, 1, '0', NULL, NULL);
