INSERT INTO `devops_jenkinsfile` VALUES (7, 7, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"name\":\"获取变量\",\"branches\":[{\"name\":\"default\",\"steps\":[{\"name\":\"script\",\"stepName\":\"获取依赖仓库\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"echo \'获取依赖仓库\'\\n          //通过依赖分析接口获取环境变量\\n          if(deepAnalysis == \'true\'){\\n            def proxy = \'\'\\n            if(repoId != \'-\'){\\n              def result = sh returnStdout: true ,script: \'\'\'\\\"\\\"\\\"\\n                    curl -X GET \\\"${env.repositorySvcUrl}/api/repository/detail?id=${repoId}\\\" -H \\\"accept: */*\\\" -H \\\"Amp-Organ-Id: ${env.tenantId}\\\" -d \\\"\\\"\\n                    \\\"\\\"\\\"\'\'\'\\n              def resData = readJSON text: \'\'\'\\\"\\\"\\\"${result}\\\"\\\"\\\"\'\'\'\\n              if(resData.code != 0){\\n                error \\\"调用制品库服务查询扫描结果报错，报错信息：${resData.msg}\\\"\\n              }\\n              proxy = resData.data.externalUrl\\n\\n            }else{\\n              if(language.startsWith(\'java\')){\\n                proxy = \\\"${env.nexusUrl}/repository/proxy-maven/\\\"\\n              }else if(language.startsWith(\'node\')){\\n                proxy = \'${env.nexusUrl}1/repository/proxy-npm/\'\\n              }else if(language.startsWith(\'python\')){\\n                proxy = \'${env.nexusUrl}/repository/proxy-pypi/\'\\n              }else if(language.startsWith(\'go\')){\\n                proxy = \'${env.nexusUrl}/repository/proxy-go/\'\\n              }\\n            }\\n            if(language.startsWith(\'java\')){\\n              writeFile encoding: \\\"utf-8\\\", file: \\\"settings.xml\\\", text: \'\'\'\\\"\\\"\\\"<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n            <settings\\n                xmlns=\\\"http://maven.apache.org/SETTINGS/1.0.0\\\"\\n                xmlns:xsi=\\\"http://www.w3.org/2001/XMLSchema-instance\\\"\\n            xsi:schemaLocation=\\\"http://maven.apache.org/SETTINGS/1.0.0 http://maven.apache.org/xsd/settings-1.0.0.xsd\\\">\\n                <localRepository>/root/.m2/repository</localRepository>\\n                <pluginGroups></pluginGroups>\\n                <proxies></proxies>\\n                <servers>\\n                </servers>\\n                <mirrors>\\n                    <mirror>\\n                        <id>public</id>\\n                        <mirrorOf>*</mirrorOf>\\n                        <name>central-repo</name>\\n                        <url>${proxy}</url>\\n                    </mirror>\\n                </mirrors>\\n                <profiles>\\n                    <profile>\\n                        <id>central-repo</id>\\n                        <repositories>\\n                            <repository>\\n                                <id>public</id>\\n                                <name>central-repo</name>\\n                                <url>http://zzzzzz/central</url>\\n                                <releases>\\n                                    <enabled>true</enabled>\\n                                </releases>\\n                                <snapshots>\\n                                    <enabled>true</enabled>\\n                                </snapshots>\\n                            </repository>\\n                        </repositories>\\n                    </profile>\\n                </profiles>\\n                <activeProfiles>\\n                    <activeProfile>central-repo</activeProfile>\\n                </activeProfiles>\\n            </settings>\\n                \\\"\\\"\\\"\'\'\'\\n              sh \'\'\'\\\"\\\"\\\"\\n                mkdir -p /root/.m2\\n                mv settings.xml /root/.m2/settings.xml\\n                \\\"\\\"\\\"\'\'\'\\n            }else if(language.startsWith(\'node\')){\\n              sh \'\'\'\\\"\\\"\\\"\\n                npm config set sass_binary_site=${env.nexusUrl}/repository/node-sass\\n                npm config set registry ${proxy}\\n                \\\"\\\"\\\"\'\'\'\\n            }else if(language.startsWith(\'python\')){\\n              sh \'\'\'\\\"\\\"\\\"\\n                pip config set global.index-url ${proxy}\\n                pip config set install.trusted-host ${proxy}\\n                \\\"\\\"\\\"\'\'\'\\n            }else if(language.startsWith(\'go\')){\\n              sh \'\'\'\\\"\\\"\\\"\\n                go env -w GO111MODULE=on\\n                go env -w GOPROXY=${proxy}\\n                \\\"\\\"\\\"\'\'\'\\n            }\\n\\n          }\"},\"key\":\"scriptBlock\"}]}]}]},{\"name\":\"代码克隆\",\"branches\":[{\"name\":\"default\",\"steps\":[{\"name\":\"subsystemClone\",\"stepName\":\"代码克隆\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码克隆\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.branch}\\\"\"},\"key\":\"subSystemBranch\"}]}]}]},{\"name\":\"依赖分析\",\"branches\":[{\"name\":\"default\",\"steps\":[{\"name\":\"script\",\"stepName\":\"依赖分析\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"echo \'依赖分析\'\\n          if(env.deepAnalysis == \'true\'){\\n            dependAnsysial(stepName: \'依赖检测分析\', dependLanguage: \'\', scanPath: \\\"${env.scanPath}\\\", extend: \'\', deepAnalysis: true, doorFlag: false)\\n          }else{\\n            dependAnsysial(stepName: \'依赖检测分析\', dependLanguage: \'\', scanPath: \\\"${env.scanPath}\\\", extend: \'\', deepAnalysis: false, doorFlag: false)\\n          }\"},\"key\":\"scriptBlock\"}]}]}]}]}}', 'pipeline {\n  agent {\n    kubernetes {\n      cloud \"${env.runCluster}\"\n      defaultContainer \'maven\'\n      yaml \'\'\'\napiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: jnlp\n    image: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'获取变量\') {\n      steps {\n        script {\n          echo \'获取依赖仓库\'\n          //通过依赖分析接口获取环境变量\n          if(deepAnalysis == \'true\'){\n            def proxy = \'\'\n            if(repoId != \'-\'){\n              def result = sh returnStdout: true ,script: \"\"\"\n                    curl -X GET \"${env.repositorySvcUrl}/api/repository/detail?id=${repoId}\" -H \"accept: */*\" -H \"Amp-Organ-Id: ${env.tenantId}\" -d \"\"\n                    \"\"\"\n              def resData = readJSON text: \"\"\"${result}\"\"\"\n              if(resData.code != 0){\n                error \"调用制品库服务查询扫描结果报错，报错信息：${resData.msg}\"\n              }\n              proxy = resData.data.externalUrl\n\n            }else{\n              if(language.startsWith(\'java\')){\n                proxy = \"${env.nexusUrl}/repository/proxy-maven/\"\n              }else if(language.startsWith(\'node\')){\n                proxy = \'${env.nexusUrl}1/repository/proxy-npm/\'\n              }else if(language.startsWith(\'python\')){\n                proxy = \'${env.nexusUrl}/repository/proxy-pypi/\'\n              }else if(language.startsWith(\'go\')){\n                proxy = \'${env.nexusUrl}/repository/proxy-go/\'\n              }\n            }\n            if(language.startsWith(\'java\')){\n              writeFile encoding: \"utf-8\", file: \"settings.xml\", text: \"\"\"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n            <settings\n                xmlns=\"http://maven.apache.org/SETTINGS/1.0.0\"\n                xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n            xsi:schemaLocation=\"http://maven.apache.org/SETTINGS/1.0.0 http://maven.apache.org/xsd/settings-1.0.0.xsd\">\n                <localRepository>/root/.m2/repository</localRepository>\n                <pluginGroups></pluginGroups>\n                <proxies></proxies>\n                <servers>\n                </servers>\n                <mirrors>\n                    <mirror>\n                        <id>public</id>\n                        <mirrorOf>*</mirrorOf>\n                        <name>central-repo</name>\n                        <url>${proxy}</url>\n                    </mirror>\n                </mirrors>\n                <profiles>\n                    <profile>\n                        <id>central-repo</id>\n                        <repositories>\n                            <repository>\n                                <id>public</id>\n                                <name>central-repo</name>\n                                <url>http://zzzzzz/central</url>\n                                <releases>\n                                    <enabled>true</enabled>\n                                </releases>\n                                <snapshots>\n                                    <enabled>true</enabled>\n                                </snapshots>\n                            </repository>\n                        </repositories>\n                    </profile>\n                </profiles>\n                <activeProfiles>\n                    <activeProfile>central-repo</activeProfile>\n                </activeProfiles>\n            </settings>\n                \"\"\"\n              sh \"\"\"\n                mkdir -p /root/.m2\n                mv settings.xml /root/.m2/settings.xml\n                \"\"\"\n            }else if(language.startsWith(\'node\')){\n              sh \"\"\"\n                npm config set sass_binary_site=${env.nexusUrl}/repository/node-sass\n                npm config set registry ${proxy}\n                \"\"\"\n            }else if(language.startsWith(\'python\')){\n              sh \"\"\"\n                pip config set global.index-url ${proxy}\n                pip config set install.trusted-host ${proxy}\n                \"\"\"\n            }else if(language.startsWith(\'go\')){\n              sh \"\"\"\n                go env -w GO111MODULE=on\n                go env -w GOPROXY=${proxy}\n                \"\"\"\n            }\n\n          }\n        }\n\n      }\n    }\n\n    stage(\'代码克隆\') {\n      steps {\n        subsystemClone(stepName: \'代码克隆\', subSystemBranch: \"${env.branch}\")\n      }\n    }\n\n    stage(\'依赖分析\') {\n      steps {\n        script {\n          echo \'依赖分析\'\n          if(env.deepAnalysis == \'true\'){\n            dependAnsysial(stepName: \'依赖检测分析\', dependLanguage: \'\', scanPath: \"${env.scanPath}\", extend: \'\', deepAnalysis: true, doorFlag: false)\n          }else{\n            dependAnsysial(stepName: \'依赖检测分析\', dependLanguage: \'\', scanPath: \"${env.scanPath}\", extend: \'\', deepAnalysis: false, doorFlag: false)\n          }\n        }\n\n      }\n    }\n\n  }\n}', 0, 0, '2024-09-30 09:56:05', '2024-11-14 11:23:28', 1, 1, '0', NULL, NULL);
INSERT INTO `devops_jenkinsfile` VALUES (10, 10, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"name\":\"获取元数据\",\"branches\":[{\"name\":\"default\",\"steps\":[{\"name\":\"script\",\"stepName\":\"获取元数据\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"echo \'获取元数据\'\\n          //获取需要回滚的环境信息buildId的信息\\n          result = sh returnStdout: true ,script: \'\'\'\\\"\\\"\\\"\\n            curl -X GET \\\"${env.pipelineSvcUrl}/devops/buildDeploy/envMap?buildId=${env.rollbackBuildId}\\\" -H \\\"accept: */*\\\" -d \\\"\\\"\\n            \\\"\\\"\\\"\'\'\'\\n          resData = readJSON text: \'\'\'\\\"\\\"\\\"${result}\\\"\\\"\\\"\'\'\'\\n          if(resData.code != 0 ){\\n            echo \\\"调用流水线服务报错，报错信息：${resData.msg}\\\"\\n            error \\\"调用流水线服务报错，报错信息：${resData.msg}\\\"\\n          }\\n          map = resData.data\\n          map.each{ data ->\\n          echo \\\"${data.key} : ${data.value}\\\"\\n          env[data.key] = data.value\\n        }\"},\"key\":\"scriptBlock\"}]}]}]},{\"name\":\"部署应用\",\"branches\":[{\"name\":\"default\",\"steps\":[{\"name\":\"script\",\"stepName\":\"部署应用\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"echo \'部署应用\'\\n        //判断是什么部署\\n        echo \\\"${env.deployType}\\\"\\n        if(env.deployType == \'主机部署\'){\\n          def map = [:]\\n          map.stepName = \'主机部署回滚\'\\n          map.deployEnv = env.deployEnv\\n          map.deployHost = env.deployHost\\n          map.remote_command = env.remote_command\\n          if(env.rawDeployProduct){\\n            map.fileFlag = true\\n            map.fileSource = \'1\'\\n            map.rawDeployProduct = env.rawDeployProduct\\n          }else{\\n            map.fileFlag = false\\n          }\\n          if(env.configRepo){\\n            map.configRepo = env.configRepo\\n            map.configEnv = env.configRepoEnv\\n            map.configPath = env.configRepoPath\\n            configRepo(map)\\n          }\\n          hostDeployFun_v1(map)\\n        }else if(env.deployType == \'sql部署\'){\\n          def map = [:]\\n          map.stepName = \'sql部署\'\\n          \\n          if(env.configRepo){\\n            map.configRepo = env.configRepo\\n            map.configEnv = env.configRepoEnv\\n            map.configPath = env.configRepoPath\\n            map.configRepoCommitId = env.configRepoCommitId\\n            configRepo(map)\\n          }\\n          \\n          map.deployEnv = env.deployEnv\\n          map.databeseType = env.databeseType\\n          map.databaseId = env.database\\n          map.configRepo = env.configRepo\\n          map.configEnv = env.configRepoEnv\\n          map.configPath = env.configPath\\n          databaseExec(map)\\n        }else if(env.deployType == \'Kubernetes部署\'){\\n          def map = [:]\\n          map.stepName = \'Kubernetes部署\'\\n          map.deployEnv = env.deployEnv\\n          map.startParamName_deployEnv = \'\'\\n          map.deployCluster = env.deployHost\\n          map.startParamName_deployCluster = \'\'\\n          map.deployPath = env.deployPath\\n\\n          if(env.commitId){\\n            map.gitRepo = env.gitRepo\\n            map.branch = env.branch\\n            map.gitCommitId = env.commitId\\n            map.gitPath = env.gitPath\\n            if(env.serverId){\\n                map.serviceType = \'1\'\\n                map.serverId = env.serverId\\n                map.gitlabId = env.gitlabId + \\\"|\\\" + env.gitRepo\\n            }else{\\n                map.gitUrl = env.gitRepo\\n            }\\n            gitClone(map)\\n          }\\n\\n          if(env.configRepo){\\n            map.configRepo = env.configRepo\\n            map.configEnv = env.configRepoEnv\\n            map.configPath = env.configRepoPath\\n            map.configRepoCommitId = env.configRepoCommitId\\n            configRepo(map)\\n          }\\n          k8sDeployFun(map)\\n        }else if(env.deployType == \'Kubernetes镜像更新\'){\\n          def map = [:]\\n          map.stepName = \'Kubernetes镜像更新\'\\n          map.deployEnv = env.deployEnv\\n          map.startParamName_deployEnv = \'\'\\n          map.deployCluster = env.deployHost\\n          map.startParamName_deployCluster = \'\'\\n          map.namespace = env.namespace\\n          map.startParamName_namespace = \'\'\\n          map.deployName = env.deployName\\n          map.imageSource = \'2\'\\n          map.dockerDeployProduct = env.dockerDeployProduct\\n          map.startParamName_dockerDeployProduct = \'\'\\n          k8sApplicationDeployFun_v1(map)\\n        }\"},\"key\":\"scriptBlock\"}]}]}]}]}}', 'pipeline {\n  agent {\n    kubernetes {\n      cloud \"${env.runCluster}\"\n      defaultContainer \'maven\'\n      yaml \'\'\'\napiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: jnlp\n    image: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'获取元数据\') {\n      steps {\n        script {\n          echo \'获取元数据\'\n          //获取需要回滚的环境信息buildId的信息\n          result = sh returnStdout: true ,script: \"\"\"\n            curl -X GET \"${env.pipelineSvcUrl}/devops/buildDeploy/envMap?buildId=${env.rollbackBuildId}\" -H \"accept: */*\" -d \"\"\n            \"\"\"\n          resData = readJSON text: \"\"\"${result}\"\"\"\n          if(resData.code != 0 ){\n            echo \"调用流水线服务报错，报错信息：${resData.msg}\"\n            error \"调用流水线服务报错，报错信息：${resData.msg}\"\n          }\n          map = resData.data\n          map.each{ data ->\n          echo \"${data.key} : ${data.value}\"\n          env[data.key] = data.value\n        }\n      }\n\n    }\n  }\n\n  stage(\'部署应用\') {\n    steps {\n      script {\n        echo \'部署应用\'\n        //判断是什么部署\n        echo \"${env.deployType}\"\n        if(env.deployType == \'主机部署\'){\n          def map = [:]\n          map.stepName = \'主机部署回滚\'\n          map.deployEnv = env.deployEnv\n          map.deployHost = env.deployHost\n          map.remote_command = env.remote_command\n          if(env.rawDeployProduct){\n            map.fileFlag = true\n            map.fileSource = \'1\'\n            map.rawDeployProduct = env.rawDeployProduct\n          }else{\n            map.fileFlag = false\n          }\n          if(env.configRepo){\n            map.configRepo = env.configRepo\n            map.configEnv = env.configRepoEnv\n            map.configPath = env.configRepoPath\n            configRepo(map)\n          }\n          hostDeployFun_v1(map)\n        }else if(env.deployType == \'sql部署\'){\n          def map = [:]\n          map.stepName = \'sql部署\'\n\n          if(env.configRepo){\n            map.configRepo = env.configRepo\n            map.configEnv = env.configRepoEnv\n            map.configPath = env.configRepoPath\n            map.configRepoCommitId = env.configRepoCommitId\n            configRepo(map)\n          }\n\n          map.deployEnv = env.deployEnv\n          map.databeseType = env.databeseType\n          map.databaseId = env.database\n          map.configRepo = env.configRepo\n          map.configEnv = env.configRepoEnv\n          map.configPath = env.configPath\n          databaseExec(map)\n        }else if(env.deployType == \'Kubernetes部署\'){\n          def map = [:]\n          map.stepName = \'Kubernetes部署\'\n          map.deployEnv = env.deployEnv\n          map.startParamName_deployEnv = \'\'\n          map.deployCluster = env.deployHost\n          map.startParamName_deployCluster = \'\'\n          map.deployPath = env.deployPath\n\n          if(env.commitId){\n            map.gitRepo = env.gitRepo\n            map.branch = env.branch\n            map.gitCommitId = env.commitId\n            map.gitPath = env.gitPath\n            if(env.serverId){\n              map.serviceType = \'1\'\n              map.serverId = env.serverId\n              map.gitlabId = env.gitlabId + \"|\" + env.gitRepo\n            }else{\n              map.gitUrl = env.gitRepo\n            }\n            gitClone(map)\n          }\n\n          if(env.configRepo){\n            map.configRepo = env.configRepo\n            map.configEnv = env.configRepoEnv\n            map.configPath = env.configRepoPath\n            map.configRepoCommitId = env.configRepoCommitId\n            configRepo(map)\n          }\n          k8sDeployFun(map)\n        }else if(env.deployType == \'Kubernetes镜像更新\'){\n          def map = [:]\n          map.stepName = \'Kubernetes镜像更新\'\n          map.deployEnv = env.deployEnv\n          map.startParamName_deployEnv = \'\'\n          map.deployCluster = env.deployHost\n          map.startParamName_deployCluster = \'\'\n          map.namespace = env.namespace\n          map.startParamName_namespace = \'\'\n          map.deployName = env.deployName\n          map.imageSource = \'2\'\n          map.dockerDeployProduct = env.dockerDeployProduct\n          map.startParamName_dockerDeployProduct = \'\'\n          k8sApplicationDeployFun_v1(map)\n        }\n      }\n\n    }\n  }\n\n}\n}', 0, 0, '2023-07-21 11:07:37', '2024-08-08 15:33:40', 1, 1, '0', NULL, NULL);
