INSERT INTO `devops_jenkinsfile` VALUES (3343230075579256832, 3343230074555846656, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"branches\":[{\"steps\":[{\"stepName\":\"代码克隆\",\"name\":\"subsystemClone\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码克隆\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${branch}\\\"\"},\"key\":\"startParamName_subSystemBranch\"},{\"value\":{\"isLiteral\":true,\"value\":\"19|master\"},\"key\":\"subSystemBranch\"}]}],\"name\":\"default\"}],\"name\":\"代码克隆\"},{\"branches\":[{\"steps\":[{\"stepName\":\"代码构建\",\"name\":\"codeBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码构建\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"node14.17.6\"},\"key\":\"language\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven3.5\"},\"key\":\"buildTool\"},{\"value\":{\"isLiteral\":true,\"value\":\"rm -rf  package-lock.json\\nrm -rf yarn.lock\\nrm -rf node_modules\\nnpm install --registry=http://192.168.15.107:32481/repository/ahzx/\\nnpm run build:prod\"},\"key\":\"command\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"file_setting\"},{\"value\":{\"isLiteral\":true,\"value\":\"17|http://192.168.15.107:32481/repository/ahzx\"},\"key\":\"proxy\"}]},{\"stepName\":\"执行Shell命令\",\"name\":\"shCommand\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"执行Shell命令\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"ls -l\\n\"},\"key\":\"shCommand\"}]}],\"name\":\"default\"}],\"name\":\"代码构建\"},{\"branches\":[{\"steps\":[{\"stepName\":\"通用代码扫描\",\"name\":\"sonarScanByParams\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"通用代码扫描\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\".\"},\"key\":\"scanPath\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"excludePath\"},{\"value\":{\"isLiteral\":true,\"value\":\"2815979210091364352\"},\"key\":\"sonarProject\"},{\"value\":{\"isLiteral\":true,\"value\":\"0\"},\"key\":\"sonarGate\"},{\"value\":{\"isLiteral\":true,\"value\":false},\"key\":\"waitGate\"},{\"value\":{\"isLiteral\":true,\"value\":false},\"key\":\"addScan\"},{\"value\":{\"isLiteral\":true,\"value\":\"33ad2472\"},\"key\":\"compareBranch\"}]}],\"name\":\"default\"}],\"name\":\"代码扫描\"},{\"branches\":[{\"steps\":[{\"stepName\":\"依赖检测分析\",\"name\":\"dependAnsysial\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"依赖检测分析\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"js\"},\"key\":\"dependLanguage\"},{\"value\":{\"isLiteral\":true,\"value\":\".\"},\"key\":\"scanPath\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"extend\"},{\"value\":{\"isLiteral\":true,\"value\":false},\"key\":\"deepAnalysis\"},{\"value\":{\"isLiteral\":true,\"value\":false},\"key\":\"doorFlag\"}]}],\"name\":\"defau