ame: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      steps {\n        subsystemClone(stepName: \'代码克隆\', startParamName_subSystemBranch: \"${branch}\", subSystemBranch: \'23|master\')\n      }\n    }\n\n    stage(\'代码构建\') {\n      steps {\n        codeBuild(stepName: \'代码构建\', language: \'node14.17.6\', buildTool: \'\', command: \'\'\'rm -rf  package-lock.json\nrm -rf yarn.lock\nrm -rf node_modules\nnpm install --registry=http://192.168.15.107:32481/repository/ahzx/\nnpm run build:prod\ntar -zcvf dist.tar.gz dist\'\'\', file_setting: \'\', proxy: \'\')\n      }\n    }\n\n    stage(\'通用制品上传\') {\n      steps {\n        universalProductUpload(stepName: \'通用制品上传\', startParamName_rawRepository: \"${rawRepository}\", startParamName_version: \"${version}\", file: \'dist.tar.gz\', productName: \'\')\n      }\n    }\n\n  }\n}', 0, 0, '2024-05-23 15:21:15', '2024-05-23 15:29:45', 3267292550326501376, 3267292550326501376, '0', NULL, NULL);
