INSERT INTO `devops_jenkinsfile` VALUES (3396940660166467584, 3396940660082581504, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"branches\":[{\"steps\":[{\"stepName\":\"制品晋级-安徽征信\",\"name\":\"productPromotion_ahzx\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"制品晋级-安徽征信\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"raw\"},\"key\":\"productType\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${rawRepository}\\\"\"},\"key\":\"startParamName_rawRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"startParamName_dockerRepository\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${version}\\\"\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${promotionPackage}\\\"\"},\"key\":\"startParamName_promotionPackage\"},{\"value