INSERT INTO `devops_jenkinsfile` VALUES (3396972121221341184, 3396972121137455104, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"branches\":[{\"steps\":[{\"stepName\":\"代码克隆\",\"name\":\"gitClone\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码克隆\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"1\"},\"key\":\"serviceType\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"gitUrl\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"gitCredentialId\"},{\"value\":{\"isLiteral\":true,\"value\":\"1\"},\"key\":\"serverId\"},{\"value\":{\"isLiteral\":true,\"value\":\"119|http://192.168.15.107:32480/ahc-devops/devops-workflow-web.git\"},\"key\":\"gitlabId\"},{\"value\":{\"isLiteral\":true,\"value\":\"master\"},\"key\":\"branch\"},{\"value\":{\"isLiteral\":true,\"value\"