INSERT INTO `devops_jenkinsfile` VALUES (3445235396457451520, 3445235396356788224, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"branches\":[{\"steps\":[{\"stepName\":\"代码克隆\",\"name\":\"subsystemClone\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码克隆\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${branch}\\\"\"},\"key\":\"startParamName_subSystemBranch\"},{\"value\":{\"isLiteral\":true,\"value\":\"167|dev\"},\"key\":\"subSystemBranch\"}]}],\"name\":\"default\"}],\"name\":\"代码克隆\"},{\"branches\":[{\"steps\":[{\"stepName\":\"代码构建\",\"name\":\"codeBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码构建\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"node12.16.1\"},\"key\":\"language\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"buildTool\"},{\"value\":{\"isLiteral\":true,\"value\":\"cd ruoyi-ui\\nrm -rf  package-lock.json\\nrm -rf yarn.lock\\nrm -rf node_modules\\nnpm install --registry=http://192.168.15.107:32481/repository/ahzx/ --ignore-scripts\\nnpm install quill  --registry=http://192.168.15.107:32481/repository/ahzx/ --ignore-scripts --save\\nnpm run build:prod\\n\\ntar -zcvf aq-ecsc3.tar.gz aq-ecsc3\"},\"key\":\"command\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"file_setting\"},{\"value\":{\"isLiteral\":true,\"value\":\"17|http://192.168.15.107:32481/repository/ahzx\"},\"key\":\"proxy\"}]}],\"name\":\"default\"}],\"name\":\"代码构建\"},{\"branches\":[{\"steps\":[{\"stepName\":\"通用制品上传\",\"name\":\"universalProductUpload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"通用制品上传\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${rawRepository}\\\"\"},\"key\":\"startParamName_rawRepository\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${version}\\\"\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"ruoyi-ui/aq-ecsc3.tar.gz\"},\"key\":\"file\"},{\"value\":{\"isLiteral\":true,\"value\":\"aq-ecsc3.tar.gz\"},\"key\":\"productName\"}]}],\"name\":\"default\"}],\"name\":\"通用制品上传\"}]}}', 'pipeline {\n  agent {\n    kubernetes {\n      cloud \"${env.runCluster}\"\n      defaultContainer \'maven\'\n      yaml \'\'\'\napiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: jnlp\n    image: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n      - mountPath: /root/.m2/settings.xml\n        name: config\n        subPath: settings.xml\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      steps {\n        subsystemClone(stepName: \'代码克隆\', startParamName_subSystemBranch: \"${branch}\", subSystemBranch: \'167|dev\')\n      }\n    }\n\n    stage(\'代码构建\') {\n      steps {\n        codeBuild(stepName: \'代码构建\', language: \'node12.16.1\', buildTool: \'\', command: \'\'\'cd ruoyi-ui\nrm -rf  package-lock.json\nrm -rf yarn.lock\nrm -rf node_modules\nnpm install --registry=http://192.168.15.107:32481/repository/ahzx/ --ignore-scripts\nnpm install quill  --registry=http://192.168.15.107:32481/repository/ahzx/ --ignore-scripts --save\nnpm run build:prod\n\ntar -zcvf aq-ecsc3.tar.gz aq-ecsc3\'\'\', file_setting: \'\', proxy: \'17|http://192.168.15.107:32481/repository/ahzx\')\n      }\n    }\n\n    stage(\'通用制品上传\') {\n      steps {\n        universalProductUpload(stepName: \'通用制品上传\', startParamName_rawRepository: \"${rawRepository}\", startParamName_version: \"${version}\", file: \'ruoyi-ui/aq-ecsc3.tar.gz\', productName: \'aq-ecsc3.tar.gz\')\n      }\n    }\n\n  }\n}', 0, 0, '2024-07-04 18:13:52', '2024-07-04 18:18:17', 3271117585803313152, 3271117585803313152, '0', NULL, NULL);
