ld(stepName: \'代码构建\', language: \'java8\', buildTool: \'maven3.5\', command: \'\'\'pwd\nls\nmvn clean package -Dmaven.test.skip=true\'\'\', file_setting: \'/minio/application/0c59b8f1cc22c48cf8a7d0a82b714a77.xml\', proxy: \'\')\n      }\n    }\n\n    stage(\'推送到制品仓库\') {\n      environment {\n        stageName = \'推送到制品仓库\'\n      }\n      steps {\n        universalProductUploadFun(stepName: \'通用制品上传\', rawRepository: \'\', startParamName_rawRepository: \"${rawRepository}\", tyzpsc_btn_1: true, tyzpsc_btn1: \'选择已有\', version: \'\', str_version: \'\', startParamName_version: \"${version}\", tyzpsc_btn_2: true, tyzpsc_btn2: \'选择已有\', file: \"${packageName}/target/*.jar\", productName: \'\')\n      }\n    }\n\n  }\n}', 0, 0, '2024-07-10 16:31:07', '2024-07-17 17:09:10', 3271113249245298688, 3271113249245298688, '0', NULL, NULL);
