age}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n      - mountPath: /root/.m2/settings.xml\n        name: config\n        subPath: settings.xml\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      steps {\n        gitClone(stepName: \'代码克隆\', serviceType: \'1\', gitUrl: \'\', gitCredentialId: \'\', serverId: \'1\', gitlabId: \'152|http://192.168.15.107:32480/ahc-bzdb/ahc-bzdb.git\', branch: \'master\', startParamName_branch: \'\', dmkl_btn1: \'设置为变量\', dmkl_btn_1: \'\', gitPath: \'\')\n      }\n    }\n\n    stage(\'代码构建\') {\n      steps {\n        codeBuild(stepName: \'代码构建\', language: \'java8\', buildTool: \'maven3.8\', command: \'\'\'mvn clean package\n\'\'\', file_setting: \'\', proxy: \'\')\n        shCommand(stepName: \'执行Shell命令\', shCommand: \'\'\'echo \\\'hello\\\'\nsleep 3600\'\'\')\n      }\n    }\n\n    stage(\'制品上传\') {\n      steps {\n        universalProductUpload(stepName: \'通用制品上传\', startParamName_rawRepository: \"${rawRepository}\", startParamName_version: \"${version}\", file: \'target\', productName: \'\')\n      }\n    }\n\n  }\n}', 0, 0, '2024-09-19 14:58:27', '2024-09-20 08:57:29', 3267307713708539904, 3267307713708539904, '0', NULL, NULL);
INSERT INTO `devops_jenkinsfile` VALUES (3556666350989443072, 3556666349513048064, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"branches\":[{\"steps\":[{\"stepName\":\"配置克隆\",\"name\":\"configRepo\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"配置克隆\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"1|151\"},\"key\":\"configRepo\"},{\"value\":{\"isLiteral\":true,\"value\":\"main\"},\"key\":\"configEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"config/\"},\"key\":\"configPath\"}]}],\"name\":\"default\"}],\"name\":\"配置克隆\"},{\"branches\":[{\"steps\":[{\"stepName\":\"执行Shell命令\",\"name\":\"shCommand\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"执行Shell命令\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"cat ./config/deploy/devops-app-build-prod.sh\\n\\nchmod +x ./config/deploy/devops-app-build-prod.sh\\nbash -x ./config/deploy/devops-app-build-prod.sh ${version} ${imageName} ${dockerRepository}\"},\"key\":\"shCommand\"}]},{\"stepName\":\"执行Groovy脚本\",\"name\":\"script\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"echo \'执行Groovy脚本\'\\n          def result = sh returnStdout: true ,script: \'\'\'\\\"\\\"\\\"\\n          curl -X GET \\\"${env.repositorySvcUrl}/api/repository/detail?id=${env.repository}\\\" -H \\\"accept: */*\\\" -d \\\"\\\"\\n          \\\"\\\"\\\"\'\'\'\\n          def resData = readJSON text: \'\'\'\\\"\\\"\\\"${result}\\\"\\\"\\\"\'\'\'\\n          if(resData.code != 0){\\n            error \\\"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\\\"\\n          }\\n\\n          env.harborUrl=resData.data.url.replace(\\\"https://\\\",\\\"\\\")\\n          env.tagert = \\\"${version}\\\"\\n          echo \\\"版本：${env.tagert}\\\"\"},\"key\":\"scriptBlock\"}]}],\"name\":\"default\"}],\"name\":\"镜像打包\"},{\"branches\":[{\"steps\":[{\"stepName\":\"Kubernetes镜像更新\",\"name\":\"k8sApplicationDeploy_v1\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"Kubernetes镜像更新\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${deployEnv}\\\"\"},\"key\":\"startParamName_deployEnv\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${deployCluster}\\\"\"},\"key\":\"startParamName_deployCluster\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${namespace}\\\"\"},\"key\":\"startParamName_namespace\"},{\"value\":{\"isLiteral\":true,\"value\":\"devops-app\"},\"key\":\"deployName\"},{\"value\":{\"isLiteral\":true,\"value\":\"1\"},\"key\":\"imageSource\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"startParamName_dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"startParamName_dockerDeployProduct\"}]}],\"name\":\"default\"}],\"name\":\"镜像更新\"}]}}', 'pipeline {\n  agent {\n    kubernetes {\n      cloud \"${env.runCluster}\"\n      defaultContainer \'maven\'\n      yaml \'\'\'\napiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: jnlp\n    image: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n      - mountPath: /root/.m2/settings.xml\n        name: config\n        subPath: settings.xml\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'配置克隆\') {\n      steps {\n        configRepo(stepName: \'配置克隆\', configRepo: \'1|151\', configEnv: \'main\', configPath: \'config/\')\n      }\n    }\n\n    stage(\'镜像打包\') {\n      steps {\n        shCommand(stepName: \'执行Shell命令\', shCommand: \'\'\'cat ./config/deploy/devops-app-build-prod.sh\n\nchmod +x ./config/deploy/devops-app-build-prod.sh\nbash -x ./config/deploy/devops-app-build-prod.sh ${version} ${imageName} ${dockerRepository}\'\'\')\n        script {\n          echo \'执行Groovy脚本\'\n          def result = sh returnStdout: true ,script: \"\"\"\n          curl -X GET \"${env.repositorySvcUrl}/api/repository/detail?id=${env.repository}\" -H \"accept: */*\" -d \"\"\n          \"\"\"\n          def resData = readJSON text: \"\"\"${result}\"\"\"\n          if(resData.code != 0){\n            error \"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\"\n          }\n\n          env.harborUrl=resData.data.url.replace(\"https://\",\"\")\n          env.tagert = \"${version}\"\n          echo \"版本：${env.tagert}\"\n        }\n\n      }\n    }\n\n    stage(\'镜像更新\') {\n      steps {\n        k8sApplicationDeploy_v1(stepName: \'Kubernetes镜像更新\', startParamName_deployEnv: \"${deployEnv}\", startParamName_deployCluster: \"${deployCluster}\", startParamName_namespace: \"${namespace}\", deployName: \'devops-app\', imageSource: \'1\', startParamName_dockerRepository: \'\', startParamName_version: \'\', startParamName_dockerDeployProduct: \'\')\n      }\n    }\n\n  }\n}', 0, 0, '2024-09-19 15:10:34', '2024-11-07 15:56:51', 3267307713708539904, 3267307713708539904, '0', NULL, NULL);
