 }\n\n    stage(\'推送到制品仓库\') {\n      environment {\n        stageName = \'推送到制品仓库\'\n      }\n      steps {\n        universalProductUploadFun(stepName: \'通用制品上传\', rawRepository: \'\', startParamName_rawRepository: \"${rawRepository}\", tyzpsc_btn_1: true, tyzpsc_btn1: \'选择已有\', version: \'\', str_version: \'\', startParamName_version: \"${version}\", tyzpsc_btn_2: true, tyzpsc_btn2: \'选择已有\', file: \'target/ahzx-icbc-jft.war\', productName: \'\')\n      }\n    }\n\n  }\n}', 0, 0, '2024-09-23 15:03:14', '2024-12-19 09:48:17', 1, 3267292550326501376, '0', NULL, NULL);
