"},\"key\":\"startParamName_branch\"},{\"value\":{\"isLiteral\":true,\"value\":\"设置为变量\"},\"key\":\"dmkl_btn1\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"dmkl_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"gitPath\"}]}],\"name\":\"default\"}],\"name\":\"代码克隆\"},{\"branches\":[{\"steps\":[{\"stepName\":\"查询目录树创建打包目录\",\"name\":\"shCommand\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"查询目录树创建打包目录\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"ls -R\\nmkdir xmfmodelbuild\"},\"key\":\"shCommand\"}]},{\"stepName\":\"代码构建\",\"name\":\"codeBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码构建\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"java8_131\"},\"key\":\"language\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven3.8\"},\"key\":\"buildTool\"},{\"value\":{\"isLiteral\":true,\"value\":\"find src/com -name \\\"*.java\\\" |xargs javac -d xmfmodelbuild -cp \\\"WebContent/WEB-INF/lib/*\\\"\\n\"},\"key\":\"command\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"file_setting\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"proxy\"}]},{\"stepName\":\"war包构建\",\"name\":\"shCommand\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"war包构建\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"cp -r WebContent/* xmfmodelbuild/\\nls\\ncd xmfmodelbuild\\nls\\nmv com WEB-INF/com\\npwd\\nls\\njar cvfm ../xmfModel.war META-INF/MANIFEST.MF -C . WEB-INF -C . META-INF\"},\"key\":\"shCommand\"}]}],\"name\":\"default\"}],\"name\":\"代码构建\"},{\"branches\":[{\"steps\":[{\"stepName\":\"通用制品上传\",\"name\":\"universalProductUpload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"通用制品上传\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${rawRepository}\\\"\"},\"key\":\"startParamName_rawRepository\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${version}\\\"\"},\"key\":\"startParamName_version\"},{\"value\":