yEnv\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${deployCluster}\\\"\"},\"key\":\"startParamName_deployCluster\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${namespace}\\\"\"},\"key\":\"startParamName_namespace\"},{\"value\":{\"isLiteral\":true,\"value\":\"track-issues-svc-v2\"},\"key\":\"deployName\"},{\"value\":{\"isLiteral\":true,\"value\":\"1\"},\"key\":\"imageSource\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"startParamName_dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"startParamName_dockerDeployProduct\"}]}],\"name\":\"default\"}],\"name\":\"镜像更新\"}]}}', 'pipeline {\n  agent {\n    kubernetes {\n      cloud \"${env.runCluster}\"\n      defaultContainer \'maven\'\n      yaml \'\'\'\napiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: jnlp\n    image: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n      - mountPath: /root/.m2/settings.xml\n        name: config\n        subPath: settings.xml\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      steps {\n        gitClone(stepName: \'代码克隆\', serviceType: \'1\', gitUrl: \'\', gitCredentialId: \'\', serverId: \'1\', gitlabId: \'107|http://192.168.15.107:32480/ahc-devops/track-issues-svc-v2.git\', branch: \'\', startParamName_branch: \"${branch}\", dmkl_btn1: \'