INSERT INTO `devops_jenkinsfile` VALUES (3613341925550264320, 3613341925466378240, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"branches\":[{\"steps\":[{\"stepName\":\"代码克隆\",\"name\":\"gitClone\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码克隆\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"1\"},\"key\":\"serviceType\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"gitUrl\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"gitCredentialId\"},{\"value\":{\"isLiteral\":true,\"value\":\"1\"},\"key\":\"serverId\"},{\"value\":{\"isLiteral\":true,\"value\":\"324|http://192.168.15.107:32480/dcp/dcp.git\"},\"key\":\"gitlabId\"},{\"value\":{\"isLiteral\":true,\"value\":\"master\"},\"key\":\"branch\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"startParamName_branch\"},{\"value\":{\"isLiteral\":true,\"value\":\"设置为变量\"},\"key\":\"dmkl_btn1\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"dmkl_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"gitPath\"}]}],\"name\":\"default\"}],\"name\":\"代码克隆\"},{\"branches\":[{\"steps\":[{\"stepName\":\"代码构建\",\"name\":\"codeBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码构建\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"java8\"},\"key\":\"language\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven3.8\"},\"key\":\"buildTool\"},{\"value\":{\"isLiteral\":true,\"value\":\"mvn clean package -Dmaven.test.skip=true -B\\n\"},\"key\":\"command\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"file_setting\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"proxy\"}]}],\"name\":\"default\"}],\"name\":\"代码构建\"},{\"branches\":[{\"steps\":[{\"stepName\":\"通用制品上传\",\"name\":\"universalProductUpload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"通用制品上传\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${rawRepository}\\\"\"},\"key\":\"startParamName_rawRepository\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${version}\\\"\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"target/dcp.jar\"},\"key\":\"file\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"productName\"}]}],\"name\":\"default\"}],\"name\":\"制品上传\"}]}}', 'pipeline {\n  agent {\n    kubernetes {\n      cloud \"${env.runCluster}\"\n      defaultContainer \'maven\'\n      yaml \'\'\'\napiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: jnlp\n    image: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n      - mountPath: /root/.m2/settings.xml\n        name: config\n        subPath: settings.xml\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      steps {\n        gitClone(stepName: \'代码克隆\', serviceType: \'1\', gitUrl: \'\', gitCredentialId: \'\', serverId: \'1\', gitlabId: \'324|http://192.168.15.107:32480/dcp/dcp.git\', branch: \'master\', startParamName_branch: \'\', dmkl_btn1: \'设置为变量\', dmkl_btn_1: \'\', gitPath: \'\')\n      }\n    }\n\n    stage(\'代码构建\') {\n      steps {\n        codeBuild(stepName: \'代码构建\', language: \'java8\', buildTool: \'maven3.8\', command: \'\'\'mvn clean package -Dmaven.test.skip=true -B\n\'\'\', file_setting: \'\', proxy: \'\')\n      }\n    }\n\n    stage(\'制品上传\') {\n      steps {\n        universalProductUpload(stepName: \'通用制品上传\', startParamName_rawRepository: \"${rawRepository}\", startParamName_version: \"${version}\", file: \'target/dcp.jar\', productName: \'\')\n      }\n    }\n\n  }\n}', 0, 0, '2024-10-28 17:32:42', '2024-10-29 10:36:54', 3267292550326501376, 3267292550326501376, '0', NULL, NULL);
