INSERT INTO `devops_jenkinsfile` VALUES (3646578685495152640, 3646578685411266560, 0, '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"branches\":[{\"steps\":[{\"stepName\":\"代码克隆\",\"name\":\"subsystemClone\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码克隆\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${branch}\\\"\"},\"key\":\"startParamName_subSystemBranch\"},{\"value\":{\"isLiteral\":true,\"value\":\"314|dev\"},\"key\":\"subSystemBranch\"}]}],\"name\":\"default\"}],\"name\":\"代码克隆\"},{\"branches\":[{\"steps\":[{\"stepName\":\"代码构建\",\"name\":\"codeBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码构建\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"node12.16.1\"},\"key\":\"language\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"k