ath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      steps {\n        subsystemClone(stepName: \'代码克隆\', startParamName_subSystemBranch: \"${branch}\", subSystemBranch: \'314|dev\')\n      }\n    }\n\n    stage(\'代码构建\') {\n      steps {\n        codeBuild(stepName: \'代码构建\', language: \'node12.16.1\', buildTool: \'\', command: \'\'\'rm -rf  package-lock.json\nrm -rf yarn.lock\nrm -rf node_modules\nnpm install --registry=http://192.168.15.107:32481/repository/ahzx/ --ignore-scripts\nnpm install quill  --registry=http://192.168.15.107:32481/repository/ahzx/ --ignore-scripts --save\nnpm run build:test\nmv dist xzzx-web\ntar -zcvf xzzx-web.tar.gz xzzx-web\'\'\', file_setting: \'\', proxy: \'17|http://192.168.15.107:32481/repository/ahzx\')\n      }\n    }\n\n    stage(\'通用制品上传\') {\n      steps {\n        universalProductUpload(stepName: \'通用制品上传\', startParamName_rawRepository: \"${rawRepository}\", startParamName_version: \"${version}\", file: \'xzzx-web.tar.gz\', productName: \'xzzx-web.tar.gz\')\n      }\n    }\n\n  }\n}', 0, 0, '2024-11-20 15:50:27', '2024-11-20 15:54:57', 3271117585803313152, 3271117585803313152, '0', NULL, NULL);
