INSERT INTO `devops_jenkinsfile_stage_component` VALUES (4, 1008, '执行Shell命令', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"shCommand\":{\"default\":\"echo \'hello\'\",\"x-decorator\":\"FormItem\",\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"4j1x9xfxngz\",\"x-decorator-props\":{\"tooltip\":\"\",\"colon\":false},\"name\":\"shCommand\",\"x-validator\":[],\"x-component-props\":{\"style\":{\"height\":\"300px\"}},\"type\":\"string\",\"title\":\"Shell命令\",\"x-index\":0,\"required\":true}},\"x-designable-id\":\"y3tnduqdz29\"}}]', '{\"name\":\"shCommand\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"shCommand\"},\"key\":\"shCommand\"}],\"stepFunc\":\"shCommand\"}', '{\r\n	\"name\": \"sh\",\r\n	\"arguments\": [{\r\n		\"value\": {\r\n		  \"isLiteral\": true,\r\n          \"value\": \"$$SHELL\"\r\n		},\r\n		\"key\": \"script\"\r\n	}]\r\n}', '执行Shell命令', 1, 0, '2022-03-21 14:46:56', '2024-02-04 16:34:17', NULL, 1, 'shCommand', '0', '2', '2', 'def call(String  stepName,String command) {\n    //ceshi 22211\n    println(\"---${command}----\")\n    sh \"\"\"\n    ${command}\n    \"\"\"\n}\n\ndef call(def map){\n    call(map.stepName,map.shCommand)\n    echo env.endString\n\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (14, 1004, 'Maven制品上传', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"labelCol\":6,\"colon\":false},\"schema\":{\"type\":\"object\",\"properties\":{\"mvnDeployType\":{\"default\":\"1\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"w17ddj22fn4\",\"x-decorator-props\":{\"tooltip\":\"支持mvn deploy和通用上传方式\"},\"name\":\"mvnDeployType\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"上传方式\",\"x-index\":0,\"enum\":[{\"children\":[],\"label\":\"deploy\",\"value\":\"1\"},{\"children\":[],\"label\":\"通用上传\",\"value\":\"2\"}]},\"nexusUrl\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"ig7b7gqjnv3\",\"x-display\":\"none\",\"x-decorator-props\":{\"tooltip\":\"制品仓库地址\"},\"name\":\"nexusUrl\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  fetch(`${window.location.origin}/api/warehouse/api/repository/maven2?repositoryType=hosted`, {\\n    headers: { Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"|\\\" + k.url,\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [$deps.mvnDeployType])\\n\",\"state\":{\"visible\":\"{{$deps.mvnDeployType === \'1\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"mvnDeployType\",\"source\":\"mvnDeployType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"制品仓库\",\"x-index\":1,\"required\":true},\"group\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"qybm09iepjn\",\"x-decorator-props\":{\"tooltip\":\"项目组标识。支持输入字母、数字和连接符（减号和下划线），建议使用小写字母和连接符进行命名\"},\"name\":\"group\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.mvnDeployType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"mvnDeployType\",\"source\":\"mvnDeployType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"group\",\"x-index\":2,\"required\":true},\"artifacts\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"kdtawv2zpmq\",\"x-decorator-props\":{\"tooltip\":\"支持输入字母、数字和连接符（减号和下划线），建议使用小写字母和连接符进行命名\"},\"name\":\"artifacts\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.mvnDeployType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"mvnDeployType\",\"source\":\"mvnDeployType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"artifacts\",\"x-index\":3,\"required\":true},\"pomVersion\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"3fc86ta7074\",\"x-decorator-props\":{\"tooltip\":\"支持数字、字母、点号（.）、连接符（-）和下划线（_）。版本号应符合Maven的版本号规范，例如1.0.0、1.0-alpha、1.0-SNAPSHOT等\"},\"name\":\"pomVersion\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.mvnDeployType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"mvnDeployType\",\"source\":\"mvnDeployType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"version\",\"x-index\":4,\"required\":true},\"packaging\":{\"x-component\":\"Select\",\"x-designable-id\":\"l0fb3nfnpni\",\"x-decorator-props\":{\"tooltip\":\"包类型\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"packaging\",\"x-index\":5,\"enum\":[{\"children\":[],\"label\":\"jar\",\"value\":\"jar\"}],\"required\":true,\"default\":\"jar\",\"x-decorator\":\"FormItem\",\"name\":\"packaging\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.mvnDeployType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"mvnDeployType\",\"source\":\"mvnDeployType\",\"type\":\"any\"}]}},\"Classfier\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"glitf0orcnx\",\"x-decorator-props\":{},\"name\":\"Classfier\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.mvnDeployType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"mvnDeployType\",\"source\":\"mvnDeployType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"Classfier\",\"x-index\":6},\"pom\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Switch\",\"x-designable-id\":\"qooh6pc0gif\",\"x-decorator-props\":{\"tooltip\":\"是否生成pom.xml\"},\"name\":\"pom\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.mvnDeployType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"mvnDeployType\",\"source\":\"mvnDeployType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"生成pom\",\"x-index\":7},\"packPath\":{\"x-component\":\"Input\",\"x-designable-id\":\"8gpptzs4w0z\",\"x-decorator-props\":{\"tooltip\":\"待上传文件路径\"},\"description\":\"\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"文件路径\",\"x-index\":8,\"default\":\"target\",\"x-decorator\":\"FormItem\",\"name\":\"packPath\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.mvnDeployType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"mvnDeployType\",\"source\":\"mvnDeployType\",\"type\":\"any\"}]}}},\"x-designable-id\":\"02byyjnz2vj\"}}]', '{\"name\":\"mavenProductUpload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"mvnDeployType\"},\"key\":\"mvnDeployType\"},{\"value\":{\"isLiteral\":true,\"value\":\"nexusUrl\"},\"key\":\"nexusUrl\"},{\"value\":{\"isLiteral\":true,\"value\":\"group\"},\"key\":\"group\"},{\"value\":{\"isLiteral\":true,\"value\":\"artifacts\"},\"key\":\"artifacts\"},{\"value\":{\"isLiteral\":true,\"value\":\"pomVersion\"},\"key\":\"pomVersion\"},{\"value\":{\"isLiteral\":true,\"value\":\"packaging\"},\"key\":\"packaging\"},{\"value\":{\"isLiteral\":true,\"value\":\"Classfier\"},\"key\":\"Classfier\"},{\"value\":{\"isLiteral\":true,\"value\":\"pom\"},\"key\":\"pom\"},{\"value\":{\"isLiteral\":true,\"value\":\"packPath\"},\"key\":\"packPath\"}],\"stepFunc\":\"mavenProductUpload\"}', NULL, '将制品上传到Maven制品库', 1, 0, '2022-04-14 05:29:41', '2024-01-30 16:03:43', NULL, 1, 'mavenProductUpload', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.mvnDeployType,map.nexusUrl,map.group,map.artifacts,map.pomVersion,map.packaging,map.Classfier,map.pom,map.packPath)\n    echo env.endString\n\n}\n\ndef call(String stepName,String type,String nexusUrl,String group,String artifacts,String version,\n         String packaging,String Classfier,boolean pom,String path){\n    def pomInfo = readMavenPom file: \'pom.xml\' \n    version = pomInfo.version.toUpperCase()\n    versionType = \'RELEASE\'\n    if(version.contains(\"SNAP\")){\n        versionType = \'SNAPSHOT\'\n    }\n    result = sh returnStdout: true ,script: \"\"\"\n    curl -X GET \"${env.repositorySvcUrl}/api/repository/maven2?repositoryType=hosted&versionPolicy=${versionType}\" -H \"Amp-Organ-Id: ${env.tenantId}\" -H \"accept: */*\" -d \"\"\n    \"\"\"\n    resData = readJSON text: \"\"\"${result}\"\"\"\n    if(resData.code != 0){\n        error \"调用制品库服务查询扫描结果报错，报错信息：${resData.msg}\"\n    }\n    repoUrl = resData.data[0].url\n    repoId = resData.data[0].id\n\n    if(type == \'1\'){\n        def repo = \'\'\n        env.MAVEN_OPTS = \"-Dmaven.wagon.http.ssl.insecure=true -Dmaven.wagon.http.ssl.allowall=true\"\n        if(env.maven_local_repo){\n            repo = \"-Dmaven.repo.local=${env.maven_local_repo}\"\n        }\n        sh \"mvn deploy ${repo} -DskipTests -DaltDeploymentRepository=public::default::${repoUrl}\"\n    }else{\n        fileName = sh(returnStdout:true, script:\"ls ${path}/*.${packaging}\").trim()\n        classStr = \"\"\n        if(Classfier != \'\'){\n            classStr = \"-F \'assetClassifier=${Classfier}\'\"\n        }\n        sh\"\"\"\n            curl -X POST \'${env.repositorySvcUrl}/api/product/upload\' -H  \'accept: */*\' \\\n             -H  \'Content-Type: multipart/form-data\' -F \'packaging=${packaging}\' \\\n             -F \'repositoryId=${repoId}\' -F \'imageName=\' -F \'directory=\' -F \'artifactId=${artifacts}\'  \\\n              ${classStr} -F \'assetFilename=\' -F \'files=@${fileName}\' \\\n             -F \'version=${version}\' -F \'generatePom=true\' -F \'groupId=${group}\' -F \'imageTag=\'\n          \"\"\"\n    }\n}\n\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (15, 1004, 'Npm制品上传', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"nexusRpo\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"n2nyr6eutw6\",\"x-decorator-props\":{\"tooltip\":\"node制品仓库\"},\"name\":\"nexusRpo\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  fetch(`${window.location.origin}/api/warehouse/api/repository/npm?repositoryType=hosted`, {\\n    headers: { Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"\\\",\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"制品仓库\",\"x-index\":0,\"required\":true}},\"x-designable-id\":\"mbs50na3pqr\"}}]', '{\"name\":\"npmProductUpload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"nexusRpo\"},\"key\":\"nexusRpo\"}],\"stepFunc\":\"npmProductUpload\"}', NULL, '上传制品到npm类型组织二方库', 1, 0, '2022-04-14 05:51:23', '2024-02-04 16:25:42', NULL, 1, 'npmProductUpload', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.nexusRpo)\n    echo env.endString\n\n}\n\ndef call(String stepName,String nexusRepo){\n    sh(script:\"npm pack\")\n    npmFileName = sh(returnStdout:true, script:\"ls *.tgz\").trim()\n    sh\"\"\"\n     curl -X POST \'${env.repositorySvcUrl}/api/product/upload\' -H  \'accept: */*\' \\\n    -H  \'Content-Type: multipart/form-data\' -F \'packaging=\' -F \'repositoryId=${nexusRepo}\' \\\n    -F \'imageName=\' -F \'directory=\' -F \'artifactId=\' -F \'assetClassifier=\' -F \'assetFilename=\' \\\n    -F \'files=@${npmFileName}\' -F \'version=\' -F \'generatePom=\' -F \'groupId=\' -F \'imageTag=\' \n    \"\"\"\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (16, 1002, '镜像构建', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"jxgj_dev1\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"evff3fifvjw\",\"x-reactions\":{\"fulfill\":{\"state\":{\"componentProps\":\"{{{\\n  style: {\\n    position: \'relative\'\\n  }\\n}}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"jxgj_dev1\",\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":0,\"properties\":{\"dockerRepository\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"q9roi0y7kre\",\"x-decorator-props\":{\"tooltip\":\"存放镜像的仓库。支持选择已有镜像仓库或者设置为启动变量，例如${dockerRepository}，在执行流水线时指定仓库\",\"addonBefore\":\"\",\"addonAfter\":\"\"},\"name\":\"dockerRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n    $self.loading = true\\n    const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n    var systemId = sessionStorage.getItem(\'systemId\')\\n    var systemOpt = systemId && systemId !== \'null\'?`systemId=${systemId}&`:\'\'\\n    \\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/provider/repository/listAll?${systemOpt}format=docker&kind=2`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"|\\\" + k.url,\\n            label: k.name,\\n          }))\\n          $self.loading = false        \\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  \\n}, [])\\n\",\"state\":{\"visible\":\"{{ !!!$deps.jxgj_btn_1}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"jxgj_btn_1\",\"source\":\"jxgj_dev1.jxgj_dev1_1.jxgj_btn_1\",\"type\":\"boolean\"},{\"property\":\"value\",\"name\":\"startParamName_dockerRepository\",\"source\":\"jxgj_dev1.startParamName_dockerRepository\",\"type\":\"string\"}]},\"x-validator\":[],\"x-component-props\":{\"showSearch\":true},\"title\":\"镜像仓库\",\"x-index\":0,\"required\":true,\"enum\":[]},\"startParamName_dockerRepository\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"kvkz2tpa9bi\",\"x-decorator-props\":{\"tooltip\":\"存放镜像的仓库。支持选择已有镜像仓库或者设置为启动变量，例如${dockerRepository}，在执行流水线时指定仓库\"},\"x-reactions\":{\"fulfill\":{\"run\":\"\",\"state\":{\"visible\":\"{{ !!$deps.jxgj_btn_1}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"jxgj_btn_1\",\"source\":\"jxgj_dev1.jxgj_dev1_1.jxgj_btn_1\",\"type\":\"any\"}]},\"name\":\"startParamName_dockerRepository\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"镜像仓库\",\"x-index\":1,\"required\":true},\"jxgj_dev1_1\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"rw4mm195xig\",\"x-reactions\":{\"fulfill\":{\"state\":{\"componentProps\":\"{{{\\n  style: {\\n    position: \'absolute\',\\n    top: -5,\\n    right: 0,\\n    zIndex: 10000,\\n    width: 74,\\n    cursor: \'pointer\',\\n    color: \'#226ee7\',\\n  }\\n}}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"jxgj_dev1_1\",\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":2,\"properties\":{\"jxgj_btn1\":{\"x-component\":\"Text\",\"x-designable-id\":\"9vjj7yhe68d\",\"x-decorator\":\"FormItem\",\"x-decorator-props\":{\"wrapperWrap\":false,\"labelWrap\":false,\"inset\":false,\"feedbackLayout\":\"none\",\"wrapperAlign\":\"left\"},\"name\":\"jxgj_btn1\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  updateFlag: false\\n})\\n\\n\\n$props({\\n  onClick() {\\n    state.updateFlag = true\\n    $form.fields[\'jxgj_dev1.jxgj_dev1_1.jxgj_btn_1\'].value = !$form.fields[\'jxgj_dev1.jxgj_dev1_1.jxgj_btn_1\'].value\\n  }\\n})\\n\\n\\n\\n\\n$effect(()=>{\\n  if($form.fields[\'jxgj_dev1.jxgj_dev1_1.jxgj_btn_1\'].value){\\n    $self.value = \'选择已有\'\\n    $form.fields[\'jxgj_dev1.dockerRepository\'].value=\'\'\\n    if(state.updateFlag && !$form.fields[\'jxgj_dev1.startParamName_dockerRepository\'].value){\\n      $form.fields[\'jxgj_dev1.startParamName_dockerRepository\'].value = \'${dockerRepository}\'\\n    }\\n    if(!$form.fields[\'jxgj_dev3.jxgj_dev3_1.jxgj_btn_3\'].value){\\n      $form.fields[\'jxgj_dev3.jxgj_dev3_1.jxgj_btn_3\'].value = true\\n    }\\n  }else{\\n    if(state.updateFlag){\\n      $self.value = \'设置为变量\'\\n      $form.fields[\'jxgj_dev1.startParamName_dockerRepository\'].value=\'\'\\n    }\\n  }\\n},[$form.fields[\'jxgj_dev1.jxgj_dev1_1.jxgj_btn_1\']?.value])\\n\",\"state\":{\"value\":\"{{\'设置为变量\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"content\":\"设置为变量\"},\"type\":\"string\",\"x-index\":0},\"jxgj_btn_1\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Switch\",\"x-designable-id\":\"bzfl17kg6o7\",\"x-decorator-props\":{},\"name\":\"jxgj_btn_1\",\"x-reactions\":{\"fulfill\":{\"state\":{\"hidden\":\"{{true}}\"}},\"dependencies\":[]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"\",\"x-index\":1}}}}},\"dockerfile\":{\"x-component\":\"Input\",\"x-designable-id\":\"qorm04hiij6\",\"x-decorator-props\":{\"tooltip\":\"为Dockerfile文件相对于代码库根目录所在路径，如META/config/Dockerfile或Dockerfile\"},\"description\":\"\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"Dockerfile路径\",\"x-index\":1,\"required\":true,\"default\":\"Dockerfile\",\"x-decorator\":\"FormItem\",\"name\":\"dockerfile\"},\"platform\":{\"default\":\"amd64\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"9fgf2o8tdei\",\"x-decorator-props\":{\"tooltip\":\"支持arm64和amd平台\",\"addonBefore\":\"\"},\"name\":\"platform\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"平台架构\",\"x-index\":2,\"required\":true,\"enum\":[{\"children\":[],\"label\":\"amd64\",\"value\":\"amd64\"},{\"children\":[],\"label\":\"arm64\",\"value\":\"arm64\"}]},\"imageName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"9d6nrjboove\",\"x-decorator-props\":{\"tooltip\":\"镜像名称应表达镜像用途和功能。使用小写字母，并以字母开头，以短横线(-)作为单词分隔，不能包含特殊字符和空格\"},\"name\":\"imageName\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"镜像名称\",\"x-index\":3,\"required\":true},\"tagType\":{\"default\":\"defin\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"o6izxlus0ce\",\"x-decorator-props\":{\"tooltip\":\"自定义标签支持输入固定值或者设置为启动变量${tag}，在执行流水线时设置。使用分支标签需在放在代码构建插件后\"},\"name\":\"tagType\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"镜像标签\",\"x-index\":4,\"enum\":[{\"children\":[],\"label\":\"自定义\",\"value\":\"defin\"},{\"children\":[],\"label\":\"时间戳\",\"value\":\"timestamp\"},{\"children\":[],\"label\":\"分支名称\",\"value\":\"branchTag\"},{\"children\":[],\"label\":\"commitId\",\"value\":\"commitId\"}],\"required\":true},\"params_tag\":{\"x-component\":\"Input\",\"x-designable-id\":\"52v27r0372n\",\"x-decorator-props\":{\"tooltip\":\"自定义标签支持输入固定值或者设置为启动变量${tag}，在执行流水线时设置\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"自定义标签\",\"x-index\":5,\"required\":true,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"params_tag\",\"x-reactions\":{\"fulfill\":{\"run\":\"\\n$effect(()=>{\\n  if($deps.tagType == \'defin\'){\\n    $self.value = \'${tag}\'\\n  }else{\\n    $self.value = \'\'\\n  }\\n},[$deps.tagType])\\n  \",\"state\":{\"visible\":\"{{$deps.tagType == \'defin\' }}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"tagType\",\"source\":\"tagType\",\"type\":\"any\"}]},\"x-pattern\":\"editable\"}},\"x-designable-id\":\"oc9o8ooi2wf\"}}]', '{\"name\":\"imageBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"dockerRepository\"},\"key\":\"dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_dockerRepository\"},\"key\":\"startParamName_dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"jxgj_btn1\"},\"key\":\"jxgj_btn1\"},{\"value\":{\"isLiteral\":true,\"value\":\"jxgj_btn_1\"},\"key\":\"jxgj_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"dockerfile\"},\"key\":\"dockerfile\"},{\"value\":{\"isLiteral\":true,\"value\":\"platform\"},\"key\":\"platform\"},{\"value\":{\"isLiteral\":true,\"value\":\"imageName\"},\"key\":\"imageName\"},{\"value\":{\"isLiteral\":true,\"value\":\"tagType\"},\"key\":\"tagType\"},{\"value\":{\"isLiteral\":true,\"value\":\"params_tag\"},\"key\":\"params_tag\"}],\"stepFunc\":\"imageBuild\"}', NULL, '通过Dockerfile制作镜像并上传至镜像仓库', 1, 0, '2022-04-28 01:35:27', '2024-02-27 10:48:31', NULL, 1, 'imageBuild', '3', '2', '2', 'def call(def map){\n    \n    def dockerRepository = \'\'\n    \n    if(map.startParamName_dockerRepository || !map.dockerRepository.contains(\"/\")){\n        def harborId = map.startParamName_dockerRepository?map.startParamName_dockerRepository:map.dockerRepository\n        def result = sh returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/repository/detail?id=${harborId}\" -H \"accept: */*\" -d \"\"\n        \"\"\"\n        def resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0){\n            error \"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\"\n        }\n        def harborUrl = resData.data.url.replace(\"https://\",\"\")\n        dockerRepository = harborId + \'|\' + harborUrl\n    }else{\n        dockerRepository = map.dockerRepository\n    }\n    \n    call(map.stepName,dockerRepository,map.imageName,map.dockerfile,map.platform,map.tagType,map.params_tag)\n    echo env.endString\n}\n\ndef call(String stepName,String harborUrl,String imageName,String dockerfile,String target){\n   call(stepName,harborUrl,imageName,dockerfile,\'defin\',target)\n}\n\ndef call(String stepName,String harborUrl,String imageName,String dockerfile,String tagType ,String tag){\n   call(stepName,harborUrl,imageName,dockerfile,\'amd64\',tagType,tag)\n}\n\ndef call(String stepName,String harborUrl,String imageName,String dockerfile,String platform,String tagType ,String tag){\n    echo \"harborUrl：${harborUrl}\"\n    echo \"dockerfile文件：${dockerfile}\"\n    def repoIdOp = \'\'\n    if(harborUrl.contains(\"|\")){\n        def repoId = harborUrl.split(\"\\\\|\")[0]\n        harborUrl = harborUrl.split(\"\\\\|\")[1]\n        repoIdOp = \"-F \'repositoryId=${repoId}\'\"\n    }\n    \n    if(!fileExists(dockerfile)){\n        def language= env.language\n        println(\"-------------\"+language)\n        if(language == \'java8\' ||  language == \'java\'){\n            if(env.packageType == \'war\'){\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:8\nWORKDIR /app\nCOPY target/*.war ./app.war\n\"\"\"\n            }else {\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:8\nWORKDIR /app\nCOPY target/*.jar ./app.jar\nENTRYPOINT [\"java\", \"-jar\",\"/app/app.jar\"]\n\"\"\"\n            }\n        }else if(language == \'java11\'){\n            if(env.packageType == \'war\'){\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:11\nWORKDIR /app\nCOPY target/*.war ./app.war\n\"\"\"\n            }else {\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:11\nWORKDIR /app\nCOPY target/*.jar ./app.jar\nENTRYPOINT [\"java\", \"-jar\",\"/app/app.jar\"]\n\"\"\"\n            }\n        }else if(language == \'node14\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM node:14.16\nWORKDIR /app\nCOPY dist/ ./dist/\nENTRYPOINT npm run entrypoint\n\"\"\"\n        }else if(language == \'net5\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM mcr.microsoft.com/dotnet/runtime:3.1.31-buster-slim\nWORKDIR /app\nCOPY app/build/ ./\nENTRYPOINT [\"dotnet\", \"dotnetWebDemo.dll\"]\n\"\"\"\n        }else if(language == \'php7\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM php:7.4.33-cli-bullseye\nWORKDIR /app\nCOPY ./ ./\nRUN composer install\nCMD [\"php\", \"-S 0.0.0.0:80\", \"-t ./\"]\n\"\"\"\n        }else if(language == \'golang1.19\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM golang:1.19-bullseye\nUSER root\nWORKDIR /home/go\nCOPY ./ ./\nENTRYPOINT [\"./go-app\"]\n\"\"\"\n        }else if(language == \'python3\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM python:3.8-bullseye\nUSER root\nWORKDIR /home/python\nCOPY dist/ ./dist/\n\"\"\"\n        }else{\n            error \"没有language启动变量\"\n        }\n    }\n    // defin  timestamp  increment  branchTag  commitId\n    if(env.productVersion){\n        tag = env.productVersion\n    }else if(tagType == \'defin\'){\n        if(env.tag){\n          tag =  env.tag \n        }\n\n    }else if(tagType == \'timestamp\'){\n        tag = env.date\n    }else if(tagType == \'increment\'){\n        arr = tag.split(\"\\\\.\")\n        int value = arr[2].toInteger() + 1\n        tag =  \"${arr[0]}.${arr[1]}.${value}\"\n        //将修改后的tag提交到后台\n        echo \"-----------------------镜像构建的分支是： ${tag}--------------------------\"\n        sh \"\"\"\n        curl -X PUT \"${env.pipelineSvcUrl}/devops/pipeline/jobs/${env.job_id}/startParams\" -H \"accept: */*\" -H \"Content-Type: application/json\" -d \"{\\\\\\\"tag\\\\\\\":\\\\\\\"${tag}\\\\\\\"}\"\n        \"\"\"\n    }else if(tagType == \'branchTag\'){\n        tag = env.branch\n    }else if(tagType == \'commitId\'){\n        tag = sh(returnStdout: true ,script: \'git rev-parse --verify --short HEAD\').trim()\n    }\n    if(imageName){\n        imageName = imageName\n    }\n     if(platform == \'arm64\'){\n      sh \"\"\"\n      export DOCKER_HOST=tcp://10.10.102.93:2375\n      docker buildx build --platform linux/arm64 -f ${dockerfile} -t ${harborUrl}/${imageName}:${tag} . --load \n      \"\"\"\n    }else{\n      sh \"docker build -f ${dockerfile} -t ${harborUrl}/${imageName}:${tag} .\"\n    }\n    def credentailId = \'harbor-pipeline-credentials\'\n    if(harborUrl.startsWith(\'10.120.1.233:8443\')){\n        credentailId = \"harbor-pipeline-credentials-233\"\n    }\n    withCredentials([usernamePassword(credentialsId: credentailId,passwordVariable: \'password\', usernameVariable: \'username\')]) {\n         retry(3) {\n            if(platform == \'arm64\'){\n                sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n            }else{\n                sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n            }\n\n         }\n\n    }\n    \n    // if(\"${harborUrl}\".startsWith(\"10.120.1.233\")){\n    //     withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials-233\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n    //      retry(3) {\n    //         sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n    //      }\n\n    //     }\n    // } else {\n    // withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n    //      retry(3) {\n    //         if(platform == \'arm64\'){\n    //             sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n    //         }else{\n    //             sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n    //         }\n\n    //      }\n\n    //     }\n    // }\n    retry(3) {\n        if(platform == \'arm64\'){\n              sh \"\"\"\n              export DOCKER_HOST=tcp://10.10.102.93:2375\n              docker push ${harborUrl}/${imageName}:${tag}\n              \"\"\"\n        }else{\n            sh \"docker push ${harborUrl}/${imageName}:${tag}\"\n        }\n\n    }\n\n    // if(platform == \'arm64\'){\n    //     sh \"\"\"\n    //     export DOCKER_HOST=tcp://10.10.102.93:2375\n    //     docker-arm rmi -f ${harborUrl}/${imageName}:${tag}\n    //     \"\"\"\n    // }else{\n    //     sh \"docker rmi -f ${harborUrl}/${imageName}:${tag}\"\n    // }\n    env.harborUrl = harborUrl\n    env.imageName = imageName\n    env.tagert = tag\n    \n    imageProjectName = env.harborUrl.split(\"/\")[1]\n    \n    mergeBranch = \'\'\n    mergeCommitId = \'\'\n    if(env.pipeline_clone_branch){\n       mergeBranch = \'\' \n    }\n    if(env.commitId){\n        mergeCommitId = env.commitId\n    }\n    \n    //通用制品上传\n    //判断扫描结果是否已经生成 1、如果打开了扫描的门禁则可以确定已经生成了扫描方案 \n    result = sh returnStdout: true ,script: \"\"\"\n    curl -X GET \"${env.codeInspectSvcUrl}/scanTasks/scanInfo/byBuildId?buildId=${env.buildId}\" -H \"accept: */*\" -d \"\"\n    \"\"\"\n    def resData = readJSON text: \"\"\"${result}\"\"\"\n    if(resData.code != 0){\n        error \"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\"\n    }\n    historyOpt = \'\'\n    if(env.soanrWaitGate || (resData.data.status != 3 && resData.data.histories.size() == 1)){\n        for(item in resData.data.histories){\n            historyOpt += \"-F \'historyId =${item.historyId}\' -F \'sonarResult =${item.status}\' \"\n        }\n    }\n    version = tag\n    \n    if(!env.mergeServerId){\n        env.mergeServerId = \'\'\n    }\n    if(!env.mergeGitlabId){\n        env.mergeGitlabId = \'\'\n    }\n    systemOpt = \'\'\n    if(env.systemId){\n        systemOpt = \"-F \'subsystemId=${env.subsystemId}\' -F \'systemId=${env.systemId}\'\"\n    }\n    if(repoIdOp != \'\'){\n        result = sh returnStdout: true ,script: \"\"\"\n         curl -X POST \'${env.repositorySvcUrl}/api/provider/product/upload/container\' -H  \'accept: */*\' -H  \'Content-Type: multipart/form-data\' \\\n         -F \'jobId=${job_id}\' -F \'buildId=${env.buildId}\' -F \'serverId=${env.mergeServerId}\' -F \'gitlabId=${env.mergeGitlabId}\' -F \'jobName=${env.JOB_NAME}\' -F \'repositoryName=${imageProjectName}\'\\\n         -F \'productName=${env.imageName}\' -F \'version=${version}\' -F \'mergeBranch=${env.mergeBranch}\' -F \'commitId=${env.mergeCommitId}\' ${historyOpt} ${repoIdOp}  ${systemOpt} -F \'userId=${env.runUserId}\'\n        \"\"\"\n        echo \"${result}\"\n        resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0){\n            error \"上传元通用制品元数据失败\"\n        }\n        echo \"上传制品：${resData.data.id}\"\n        env.dockerDeployProduct = resData.data.id\n        env.productUploadStepFlag = true\n    }\n}\n\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (17, 1010, '收集通用报告', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"reportName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"7jtpgh9g9fj\",\"x-decorator-props\":{},\"name\":\"reportName\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"报告名称\",\"x-index\":0,\"required\":true},\"reportDir\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"rzolnnidjya\",\"x-decorator-props\":{},\"name\":\"reportDir\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"报告路径\",\"x-index\":1,\"required\":true},\"reportFiles\":{\"default\":\"index.html\",\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"lpdr8pednmn\",\"x-decorator-props\":{},\"name\":\"reportFiles\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"入口文件\",\"x-index\":2,\"required\":true}},\"x-designable-id\":\"sjyll01i8pe\"}}]', '{\"name\":\"publishReport\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"reportName\"},\"key\":\"reportName\"},{\"value\":{\"isLiteral\":true,\"value\":\"reportDir\"},\"key\":\"reportDir\"},{\"value\":{\"isLiteral\":true,\"value\":\"reportFiles\"},\"key\":\"reportFiles\"}],\"stepFunc\":\"publishReport\"}', NULL, '收集通用报告', 1, 0, '2022-05-09 06:15:26', '2024-05-27 11:20:41', NULL, 1, 'publishReport', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.reportName,map.reportDir,map.reportFiles)\n    echo env.endString\n\n}\ndef call(String stepName,String reportName,String reportDir,String reportFiles) {\n    \n    if (!fileExists(\"${reportDir}/${reportFiles}\")) {\n        error \"收集的通用报告不存在\"\n    }\n    \n    publishHTML([allowMissing: false, alwaysLinkToLastBuild: false, keepAll: true, reportDir: \"${reportDir}\", reportFiles: \"${reportFiles}\", reportName: \"${reportName}\", reportTitles: \"${reportName}\"])\n    sh \"\"\"\n    curl -X POST \"${env.pipelineSvcUrl}/publishHtml\" -H \"accept: */*\" -H \"Content-Type: application/json\" -d \"{\\\\\\\"buildId\\\\\\\":\\\\\\\"${env.buildId}\\\\\\\",\\\\\\\"reportDir\\\\\\\":\\\\\\\"${reportDir}\\\\\\\",\\\\\\\"reportFiles\\\\\\\":\\\\\\\"${reportFiles}\\\\\\\",\\\\\\\"reportName\\\\\\\":\\\\\\\"${reportName}\\\\\\\"}\"\n    \"\"\"\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (30, 1010, '文件读取', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"fileName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"kvrxnalvrvc\",\"x-decorator-props\":{\"tooltip\":\"读取文件名\"},\"name\":\"fileName\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"文件\",\"x-index\":0,\"required\":true},\"encoding\":{\"default\":\"utf-8\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"ygzr88me5he\",\"x-decorator-props\":{\"tooltip\":\"文件编码\"},\"name\":\"encoding\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"编码\",\"x-index\":1,\"enum\":[{\"children\":[],\"label\":\"utf-8\",\"value\":\"utf-8\"}],\"required\":true},\"variable\":{\"default\":\"fileContent\",\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"u6vn10fe54a\",\"x-decorator-props\":{\"tooltip\":\"附加参数\"},\"name\":\"variable\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"变量\",\"x-index\":2,\"required\":true}},\"x-designable-id\":\"385a45d3beo\"}}]', '{\"name\":\"fileRead\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"fileName\"},\"key\":\"fileName\"},{\"value\":{\"isLiteral\":true,\"value\":\"encoding\"},\"key\":\"encoding\"},{\"value\":{\"isLiteral\":true,\"value\":\"variable\"},\"key\":\"variable\"}],\"stepFunc\":\"fileRead\"}', NULL, '文件读取', 1, 0, '2022-09-19 17:19:21', '2024-02-04 16:35:40', NULL, 1, 'fileRead', '0', '0', '2', 'def call(def map){\n    call(map.stepName,map.fileName,map.encoding,map.variable)\n    echo env.endString\n\n}\n\ndef call(String stepName,String file,String enCode,String param){\n    env[param] = readFile encoding: \'utf-8\', file: file\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (31, 1010, '文件写入', '[{\"form\":{\"layout\":\"vertical\",\"wrapperWrap\":false,\"wrapperCol\":12,\"inset\":false,\"labelWrap\":false,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"fileName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"li621rsy7xy\",\"x-decorator-props\":{\"tooltip\":\"填写文件路径及名称，例如app/test.txt\"},\"name\":\"fileName\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"文件路径\",\"x-index\":0,\"required\":true},\"encoding\":{\"default\":\"utf-8\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"0f8q2nvpg1a\",\"x-decorator-props\":{\"tooltip\":\"编码格式\"},\"name\":\"encoding\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"编码\",\"x-index\":1,\"required\":true,\"enum\":[{\"children\":[],\"label\":\"utf-8\",\"value\":\"utf-8\"}]},\"fileContent\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input.TextArea\",\"x-display\":\"visible\",\"x-designable-id\":\"dphkchiebff\",\"x-decorator-props\":{\"tooltip\":\"文件内容\"},\"name\":\"fileContent\",\"x-validator\":[],\"x-component-props\":{\"autoSize\":true,\"showCount\":false,\"style\":{\"width\":\"inherit\"},\"placeholder\":\"\"},\"type\":\"string\",\"title\":\"文件内容\",\"x-index\":2,\"required\":true}},\"x-designable-id\":\"quurtmq9hv2\"}}]', '{\"name\":\"fileWrite\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"fileName\"},\"key\":\"fileName\"},{\"value\":{\"isLiteral\":true,\"value\":\"encoding\"},\"key\":\"encoding\"},{\"value\":{\"isLiteral\":true,\"value\":\"fileContent\"},\"key\":\"fileContent\"}],\"stepFunc\":\"fileWrite\"}', NULL, '在指定路径新建文件并写入内容', 1, 0, '2022-09-19 17:19:39', '2024-02-04 16:35:52', NULL, 1, 'fileWrite', '0', '2', '2', 'def call(def map){\n    \n    call(map.stepName,map.fileName,map.encoding,map.fileContent)\n    echo \'--------------------------------------------------------------------------\'\n    echo env.endString\n\n}\ndef call(String stepName,String fileName,String encoding,String fileContent){\n    \n    writeFile encoding: encoding, file: fileName, text: \"\"\"${fileContent}\"\"\"\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (107, 1005, 'Kubernetes部署', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"k8sbs_dev1\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"u0njzdfh93r\",\"name\":\"k8sbs_dev1\",\"x-reactions\":{\"fulfill\":{\"state\":{\"componentProps\":\"{{{\\n    style: {\\n      position: \'relative\'\\n    }\\n  }}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":0,\"properties\":{\"deployEnv\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"l0wxu932ssu\",\"x-decorator-props\":{\"tooltip\":\"环境在持续交付或系统下的部署环境菜单中配置，在环境下添加集群及命名空间后才能用于部署。 支持选择已有环境或者设置为启动变量，例如${deployEnv}，在执行流水线时指定环境\"},\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  // $self.value = \\\"\\\"\\n  var systemId = sessionStorage.getItem(\\\"systemId\\\")\\n  fetch(`${window.location.origin}/api/efficiency/deploy/env?systemId=${systemId}`, {\\n    headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.records.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"\\\",\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\",\"state\":{\"visible\":\"{{!!!$deps.k8sbs_btn_1}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"k8sbs_btn_1\",\"source\":\"k8sbs_dev1.k8sbs_dev1_1.k8sbs_btn_1\",\"type\":\"boolean\"},{\"property\":\"value\",\"name\":\"startParamName_deployEnv\",\"source\":\"k8sbs_dev1.startParamName_deployEnv\",\"type\":\"string\"}]},\"name\":\"deployEnv\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"部署环境\",\"x-index\":0,\"required\":true},\"startParamName_deployEnv\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"z0a7gqekamd\",\"x-decorator-props\":{\"tooltip\":\"环境在持续交付或系统下的部署环境菜单中配置，在环境下添加集群及命名空间后才能用于部署。 支持选择已有环境或者设置为启动变量，例如${deployEnv}，在执行流水线时指定环境\"},\"name\":\"startParamName_deployEnv\",\"x-reactions\":{\"fulfill\":{\"run\":\"\",\"state\":{\"visible\":\"{{!!$deps.k8sbs_btn_1}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"k8sbs_btn_1\",\"source\":\"k8sbs_dev1.k8sbs_dev1_1.k8sbs_btn_1\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"部署环境\",\"x-index\":1,\"required\":true},\"k8sbs_dev1_1\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"i3ak1u5sobs\",\"name\":\"k8sbs_dev1_1\",\"x-reactions\":{\"fulfill\":{\"state\":{\"componentProps\":\"{{{\\n  style: {\\n    position: \'absolute\',\\n    top: -5,\\n    right: 0,\\n    zIndex: 10000,\\n    width: 74,\\n    cursor: \'pointer\',\\n    color: \'#226ee7\',\\n  }\\n}}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":2,\"properties\":{\"k8sbs_btn1\":{\"x-component\":\"Text\",\"x-designable-id\":\"9vjj7yhe68a\",\"x-decorator\":\"FormItem\",\"x-decorator-props\":{\"wrapperWrap\":false,\"labelWrap\":false,\"inset\":false,\"feedbackLayout\":\"none\",\"wrapperAlign\":\"left\"},\"name\":\"k8sbs_btn1\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  updateFlag: false\\n})\\n\\n\\n$props({\\n  onClick() {\\n    state.updateFlag = true\\n    $form.fields[\'k8sbs_dev1.k8sbs_dev1_1.k8sbs_btn_1\'].value = !$form.fields[\'k8sbs_dev1.k8sbs_dev1_1.k8sbs_btn_1\'].value\\n  }\\n})\\n\\n\\n$effect(()=>{\\n  if($form.fields[\'k8sbs_dev1.k8sbs_dev1_1.k8sbs_btn_1\'].value){\\n    $self.value = \'选择已有\'\\n    $form.fields[\'k8sbs_dev1.deployEnv\'].value=\'\'\\n    if(state.updateFlag && !$form.fields[\'k8sbs_dev1.startParamName_deployEnv\'].value){\\n      $form.fields[\'k8sbs_dev1.startParamName_deployEnv\'].value = \'${deployEnv}\'\\n    }\\n    if(!$form.fields[\'k8sbs_dev2.k8sbs_dev2_1.k8sbs_btn_2\'].value){\\n      $form.fields[\'k8sbs_dev2.k8sbs_dev2_1.k8sbs_btn_2\'].value = !$form.fields[\'k8sbs_dev2.k8sbs_dev2_1.k8sbs_btn_2\'].value\\n    }\\n  }else{\\n    if(state.updateFlag){\\n      $self.value = \'设置为变量\'\\n    $form.fields[\'k8sbs_dev1.startParamName_deployEnv\'].value=\'\'\\n  }\\n  }\\n},[$form.fields[\'k8sbs_dev1.k8sbs_dev1_1.k8sbs_btn_1\']?.value])\\n\\n\\n\",\"state\":{\"value\":\"{{\'设置为变量\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"content\":\"设置为变量\"},\"type\":\"string\",\"x-index\":0},\"k8sbs_btn_1\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Switch\",\"x-designable-id\":\"bzfl17kg6o7\",\"x-decorator-props\":{},\"name\":\"k8sbs_btn_1\",\"x-reactions\":{\"fulfill\":{\"state\":{\"hidden\":\"{{true}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"\",\"x-index\":1}}}}},\"k8sbs_dev2\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"epil3krbgim\",\"name\":\"k8sbs_dev2\",\"x-reactions\":{\"fulfill\":{\"state\":{\"componentProps\":\"{{\\n{\\n  style: {\\n    position: \'relative\'\\n  }\\n}}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":1,\"properties\":{\"deployCluster\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"1f9hek5b33a\",\"x-decorator-props\":{\"tooltip\":\"应用需要部署到的Kubernetes集群，在部署环境中添加集群。 支持选择已有集群或者设置为启动变量，例如${deployCluster}，在执行流水线时指定集群\"},\"name\":\"deployCluster\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.deployEnv) {\\n    $self.loading = true\\n    const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n   // $self.value = \\\"\\\"\\n    \\n      fetch(\\n      `${window.location.origin}/api/efficiency/deploy/host/listAll?envId=${$deps.deployEnv}&type=4`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId,Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"\\\",\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n    \\n    \\n}, [$deps.deployEnv])\",\"state\":{\"visible\":\"{{!!!$deps.k8sbs_btn_2}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployEnv\",\"source\":\"k8sbs_dev1.deployEnv\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"k8sbs_btn_2\",\"source\":\"k8sbs_dev2.k8sbs_dev2_1.k8sbs_btn_2\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"Kubernetes集群\",\"x-index\":0,\"required\":true},\"startParamName_deployCluster\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"kbcxumq7712\",\"x-decorator-props\":{\"tooltip\":\"应用需要部署到的Kubernetes集群，在部署环境中添加集群。 支持选择已有集群或者设置为启动变量，例如${deployCluster}，在执行流水线时指定环境。命名空间在yaml文件中指定\"},\"name\":\"startParamName_deployCluster\",\"x-reactions\":{\"fulfill\":{\"run\":\"\",\"state\":{\"visible\":\"{{!!$deps.k8sbs_btn_2}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"k8sbs_btn_2\",\"source\":\"k8sbs_dev2.k8sbs_dev2_1.k8sbs_btn_2\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"Kubernetes集群\",\"x-index\":1,\"required\":true},\"k8sbs_dev2_1\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"o0171nsik5m\",\"name\":\"k8sbs_dev2_1\",\"x-reactions\":{\"fulfill\":{\"state\":{\"componentProps\":\"{{{\\n  style: {\\n    position: \'absolute\',\\n    top: -5,\\n    right: 0,\\n    zIndex: 10000,\\n    width: 74,\\n    cursor: \'pointer\',\\n    color: \'#226ee7\',\\n  }\\n}}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":2,\"properties\":{\"k8sbs_btn2\":{\"x-component\":\"Text\",\"x-designable-id\":\"9vjj7yhe90d\",\"x-decorator\":\"FormItem\",\"x-decorator-props\":{\"wrapperWrap\":false,\"labelWrap\":false,\"inset\":false,\"feedbackLayout\":\"none\",\"wrapperAlign\":\"left\"},\"name\":\"k8sbs_btn2\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  updateFlag: false\\n})\\n\\n\\n$props({\\n  onClick() {\\n    state.updateFlag = true\\n    if(!$form.fields[\'k8sbs_dev1.k8sbs_dev1_1.k8sbs_btn_1\'].value){\\n      $form.fields[\'k8sbs_dev2.k8sbs_dev2_1.k8sbs_btn_2\'].value = !$form.fields[\'k8sbs_dev2.k8sbs_dev2_1.k8sbs_btn_2\'].value\\n    }\\n  }\\n})\\n\\n\\n$effect(()=>{\\n  if($form.fields[\'k8sbs_dev2.k8sbs_dev2_1.k8sbs_btn_2\'].value){\\n    $self.value = \'选择已有\'\\n    $form.fields[\'k8sbs_dev2.deployCluster\'].value=\'\'\\n    if(!$form.fields[\'k8sbs_dev2.startParamName_deployCluster\'].value){\\n      $form.fields[\'k8sbs_dev2.startParamName_deployCluster\'].value = \'${deployCluster}\'\\n    } \\n  }else{\\n    $self.value = \'设置为变量\'\\n    $form.fields[\'k8sbs_dev2.startParamName_deployCluster\'].value=\'\'\\n  }\\n},[$form.fields[\'k8sbs_dev2.k8sbs_dev2_1.k8sbs_btn_2\']?.value])\\n\\n\\n\",\"state\":{\"value\":\"{{\'设置为变量\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"content\":\"设置为变量\"},\"type\":\"string\",\"x-index\":0},\"k8sbs_btn_2\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Switch\",\"x-designable-id\":\"bzfl17kg9o7\",\"x-decorator-props\":{},\"name\":\"k8sbs_btn_2\",\"x-reactions\":{\"fulfill\":{\"state\":{\"hidden\":\"{{true}}\"}},\"dependencies\":[]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"\",\"x-index\":1}}}}},\"deployPath\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"sn6nqcebv3z\",\"x-decorator-props\":{\"tooltip\":\"输入yaml配置所在文件夹的相对路径\"},\"name\":\"deployPath\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"yaml文件路径\",\"x-index\":2,\"required\":true}},\"x-designable-id\":\"7xi9u26odhc\"}}]', '{\"name\":\"k8sDeployFun\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployEnv\"},\"key\":\"deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployEnv\"},\"key\":\"startParamName_deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"k8sbs_btn1\"},\"key\":\"k8sbs_btn1\"},{\"value\":{\"isLiteral\":true,\"value\":\"k8sbs_btn_1\"},\"key\":\"k8sbs_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployCluster\"},\"key\":\"deployCluster\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployCluster\"},\"key\":\"startParamName_deployCluster\"},{\"value\":{\"isLiteral\":true,\"value\":\"k8sbs_btn2\"},\"key\":\"k8sbs_btn2\"},{\"value\":{\"isLiteral\":true,\"value\":\"k8sbs_btn_2\"},\"key\":\"k8sbs_btn_2\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployPath\"},\"key\":\"deployPath\"}],\"stepFunc\":\"k8sDeployFun\"}', '', '基于 yaml 文件向 Kubernetes 集群部署应用', 1, 0, '2022-03-21 15:16:37', '2024-02-23 11:41:07', NULL, 1, 'k8sDeployFun', '3', '2', '2', 'import org.codehaus.groovy.runtime.GStringImpl\n\ndef call(def map){\n    def deployEnv = map.deployEnv\n    if(map.startParamName_deployEnv){\n        if(map.startParamName_deployEnv instanceof GStringImpl){\n            deployEnv = map.startParamName_deployEnv\n        }else{\n            deployEnv = env[map.startParamName_deployEnv] \n        }\n    }\n    def deployCluster = map.deployCluster\n    if(map.startParamName_deployCluster){\n        if(map.startParamName_deployCluster instanceof GStringImpl){\n            deployCluster = map.startParamName_deployCluster\n        }else{\n            deployCluster = env[map.startParamName_deployCluster] \n        }\n    }\n    call(map.stepName,deployEnv,deployCluster,map.deployPath)\n    echo env.endString\n\n}\n\ndef call(String stepName,String envId,String clusterId,String path){\n    //部署前，存部署信息\n    productIdOp = \'\'\n    if(env.dockerDeployProduct){\n        productIdOp = \"-F \'productId=${env.dockerDeployProduct}\'\"\n    }\n    configCloneCommandOp = \'\'\n    if(env.configCloneCommand){\n        configCloneCommandOp = \"-F \'configCloneCommand=${env.configCloneCommand}\' -F \'configRepoId=${env.configRepoId}\' -F \'configRepoName=${env.configRepoName}\' -F \'configRepoEnv=${env.configRepoEnv}\' -F \'configRepoCommitId=${env.configRepoCommitId}\' \"\n    }\n    gitlabIdOpt = \'\'\n    if(env.mergeBranch){\n       gitlabIdOpt = \"-F \'gitRepo=${env.gitRepo}\' -F \'gitBranch=${env.mergeBranch}\' -F \'gitCommitId=${env.mergeCommitId}\' -F \'gitCredentialId=${env.mergeGitCredentialId}\'\"\n        if(env.mergeGitlabId){\n            gitlabIdOpt = gitlabIdOpt + \" -F \'serverId=${env.mergeServerId}\' -F \'gitlabId=${env.mergeGitlabId}\'\"\n        } \n    }\n    sh \"\"\"\n    curl -X POST \'${env.pipelineSvcUrl}/devops/buildDeploy/addK8sRecords\' -F \'buildId=${env.buildId}\' -F \'jobId=${params.job_id}\' -F \'deployType=Kubernetes部署\' ${gitlabIdOpt} ${productIdOp} ${configCloneCommandOp} -F \'deployEnv=${envId}\' -F \'hostId=${clusterId}\'  -F \'command=kubectl replace --force -f ${path}/\' -H \'accept: */*\'\n    \"\"\"\n\n   def response = sh returnStdout: true ,script:\"\"\"\n    curl -X GET \"${env.pipelineSvcUrl}/deploy/cluster/${clusterId}/token\" -H \"accept: */*\"\n    \"\"\"\n    def resData = readJSON text: \"\"\"${response}\"\"\"\n    def token = resData.data[0].token.trim();\n    if(token.startsWith(\"apiVersion\")){\n        writeFile encoding: \"utf-8\", file: \"kubeconfig\", text: \"\"\"${token}\"\"\"\n        sh \"\"\"\n        rm -rf /root/.kube/config\n        mkdir -p /root/.kube\n        mv kubeconfig /root/.kube/config\n        \"\"\"\n    }else{\n        sh \"\"\"\n        kubectl config set-cluster kubernetes --server=https://${resData.data[0].ip}:${resData.data[0].port} --insecure-skip-tls-verify=true\n        set +x\n        kubectl config set-credentials admin --token=${token}\n        set -x\n        kubectl config set-context dev --cluster=kubernetes --user=admin\n        kubectl config use-context dev\n         \"\"\"\n\n    }\n    sh \"\"\"\n        chmod g-rw ~/.kube/config\n        chmod o-r ~/.kube/config\n    \"\"\"\n\n    sh \"kubectl apply -f ${path}/\"\n    try{\n       sh \"kubectl rollout restart -f ${path}/\" \n    }catch(Exception e){\n        \n    }\n}\n\n\ndef call(String stepName,Integer envId,Integer clusterId,String path){\n   call(stepName,\"${envId}\",\"${clusterId}\",path)\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (111, 1005, 'Kubernetes镜像更新', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"startParamName_deployEnv\":{\"x-component\":\"Select\",\"x-designable-id\":\"9se3u4fpk1v\",\"x-decorator-props\":{\"tooltip\":\"环境在 持续交付或系统下的部署环境菜单中配置。在环境下添加集群和命名空间后才能用于发布\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"环境\",\"x-index\":0,\"required\":true,\"default\":\"${deployEnv}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_deployEnv\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  \\n  const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  var systemId = sessionStorage.getItem(\\\"systemId\\\")\\n  // $self.value = \\\"\\\"\\n  fetch(`${window.location.origin}/api/efficiency/deploy/env?systemId=${systemId}`, {\\n    headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.records.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"\\\",\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"startParamName_deployCluster\":{\"x-component\":\"Select\",\"x-designable-id\":\"m56p5aht21w\",\"x-decorator-props\":{\"tooltip\":\"数据来源：部署环境资源管理\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"集群\",\"x-index\":1,\"required\":true,\"default\":\"${deployCluster}\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployEnv\",\"source\":\"deployEnv\",\"type\":\"any\"}]},\"name\":\"startParamName_deployCluster\",\"x-pattern\":\"disabled\"},\"startParamName_namespace\":{\"x-component\":\"Select\",\"x-designable-id\":\"g0307ayy1an\",\"x-decorator-props\":{\"tooltip\":\"更新应用所在命名空间，可在部署环境资源管理中配置\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"命名空间\",\"x-index\":2,\"required\":true,\"default\":\"${namespace}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_namespace\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.$$deployCluster) {\\n    $self.loading = true\\n    // $self.value = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    fetch(\\n      `${window.location.origin}/api/efficiency/deploy/cluster/${$deps.$$deployCluster}`,{\\n      headers: {Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          if (data != null && data.length > 0) {\\n            var na = data[0].namespace\\n            const re = na.map((k) => ({\\n              ...k,\\n              value: k,\\n              label: k,\\n            }))\\n            $self.loading = false\\n            $self.dataSource = re\\n          } else {\\n            $self.dataSource = []\\n          }\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.$$deployCluster])\\n\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"$$deployCluster\",\"source\":\"$$deployCluster\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"deployName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"09gqm3imjbu\",\"x-decorator-props\":{\"tooltip\":\"工作负载名称，例如Deployment中的name\"},\"name\":\"deployName\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"应用名称\",\"x-index\":3,\"required\":true}},\"x-designable-id\":\"9j954xd9h28\"}}]', '{\"name\":\"k8sApplicationDeploy\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployEnv\"},\"key\":\"startParamName_deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployCluster\"},\"key\":\"startParamName_deployCluster\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_namespace\"},\"key\":\"startParamName_namespace\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployName\"},\"key\":\"deployName\"}],\"stepFunc\":\"k8sApplicationDeploy\"}', '', '升级Kubernetes工作负载的镜像', 1, 0, '2022-03-24 06:25:51', '2024-03-19 11:58:44', NULL, 1, 'k8sApplicationDeploy', '0', '0', '2', 'def call(def map){\n    call(map.stepName,map.startParamName_deployEnv,map.startParamName_deployCluster,map.startParamName_namespace,map.deployName)\n    echo env.endString\n\n}\ndef call(String stepName,String envId,String clusterId,String namespace,String deployment){\n    if(env.deployCluster){\n        clusterId = env.deployCluster\n    }\n    if(env.namespace){\n        namespace = env.namespace\n    }\n    //根据clusterId查询环境url和token\n    def response = sh returnStdout: true ,script:\"\"\"\n    curl -X GET \"${env.pipelineSvcUrl}/deploy/cluster/${clusterId}/token\" -H \"accept: */*\"\n    \"\"\"\n    def resData = readJSON text: \"\"\"${response}\"\"\"\n    def token = resData.data[0].token.trim();\n    if(token.startsWith(\"apiVersion\")){\n        writeFile encoding: \"utf-8\", file: \"kubeconfig\", text: \"\"\"${token}\"\"\"\n        sh \"\"\"\n        mkdir -p /root/.kube\n        rm -rf /root/.kube/config\n        mv kubeconfig /root/.kube/config\n        \"\"\"\n    }else{\n        sh \"\"\"\n        kubectl config set-cluster kubernetes --server=https://${resData.data[0].ip}:${resData.data[0].port} --insecure-skip-tls-verify=true\n        set +x\n        kubectl config set-credentials admin --token=${token}\n        set -x\n        kubectl config set-context dev --cluster=kubernetes --user=admin\n        kubectl config use-context dev\n         \"\"\"\n    }\n    sh \"\"\"\n        chmod g-rw ~/.kube/config\n        chmod o-r ~/.kube/config\n    \"\"\"\n\n    if(env.imageName) {\n        def res = sh returnStdout: true, script: \"\"\"  \n        kubectl set image deployment ${deployment} *=${env.harborUrl}/${env.imageName}:${env.tagert} -n ${namespace}       \n        \"\"\"\n        if (!res.contains(\"update\")) {\n            sh \"kubectl rollout restart deployment ${deployment} -n ${namespace}\"\n        }\n    }\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (202, 1001, '代码克隆', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"serviceType\":{\"default\":\"1\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"mnue2j6knv9\",\"x-decorator-props\":{\"tooltip\":\"内部仓库：添加到平台的代码仓库，外部仓库：未导入平台的仓库，可通过url添加\",\"colon\":false},\"name\":\"serviceType\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"仓库来源\",\"x-index\":0,\"enum\":[{\"children\":[],\"label\":\"内部\",\"value\":\"1\"},{\"children\":[],\"label\":\"外部\",\"value\":\"2\"}]},\"gitUrl\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"hbxlvnz3b7o\",\"x-decorator-props\":{\"tooltip\":\"外部仓库代码克隆http地址\",\"colon\":false},\"name\":\"gitUrl\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.serviceType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"serviceType\",\"source\":\"serviceType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{\"placeholder\":\"例如 https://github.com/randx/six.git\"},\"type\":\"string\",\"title\":\"GIT仓库地址\",\"x-index\":1,\"required\":true},\"gitCredentialId\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"r2uzzcvp5tz\",\"x-decorator-props\":{\"asterisk\":false,\"tooltip\":\"Git仓库用户密码或ssh凭证。可在持续交付-凭证管理菜单添加凭证\",\"colon\":false},\"name\":\"gitCredentialId\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.gitUrl) {\\n    $self.loading = true\\n    const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n    // $self.value = \\\"\\\"\\n    fetch(\\n      `${window.location.origin}/api/efficiency/deploy/credentials/list?type=0`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"\\\",\\n            label: k.credentialName,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.gitUrl])\\n\",\"state\":{\"visible\":\"{{$deps.serviceType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"serviceType\",\"source\":\"serviceType\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"gitUrl\",\"source\":\"gitUrl\",\"type\":\"string\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"连接凭证\",\"x-index\":2,\"required\":true},\"serverId\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"7nos94rv47l\",\"x-decorator-props\":{\"tooltip\":\"平台支持管理多个Git仓库服务,请先选择仓库所在Git服务\",\"colon\":false},\"name\":\"serverId\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  \\n  fetch(`${window.location.origin}/api/code/api/open/codeserver`,{\\n      headers: {\\\"Amp-Organ-Id\\\": orgId,Authorization: token },\\n      }\\n  )\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({ ...k, value: k.id, label: k.name }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\\n$effect(() => {\\n  if($deps.serviceType == \'0\'){\\n    $self.value = \'\'\\n  }\\n}, [$deps.serviceType])\\n\",\"state\":{\"visible\":\"{{$deps.serviceType == \'1\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"serviceType\",\"source\":\"serviceType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{\"showSearch\":true},\"title\":\"GIT服务器\",\"x-index\":3,\"required\":true},\"gitlabId\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"o9oni6zr02j\",\"x-decorator-props\":{\"tooltip\":\"请先在代码仓库菜单导入或新建仓库\",\"colon\":false},\"name\":\"gitlabId\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  productType: \\\"\\\",\\n})\\n$effect(() => {\\n  if ($deps.serverId) {\\n    $self.loading = true\\n    if (state.productType == \\\"\\\") {\\n      state.productType = \\\"1\\\"\\n    } else {\\n      $self.value = \\\"\\\"\\n    }\\n    // $self.value = \\\"\\\"\\n    const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n   \\n    fetch(\\n      `${window.location.origin}/api/code/api/open/codeserver/projects/list?serverId=${$deps.serverId}`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId,Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"|\\\" + k.httpUrlToRepo,\\n            label: k.pathWithNamespace,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.serverId])\\n\",\"state\":{\"visible\":\"{{// !!$deps.server && ($deps.serviceType == \'1\')\\n$deps.serviceType == \'1\'\\n}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"serviceType\",\"source\":\"serviceType\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"serverId\",\"source\":\"serverId\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{\"showSearch\":true},\"title\":\"代码仓库\",\"x-index\":4,\"required\":true},\"dmkl_dev1\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"4g4364mapw2\",\"x-reactions\":{\"fulfill\":{\"state\":{\"componentProps\":\"{{{\\n  style: {\\n    position: \'relative\'\\n  }\\n}}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"dmkl_dev1\",\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":5,\"properties\":{\"branch\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"q9roi0y7kre\",\"x-decorator-props\":{\"tooltip\":\"支持选择已有分支或者设置为启动变量，例如${branch}，在执行流水线时指定分支\",\"colon\":false,\"addonBefore\":\"\",\"addonAfter\":\"\"},\"name\":\"branch\",\"x-reactions\":{\"fulfill\":{\"run\":\"\\n$effect(() => {\\n \\n  const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  \\n  if ($deps.serverId && $deps.gitlabId) {\\n    $self.loading = true\\n    \\n    var stageStr = window.sessionStorage.getItem(\\\"pipelineStageInfo\\\")\\n    if (stageStr != null && stageStr != \\\"{}\\\") {\\n      var stageInfo = JSON.parse(stageStr)\\n      stageInfo.gitlabId = $deps.gitlabId\\n      stageInfo.serverId = $deps.serverId\\n      stageStr = JSON.stringify(stageInfo)\\n      window.sessionStorage.setItem(\\\"pipelineStageInfo\\\", stageStr)\\n    }else{\\n      var stageInfo = {}\\n      stageInfo.gitlabId = $deps.gitlabId\\n      stageInfo.serverId = $deps.serverId\\n      stageStr = JSON.stringify(stageInfo)\\n      window.sessionStorage.setItem(\\\"pipelineStageInfo\\\", stageStr)\\n    }\\n\\n\\n    \\n    // $self.value = \\\"\\\"\\n    var project_id = $deps.gitlabId.split(\\\"|\\\")[0]\\n    console.log(project_id)\\n    fetch(\\n      `${window.location.origin}/api/code/branch/list?gitlabId=${project_id}&serverId=${$deps.serverId}`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId,Authorization: token ,\\\"X-SCM-TOKEN\\\":\\\"SCM@2023\\\"},\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re =\\n            data.map((k) => ({\\n              ...k,\\n              value: k.name,\\n              label: k.name,\\n            })) || []\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }else if($deps.gitUrl && $deps.gitCredentialId){\\n    var stageStr = window.sessionStorage.getItem(\\\"pipelineStageInfo\\\")\\n    if (stageStr != null && stageStr != \\\"{}\\\") {\\n      var stageInfo = JSON.parse(stageStr)\\n      stageInfo.gitUrl = $deps.gitUrl\\n      stageInfo.gitCredentialId = $deps.gitCredentialId\\n      stageStr = JSON.stringify(stageInfo)\\n      window.sessionStorage.setItem(\\\"pipelineStageInfo\\\", stageStr)\\n    }else{\\n      var stageInfo = {}\\n      stageInfo.gitUrl = $deps.gitUrl\\n      stageInfo.gitCredentialId = $deps.gitCredentialId\\n      stageStr = JSON.stringify(stageInfo)\\n      window.sessionStorage.setItem(\\\"pipelineStageInfo\\\", stageStr)\\n    }\\n    fetch(\\n      `${window.location.origin}/api/efficiency/accessController/findOutGitlabBranch?repoUrl=${$deps.gitUrl}&credentialId=${$deps.gitCredentialId}`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId,Authorization: token ,\\\"X-SCM-TOKEN\\\":\\\"SCM@2023\\\"},\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k,\\n            label: k,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n\\n  }\\n}, [$deps.serverId, $deps.gitlabId,$deps.gitUrl,$deps.gitCredentialId])\\n\",\"state\":{\"visible\":\"{{ !!!$deps.dmkl_btn_1}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"serviceType\",\"source\":\"serviceType\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"gitUrl\",\"source\":\"gitUrl\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"gitCredentialId\",\"source\":\"gitCredentialId\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"serverId\",\"source\":\"serverId\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"gitlabId\",\"source\":\"gitlabId\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"dmkl_btn_1\",\"source\":\"dmkl_dev1.dmkl_dev1_1.dmkl_btn_1\",\"type\":\"boolean\"},{\"property\":\"value\",\"name\":\"startParamName_branch\",\"source\":\"dmkl_dev1.startParamName_branch\",\"type\":\"string\"}]},\"x-validator\":[],\"x-component-props\":{\"showSearch\":true},\"title\":\"分支\",\"x-index\":0,\"required\":true,\"enum\":[{\"children\":[],\"label\":\"选项 1\",\"value\":\"yemz9cyj2l7\"}]},\"startParamName_branch\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"kvkz2tpa9bi\",\"x-decorator-props\":{\"tooltip\":\"支持选择已有分支或者设置为启动变量，例如${branch}，在执行流水线时指定分支\",\"colon\":false},\"x-reactions\":{\"fulfill\":{\"run\":\"\",\"state\":{\"visible\":\"{{ !!$deps.dmkl_btn_1}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"dmkl_btn_1\",\"source\":\"dmkl_dev1.dmkl_dev1_1.dmkl_btn_1\",\"type\":\"boolean\"},{\"property\":\"value\",\"name\":\"branch\",\"source\":\"dmkl_dev1.branch\",\"type\":\"any\"}]},\"name\":\"startParamName_branch\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"分支\",\"x-index\":1,\"required\":true},\"dmkl_dev1_1\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"0xojzstugs7\",\"x-reactions\":{\"fulfill\":{\"state\":{\"componentProps\":\"{{{\\n  style: {\\n    position: \'absolute\',\\n    top: -5,\\n    right: 0,\\n    zIndex: 10000,\\n    width: 74,\\n    cursor: \'pointer\',\\n    color: \'#226ee7\',\\n  }\\n}}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"dmkl_dev1_1\",\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":2,\"properties\":{\"dmkl_btn1\":{\"x-component\":\"Text\",\"x-designable-id\":\"9vjj7yhe68d\",\"x-decorator\":\"FormItem\",\"x-decorator-props\":{\"wrapperWrap\":false,\"labelWrap\":false,\"inset\":false,\"feedbackLayout\":\"none\",\"wrapperAlign\":\"left\"},\"name\":\"dmkl_btn1\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  updateFlag: false\\n})\\n\\n\\n$props({\\n  onClick() {\\n    state.updateFlag = true\\n    $form.fields[\'dmkl_dev1.dmkl_dev1_1.dmkl_btn_1\'].value = !$form.fields[\'dmkl_dev1.dmkl_dev1_1.dmkl_btn_1\'].value\\n  }\\n})\\n\\n\\n\\n\\n$effect(()=>{\\n  if($form.fields[\'dmkl_dev1.dmkl_dev1_1.dmkl_btn_1\'].value){\\n    $self.value = \'选择已有\'\\n    $form.fields[\'dmkl_dev1.branch\'].value=\'\'\\n    if(state.updateFlag && !$form.fields[\'dmkl_dev1.startParamName_branch\'].value){\\n      $form.fields[\'dmkl_dev1.startParamName_branch\'].value = \'${branch}\'\\n    }\\n    if(!$form.fields[\'dmkl_dev3.dmkl_dev3_1.dmkl_btn_3\'].value){\\n      $form.fields[\'dmkl_dev3.dmkl_dev3_1.dmkl_btn_3\'].value = true\\n    }\\n  }else{\\n    if(state.updateFlag){\\n      $self.value = \'设置为变量\'\\n      $form.fields[\'dmkl_dev1.startParamName_branch\'].value=\'\'\\n    }\\n  }\\n},[$form.fields[\'dmkl_dev1.dmkl_dev1_1.dmkl_btn_1\']?.value])\\n\",\"state\":{\"value\":\"{{\'设置为变量\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"content\":\"设置为变量\"},\"type\":\"string\",\"x-index\":0},\"dmkl_btn_1\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Switch\",\"x-designable-id\":\"bzfl17kg6o7\",\"x-decorator-props\":{},\"name\":\"dmkl_btn_1\",\"x-reactions\":{\"fulfill\":{\"state\":{\"hidden\":\"{{true}}\"}},\"dependencies\":[]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"\",\"x-index\":1}}}}},\"gitPath\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"g4ykprlb0vv\",\"x-decorator-props\":{\"tooltip\":\"代码仓库文件会被下载至工作目录，默认下载到\\\"./\\\" 目录。如果流水线需要下载多个代码仓库，请设置不同的工作目录，避免覆盖\",\"colon\":false},\"name\":\"gitPath\",\"x-reactions\":{\"fulfill\":{\"run\":\"\",\"state\":{}},\"dependencies\":[]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"工作路径\",\"x-index\":6}},\"x-designable-id\":\"clzw3unjzcl\"}}]', '{\"name\":\"gitClone\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"serviceType\"},\"key\":\"serviceType\"},{\"value\":{\"isLiteral\":true,\"value\":\"gitUrl\"},\"key\":\"gitUrl\"},{\"value\":{\"isLiteral\":true,\"value\":\"gitCredentialId\"},\"key\":\"gitCredentialId\"},{\"value\":{\"isLiteral\":true,\"value\":\"serverId\"},\"key\":\"serverId\"},{\"value\":{\"isLiteral\":true,\"value\":\"gitlabId\"},\"key\":\"gitlabId\"},{\"value\":{\"isLiteral\":true,\"value\":\"branch\"},\"key\":\"branch\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_branch\"},\"key\":\"startParamName_branch\"},{\"value\":{\"isLiteral\":true,\"value\":\"dmkl_btn1\"},\"key\":\"dmkl_btn1\"},{\"value\":{\"isLiteral\":true,\"value\":\"dmkl_btn_1\"},\"key\":\"dmkl_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"gitPath\"},\"key\":\"gitPath\"}],\"stepFunc\":\"gitClone\"}', '', '将代码仓库文件下载至流水线工作目录，作为代码源，可用于执行单元测试、扫描代码质量、构建制品等任务', 1, 0, '2022-02-24 20:41:28', '2024-12-27 11:18:59', NULL, 1, 'gitClone', '3', '2', '2', 'import org.codehaus.groovy.runtime.GStringImpl\nimport java.net.URLEncoder\n\ndef call(def map){\n    //处理历史数据\n    if(map.branch_1 || map.branch_2){\n        call(map.stepName,map.serviceType,map.gitUrl,map.gitCredentialId,map.branch_1,map.serverId,map.gitlabId,map.branch_2,map.startParamName_branch,map.gitPath)\n        echo env.endString\n    }else{\n        def branch = \'\'\n        if(map.startParamName_branch){\n            if(map.startParamName_branch instanceof GStringImpl){\n                branch = map.startParamName_branch\n            }else{\n                branch = env[map.startParamName_branch]\n            }\n        }else{\n            branch = map.branch\n        }\n        call(map.stepName,map.serviceType,map.gitUrl,map.gitCredentialId,branch,map.serverId,map.gitlabId,branch,\'\',map.gitPath)\n        echo env.endString\n    }\n}\n\ndef call(String gitServerId,String gitGitLabId,String gitRepo,String gitBranch){\n    if(gitServerId == \'\'){\n        gitServerId = \'2194058592970518528\'\n    }\n    if(env.branch){\n        gitBranch = env.branch\n    }\n    if(env.git_merge_out_branch){\n         echo \"----git_merge_out_branch:${env.git_merge_out_branch}-----\"\n        gitBranch = env.git_merge_out_branch\n    }\n   if(env.mergeGitCredentialId){\n        env.gitCreadentId = env.mergeGitCredentialId\n    }\n    sh \"git config --global http.sslVerify false\"\n    \n    cloneCode(gitRepo,gitBranch,env.gitCreadentId)\n    if(env.gitCommitId){\n        sh \"git checkout -b  ${env.gitCommitId} ${env.gitCommitId}\"\n    }\n    //通知流水线serviceId、gitlabId、commitId\n    def commitId = sh(returnStdout: true ,script: \'git rev-parse --verify HEAD\').replaceAll(\"\\\\s+\", \"\")\n    sh \"\"\"\n    curl -X POST \"${env.pipelineSvcUrl}/devops/pipeline/${env.job_id}/${env.BUILD_NUMBER}/commitId?serverId=${gitServerId}&gitLabId=${gitGitLabId}&commitId=${commitId}\" --data-urlencode \"branch=${gitBranch}\" --data-urlencode \"gitRepo=${gitRepo}\" -H \"accept: */*\" -d \"\"\n    \"\"\"\n    env.mergeBranch = gitBranch\n    env.mergeCommitId = commitId\n    env.mergeServerId = gitServerId\n    env.mergeGitlabId = gitGitLabId\n    env.gitLabId = gitGitLabId\n    env.mergeGitCredentialId = env.gitCreadentId\n    env.gitRepo = gitRepo\n    projectNameCreate()\n}\ndef call(String stepName,String type,String gitUrl,String credentialId,String branch1,String gitServerId ,String gitGitLabId,String branch2){\n   if(type == \'2\'){\n       def response = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.pipelineSvcUrl}/deploy/credentials/${credentialId}/aesPassword\" -H \"accept: */*\"  \n        \"\"\")    \n        def resData = readJSON text: \"\"\"${response}\"\"\"\n        if(resData.code != 0){\n            error \"查询凭证对应用户信息报错\"\n        }\n        userName = resData.data.name\n        password = resData.data.password\n        \n       call(stepName,type,gitUrl,userName,password,branch1,gitServerId,gitGitLabId,branch2)\n   }else{\n       call(stepName,type,gitUrl,\'\',\'\',branch1,gitServerId,gitGitLabId,branch2)\n   } \n   \n}\n\n\n/**\n * 定义一个可以本地使用的\n */\ndef call(String stepName,String type,String gitUrl,String gitUser,String password,String branch1,String gitServerId ,String gitGitLabId,String branch2){\n     echo \"代码克隆\"\n    if(gitServerId == \'\'){\n        gitServerId = \'2194058592970518528\'\n    }\n//    def branch = branch1\n    def credentialsId = env.gitCreadentId\n    if( type == \'1\'){\n        gitUrl = gitGitLabId.split(\"\\\\|\")[1]\n//        branch = branch2\n    }else{\n        //根据用户名、密码和jobId来动态查询凭证id\n        def response = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.pipelineSvcUrl}/deploy/credentials/gitCredentialsId?jobId=${params.job_id}&gitUserName=${gitUser}&gitPassword=${password}\" -H \"accept: */*\"\n        \"\"\")\n        def resData = readJSON text: \"\"\"${response}\"\"\"\n        credentialsId = resData.data\n    }\n    \n    def branch = master\n    \n    \n    \n    if(env.branchStartParam && env.branchStartParam == \'false\'){\n        if(type == \'1\'){\n           branch = branch2 \n        }else{\n           branch = branch1 \n        }\n        \n    }\n    if(env.git_merge_out_branch){\n         echo \"----git_merge_out_branch:${env.git_merge_out_branch}-----\"\n        branch = env.git_merge_out_branch\n    }\n   sh \"git config --global http.sslVerify false\"\n    cloneCode(gitUrl,branch,credentialsId)\n    //通知流水线serviceId、gitlabId、commitId\n    def commitId = sh(returnStdout: true ,script: \'git rev-parse --verify HEAD\').replaceAll(\"\\\\s+\", \"\")     \n    env.mergeCommitId = commitId\n    env.mergeGitCredentialId = credentialsId\n    if(type == \'1\'){\n        gitGitLabId = gitGitLabId.split(\"\\\\|\")[0]\n        sh \"\"\"\n        curl -X POST \"${env.pipelineSvcUrl}/devops/pipeline/${params.job_id}/${env.BUILD_NUMBER}/commitId?serverId=${gitServerId}&gitLabId=${gitGitLabId}&commitId=${commitId}\" --data-urlencode \"branch=${branch}\" --data-urlencode \"gitRepo=${gitUrl}\" -H \"accept: */*\" -d \"\" \n        \"\"\"\n        env.mergeServerId = gitServerId\n        env.mergeGitlabId = gitGitLabId\n        env.gitLabId = gitGitLabId\n    }\n    env.gitRepo = gitUrl\n    env.mergeBranch = branch\n    projectNameCreate()\n}\n\n\ndef call(String stepName,String type,String gitUrl,String credentialId,String branch1,String gitServerId ,String gitGitLabId,String branch2,String branchName,String path){\n    \n    echo \"代码克隆\"\n    echo \"${branch1} ${branch2}\"\n    if(gitServerId == \'\'){\n        gitServerId = \'2194058592970518528\'\n    }\n    def branch = branch1\n    def credentialsId = env.gitCreadentId\n    if( type == \'1\'){\n        gitUrl = gitGitLabId.split(\"\\\\|\")[1]\n        branch = branch2\n    }else{\n        //根据用户名、密码和jobId来动态查询凭证id\n		response = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.pipelineSvcUrl}/deploy/credentials/${credentialId}/aesPassword\" -H \"accept: */*\"  \n        \"\"\")    \n        resData = readJSON text: \"\"\"${response}\"\"\"\n        if(resData.code != 0){\n            error \"查询凭证对应用户信息报错\"\n        }\n        def gitUser = resData.data.name\n        def password = resData.data.password\n        password = URLEncoder.encode(password, \"UTF-8\")\n\n        response = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.pipelineSvcUrl}/deploy/credentials/gitCredentialsId?jobId=${env.job_id}&gitUserName=${gitUser}&gitPassword=${password}\" -H \"accept: */*\"\n        \"\"\")\n        resData = readJSON text: \"\"\"${response}\"\"\"\n        credentialsId = resData.data\n    }\n    \n	if(branchName){\n		branch = env[branchName]\n	}\n	\n    \n    if(env.branchStartParam && env.branchStartParam == \'false\'){\n        if(type == \'1\'){\n           branch = branch2 \n        }else{\n           branch = branch1 \n        }\n    }\n    if(env.git_merge_out_branch){\n         echo \"----git_merge_out_branch:${env.git_merge_out_branch}-----\"\n        branch = env.git_merge_out_branch\n    }\n    \n    if(!path){\n        path = env.WORKSPACE\n    }\n    echo \"使用分支： ${branch}\"\n	echo \"使用凭据：${credentialsId}\"\n    sh \"git config --global http.sslVerify false\"\n    dir(\"${path}\"){\n        // sh \"mkdir -p /root/.ssh\"\n        // sh \"ssh-keyscan -p 31222 10.10.103.61 >> /root/.ssh/known_hosts\"\n        // withCredentials([sshUserPrivateKey(credentialsId: \'sshKey\', keyFileVariable: \'SSH_KEY\')]) {\n        //     sh \"ssh-agent bash -c \'ssh-add ${SSH_KEY}; git clone ${gitUrl} ./\'\"\n        // }\n      \n        //通知流水线serviceId、gitlabId、commitId\n        cloneCode(gitUrl,branch,credentialsId)\n        echo \"完成克隆\"\n        def commitId = sh(returnStdout: true ,script: \'git rev-parse --verify HEAD\').replaceAll(\"\\\\s+\", \"\")\n        env.mergeCommitId = commitId\n        env.mergeBranch = branch\n        env.mergeGitCredentialId = credentialsId\n    }\n    \n   \n    \n    if(type == \'1\'){\n        gitGitLabId = gitGitLabId.split(\"\\\\|\")[0]\n        sh \"\"\"\n        curl -X POST \"${env.pipelineSvcUrl}/devops/pipeline/${env.job_id}/${env.BUILD_NUMBER}/commitId?serverId=${gitServerId}&gitLabId=${gitGitLabId}&commitId=${env.mergeCommitId}\" --data-urlencode \"branch=${branch}\" --data-urlencode \"gitRepo=${gitUrl}\" -H \"accept: */*\" -d \"\" \n        \"\"\"\n        env.mergeServerId = gitServerId\n        env.mergeGitlabId = gitGitLabId\n        env.gitLabId = gitGitLabId\n    }\n    env.gitRepo = gitUrl\n    projectNameCreate()\n}\n\n\ndef projectNameCreate(){\n    if(env.gitLabId){\n        def response = sh returnStdout: true ,script:\"\"\"\n        curl -X GET \"${env.scmSvcUrl}/project/${env.gitLabId}?serverId=${env.mergeServerId}\" -H \"accept: */*\" -H \"X-SCM-TOKEN: SCM@2023\" -H \"Amp-Organ-Id: ${env.tenantId}\"\n        \"\"\"\n        def resData = readJSON text: \"\"\"${response}\"\"\"\n        if(resData.code != 0){\n            error \"调用代码库服务查询项目信息报错：${resData.msg}\" \n        }\n        env.gitlabProjectName = resData.data.name\n    }else{\n       \n       def arr = env.gitRepo.split(\'/\') \n       def projectName = arr[arr.size() -1]\n       env.gitlabProjectName = projectName.split(\'\\\\.\')[0]\n    }\n}\n\ndef cloneCode(String gitUrl,String branch,String credentialsId){\n    if(false){\n       checkout([$class: \"GitSCM\",\n          branches: [[name: branch]],\n          userRemoteConfigs: [[credentialsId: credentialsId, url: gitUrl]],\n          extensions: [[$class: \'CloneOption\', depth: 1]]]) \n    }else{\n        withCredentials([usernamePassword(credentialsId: credentialsId,passwordVariable: \'gitpassword\', usernameVariable: \'gitusername\')]) {\n            def encodedCredentials = \"${URLEncoder.encode(gitusername, \'UTF-8\')}:${URLEncoder.encode(gitpassword, \'UTF-8\')}\".toString()\n            echo \"用户名密码：${encodedCredentials}\"\n            def httpTail = \'\'\n            def gitUrlEnd = \'\'\n            if(gitUrl.startsWith(\"http://\")){\n                gitUrlEnd = gitUrl.substring(7)\n                httpTail = \"http://\"\n            }else if(gitUrl.startsWith(\"https://\")){\n                gitUrlEnd = gitUrl.substring(8)\n                httpTail =  \"https://\"\n            }\n            def credentialsUrl = \"${httpTail}${encodedCredentials}@${gitUrlEnd}\"\n            branch=branch.replace(\"refs/heads/\",\"\")\n\n            sh \"\"\"\n            set +x\n            git clone --depth 1 --branch ${branch} ${credentialsUrl} ./\n            set -x\n            \"\"\"\n        }\n    \n    }\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (212, 1010, '启动流水线', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"array_jobName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"hzgx5k8opzw\",\"x-decorator-props\":{\"tooltip\":\"调用Jenkins流水线，支持多选\"},\"name\":\"array_jobName\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  const pipelineEnvInfo = localStorage.getItem(\\\"pipelineEnvInfo\\\") || \\\"{}\\\"\\n  var envId = \\\"\\\"\\n  if (pipelineEnvInfo != \\\"{}\\\") envId = JSON.parse(pipelineEnvInfo).id || \\\"\\\"\\n\\n  const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n\\n  $self.loading = true\\n  fetch(\\n    `${window.location.origin}/api/efficiency/devops/pipeline/jobs/list?envId=${envId}`,\\n    {\\n      headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n    }\\n  )\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        $self.loading = false\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"|\\\" + k.jobName,\\n          label: k.jobName,\\n        }))\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{\"mode\":\"multiple\",\"showSearch\":true},\"title\":\"任务名称\",\"x-index\":0,\"required\":true}},\"x-designable-id\":\"324vbgphrvt\"}}]', '{\"name\":\"jenkinsBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"array_jobName\"},\"key\":\"array_jobName\"}],\"stepFunc\":\"jenkinsBuild\"}', NULL, '触发其他流水线执行', 1, 0, '2022-11-10 20:54:05', '2024-02-04 16:38:57', NULL, 1, 'jenkinsBuild', '0', '2', '2', 'def call(def map){\n    \n    call(map.stepName,map.jobName)\n}\n\ndef call(String stepName,String jobName){\n    arr = jobName.split(\",\")\n    for(String job: arr){\n        arr2 = job.split(\"\\\\|\")\n        def res = build job: arr2[1], parameters: []\n        println res.result\n        repo = sh returnStdout: true ,script: \"\"\"\n            curl -X GET \"${env.pipelineSvcUrl}/devops/pipeline/jobs/${arr2[0]}/builds/${res.id}\" -H \"accept: */*\"\n            \"\"\"\n        def resData = readJSON text: \"\"\"${repo}\"\"\"\n        println \"---------------------------------------流水线日志分割，下面为：\"+arr2[1]+\"日志------------------------------------------------------------\"\n        println resData.data\n        println \"---------------------------------------\"+arr2[1]+\"日志结束------------------------------------------------------------\"\n\n        if (res.result != \"SUCCESS\"){\n            error \"流水线${arr2[1]}调用失败!!!\"\n        }\n    }\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (213, 1005, '配置克隆', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"configRepo\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"4b0rj7zj7gw\",\"x-decorator-props\":{},\"name\":\"configRepo\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  fetch(`${window.location.origin}/api/code/api/config/list`, {\\n    headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.serverId + \\\"|\\\" + k.gitlabId,\\n          label: k.projectName,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"配置库\",\"x-index\":0,\"required\":true},\"configEnv\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"h892quteela\",\"x-decorator-props\":{},\"name\":\"configEnv\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  if ($deps.configRepo) {\\n    // $self.value = \\\"\\\"\\n    var arr = $deps.configRepo.split(\\\"|\\\")\\n    var serverId = arr[0]\\n    var projectId = arr[1]\\n    const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  \\n    \\n    fetch(\\n      `${window.location.origin}/api/code/api/open/codeserver/${serverId}/${projectId}/branches`,{\\n      headers: {\\\"Amp-Organ-Id\\\": orgId,Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re =\\n            data.content\\n            .filter(k => !k.branch.name.startsWith(\'dev_\') && !k.branch.name.endsWith(\'_template\')) \\n            .map((k) => ({\\n              ...k,\\n              value: k.branch.name,\\n              label: k.branch.name,\\n            })) || []\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.configRepo])\\n\",\"state\":{}},\"dependencies\":[{\"property\":\"value\",\"name\":\"configRepo\",\"source\":\"configRepo\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"环境\",\"x-index\":1,\"required\":true},\"configPath\":{\"default\":\"config/\",\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"n46rzy7023p\",\"x-decorator-props\":{},\"name\":\"configPath\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"文件路径\",\"x-index\":2,\"required\":true}},\"x-designable-id\":\"ddhb0oghov1\"}}]', '{\"name\":\"configRepo\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"configRepo\"},\"key\":\"configRepo\"},{\"value\":{\"isLiteral\":true,\"value\":\"configEnv\"},\"key\":\"configEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"configPath\"},\"key\":\"configPath\"}],\"stepFunc\":\"configRepo\"}', NULL, '从配置库中拉取配置文件', 1, 0, '2022-11-22 17:16:21', '2024-06-25 10:55:21', 1, 1, 'configRepo', '0', '2', '2', 'def call(def map){\n  call(map.stepName,map.configRepo,map.configEnv,map.configPath)  \n    echo env.endString\n\n}\n\ndef call(String stepName,String configRepo,String configEnv,String path){\n    arr = configRepo.split(\"\\\\|\")\n\n    def userPasswordRepon = sh returnStdout: true ,script: \"\"\"\n    curl -X GET \"${env.scmSvcUrl}/api/open/codeserver/${arr[0]}\" -H \"X-SCM-TOKEN: SCM@2023\" -H \"Amp-Organ-Id: ${env.tenantId}\" -H \"accept: */*\"\n    \"\"\"\n    userPassword = readJSON text: \"\"\"${userPasswordRepon}\"\"\"\n    gitUser = sh (returnStdout: true ,script: \"\"\"\n    set +x\n    echo ${userPassword.data.adminName} | base64 -d\n    set -x\n    \"\"\").trim()\n\n    gitPassword = sh (returnStdout: true ,script: \"\"\"\n    set +x\n    echo ${userPassword.data.adminPassword} | base64 -d\n    set -x\n    \"\"\").trim()\n    def urlRepon = sh returnStdout: true ,script: \"\"\"\n    curl -X GET \"${env.scmSvcUrl}/api/open/codeserver/projects/${arr[1]}\" -H \"X-SCM-TOKEN: SCM@2023\" -H \"Amp-Organ-Id: ${env.tenantId}\" -H \"accept: */*\"\n    \"\"\"\n    echo \"${urlRepon}\"\n    urlInfo = readJSON text: \"\"\"${urlRepon}\"\"\"\n    gitUrl = urlInfo.data.internalUrl\n    env.configRepoId = arr[1]\n    env.configRepoName = urlInfo.data.name\n    env.configRepoEnv = configEnv\n    echo \"gitUrl 地址：${gitUrl}\"\n    httpTail = \'\'\n    if(gitUrl.startsWith(\"http://\")){\n        gitUrl = gitUrl.substring(7)\n        httpTail = \"http://\"\n    }else if(gitUrl.startsWith(\"https://\")){\n        gitUrl = gitUrl.substring(8)\n        httpTail =  \"https://\"\n    }\n    echo \"---2-----${gitUrl}\"\n    //根据serverId 和gitlabId获取访问地址\n    sh \"rm -rf ${path}\"\n    sh \"\"\"\n    set +x\n    git clone  --depth 1 --branch ${configEnv} ${httpTail}${gitUser}:${gitPassword}@${gitUrl} ${path}\n    set -x\n    \"\"\"\n    sh \"ls ${path}\"\n    \n    \n    def commitId = sh(returnStdout: true ,script: \"cd ${path} && git rev-parse --verify HEAD\").trim()\n    env.configRepoCommitId = commitId\n    //直接保存\n    if(!env.configCloneCommand){\n       env.configCloneCommand = \'\'\n    }\n     env.configCloneCommand = env.configCloneCommand + \"rm -rf ${path}<br/>git clone  --branch ${configEnv} ${httpTail}${gitUser}:${gitPassword}@${gitUrl} ${path}<br/>cd ${path} <br/> git checkout -b ${commitId} ${commitId}<br/>\"\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (214, 1003, '依赖检测分析', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"dependLanguage\":{\"default\":\"java\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"gz5qd7z9ll6\",\"x-decorator-props\":{\"tooltip\":\"语言选择\"},\"name\":\"dependLanguage\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"语言\",\"x-index\":0,\"required\":true,\"enum\":[{\"children\":[],\"label\":\"java\",\"value\":\"java\"},{\"children\":[],\"label\":\"js\",\"value\":\"js\"},{\"children\":[],\"label\":\"go\",\"value\":\"go\"},{\"children\":[],\"label\":\"php\",\"value\":\"php\"}]},\"scanPath\":{\"default\":\".\",\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"e4z8c9ol8qq\",\"x-decorator-props\":{},\"name\":\"scanPath\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"分析目录\",\"x-index\":1,\"required\":true},\"extend\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"3z541419zmf\",\"x-decorator-props\":{\"tooltip\":\"填写额外的构建参数，不需要填写构建命令\"},\"name\":\"extend\",\"description\":\"\",\"x-validator\":[],\"x-component-props\":{\"placeholder\":\"\"},\"type\":\"string\",\"title\":\"构建参数\",\"x-index\":2},\"deepAnalysis\":{\"x-component\":\"Switch\",\"x-designable-id\":\"rjymd4i4eg3\",\"x-decorator-props\":{\"tooltip\":\"分析间接依赖，需要先编译构建成功\"},\"description\":\"\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"深层依赖分析\",\"x-index\":3,\"required\":true,\"default\":true,\"x-decorator\":\"FormItem\",\"name\":\"deepAnalysis\"},\"doorFlag\":{\"x-component\":\"Switch\",\"x-designable-id\":\"o9pxai4spvc\",\"x-decorator-props\":{\"tooltip\":\"\"},\"description\":\"开启质量门禁，检查不通过时终止流水线构建\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"质量门禁\",\"x-index\":4,\"required\":false,\"default\":true,\"x-decorator\":\"FormItem\",\"name\":\"doorFlag\"}},\"x-designable-id\":\"r7w0i6yglyd\"}}]', '{\"name\":\"dependAnsysial\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"dependLanguage\"},\"key\":\"dependLanguage\"},{\"value\":{\"isLiteral\":true,\"value\":\"scanPath\"},\"key\":\"scanPath\"},{\"value\":{\"isLiteral\":true,\"value\":\"extend\"},\"key\":\"extend\"},{\"value\":{\"isLiteral\":true,\"value\":\"deepAnalysis\"},\"key\":\"deepAnalysis\"},{\"value\":{\"isLiteral\":true,\"value\":\"doorFlag\"},\"key\":\"doorFlag\"}],\"stepFunc\":\"dependAnsysial\"}', NULL, '扫描项目中的第三方依赖及漏洞信息、检测许可证风险，扫描完成后会生成报告 ', 1, 0, '2022-11-22 11:07:02', '2024-02-21 16:40:50', 1, 1, 'dependAnsysial', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.dependLanguage,map.scanPath,map.extend,map.deepAnalysis,map.doorFlag)\n    echo env.endString\n\n}\n\ndef call(String stepName,String language){\n    sh \"\"\"\n    curl -O ${env.trustworthySvcUrl}/api/app/collector\n    unzip -n collector\n    \"\"\"\n    command = \"./hawkeye-linux scan \"\n    if(params.buildId){\n        command += \" -s ${params.buildId}\"\n    }\n    if(env.gitCommitId){\n        command += \" -m ${env.gitCommitId}\"\n    }\n    if(env.gitlabId){\n        command += \" -c ${env.gitlabId}\"\n    }\n    if(env.tenantId){\n        command += \" -o ${env.tenantId}\"\n    }\n    if (env.gitlabProjectName){\n        command += \" -n ${env.gitlabProjectName}\"\n    }\n    sh \"\"\"\n    ${command} -r ${env.trustworthySvcUrl} ./\n    \"\"\"\n}\ndef call(String stepName,String language, String scanPath, String extend, boolean deepAnalysis){\n    sh \"\"\"\n    curl -O ${env.trustworthySvcUrl}/api/app/collector\n    unzip -n collector\n    \"\"\"\n    command = \"./hawkeye-linux scan \"\n    if(env.buildId){\n        command += \" -s ${env.buildId}\"\n    }\n    if(env.gitCommitId){\n        command += \" -m ${env.gitCommitId}\"\n    }\n    if(env.gitlabId){\n        command += \" -c ${env.gitlabId}\"\n    }\n    if(env.tenantId){\n        command += \" -o ${env.tenantId}\"\n    }\n    if(extend){\n        command = command+\" -e \"+extend\n    }\n    sh \"\"\"\n    ${command} -r ${env.trustworthySvcUrl} -d ${deepAnalysis}  ${scanPath}\n    \"\"\"\n}\ndef call(String stepName,String language, String scanPath, String extend, boolean deepAnalysis, boolean doorFlag){\n    sh \"\"\"\n    curl -O ${env.trustworthySvcUrl}/api/app/collector\n    unzip -n collector\n    \"\"\"\n    command = \"./hawkeye-linux scan \"\n    if(buildId){\n        command += \" -s ${params.buildId}\"\n    }\n    if(env.gitCommitId){\n        command += \" -m ${env.gitCommitId}\"\n    }\n    if(env.gitlabId){\n        command += \" -c ${env.gitlabId}\"\n    }\n    if(env.tenantId){\n        command += \" -o ${env.tenantId}\"\n    }\n    if(extend){\n        command = command+\" -e \"+extend\n    }\n\n    sh \"\"\"\n    ${command} -r ${env.trustworthySvcUrl} -d ${deepAnalysis}  --gate=${doorFlag} ${scanPath}\n    \"\"\"\n      if (doorFlag) {\n        timeout(time: 30, unit: \'MINUTES\') {\n            input(message: \'\', id: \'input\', ok: \'\', submitter: \'admin\')\n        }\n\n    }\n\n    \n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (215, 1004, 'C#制品上传', '[{\"form\":{\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"nexusRepo\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"s5fuyp0m0t1\",\"x-decorator-props\":{\"tooltip\":\"net5制品仓库\"},\"name\":\"nexusRepo\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  fetch(`${window.location.origin}/api/warehouse/api/repository/nuget`,{\\n      headers: {Authorization: token },\\n      })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.url,\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"制品仓库\",\"x-index\":0,\"required\":true}},\"x-designable-id\":\"dgo9t583y8e\"}}]', '{\"name\":\"nugetProductUpload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"nexusRepo\"},\"key\":\"nexusRepo\"}],\"stepFunc\":\"nugetProductUpload\"}', NULL, 'C# 二方库nuget制品上传', 1, 0, '2022-11-15 20:25:20', '2024-02-21 16:28:27', NULL, 1, 'nugetProductUpload', '0', '0', '2', NULL, '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (216, 1004, 'composer制品上传', '[{\"form\":{\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"nexusRepo\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"pjqk3eolp8c\",\"x-decorator-props\":{\"tooltip\":\"php制品仓库\"},\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  fetch(`${window.location.origin}/api/warehouse/api/repository/composer`,{\\n      headers: {Authorization: token },\\n      })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.url + \\\"/packages/upload/\\\",\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"nexusRepo\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"制品仓库\",\"x-index\":0,\"required\":true},\"group\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"43wjnb5crxr\",\"x-decorator-props\":{},\"name\":\"group\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"项目名\",\"x-index\":1},\"title\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"gu1h9qck22r\",\"x-decorator-props\":{},\"name\":\"title\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"组件名\",\"x-index\":2},\"version\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"qd8olayp6qf\",\"x-decorator-props\":{},\"name\":\"version\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"版本号\",\"x-index\":3}},\"x-designable-id\":\"f3nbhtchkq2\"}}]', '{\"name\":\"composerProductUpload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"nexusRepo\"},\"key\":\"nexusRepo\"},{\"value\":{\"isLiteral\":true,\"value\":\"group\"},\"key\":\"group\"},{\"value\":{\"isLiteral\":true,\"value\":\"title\"},\"key\":\"title\"},{\"value\":{\"isLiteral\":true,\"value\":\"version\"},\"key\":\"version\"}],\"stepFunc\":\"composerProductUpload\"}', NULL, 'composer制品上传', 1, 0, '2022-11-15 20:26:38', '2024-02-04 15:35:49', NULL, 1, 'composerProductUpload', '0', '0', '2', NULL, '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (217, 1005, '主机部署', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"startParamName_deployEnv\":{\"x-component\":\"Select\",\"x-designable-id\":\"mevzqvgbvq3\",\"x-decorator-props\":{\"tooltip\":\"数据来源：平台部署环境管理\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"环境\",\"x-index\":0,\"required\":true,\"default\":\"${deployEnv}\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"startParamName_deployEnv\",\"x-pattern\":\"disabled\"},\"startParamName_deployHost\":{\"x-component\":\"Select\",\"x-designable-id\":\"9l3607nox7t\",\"x-decorator-props\":{\"tooltip\":\"数据来源：部署环境资源虚拟机部分;主机IP，支持多选\"},\"x-validator\":[],\"x-component-props\":{\"mode\":true,\"showSearch\":false},\"title\":\"主机\",\"x-index\":1,\"required\":true,\"default\":\"${deployHost}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_deployHost\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployEnv\",\"source\":\"deployEnv\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"from\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"n4h65xkfi6w\",\"x-decorator-props\":{\"tooltip\":\"待上传文件或目录路径，支持绝对路径和相对路径\"},\"name\":\"from\",\"description\":\"\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"本地路径\",\"x-index\":2,\"required\":false},\"to\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"l2u2iouypgp\",\"x-decorator-props\":{\"tooltip\":\"接收文件或目录路径，支持绝对路径和相对路径\"},\"name\":\"to\",\"description\":\"\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"远程路径\",\"x-index\":3,\"required\":false},\"remote_command\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"nveidvdz2o4\",\"x-decorator-props\":{\"tooltip\":\"支持多行输入\"},\"name\":\"remote_command\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"执行ssh命令\",\"x-index\":4,\"required\":true}},\"x-designable-id\":\"ed3cy7sg1tn\"}}]', '{\"name\":\"hostDeploy\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployEnv\"},\"key\":\"startParamName_deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployHost\"},\"key\":\"startParamName_deployHost\"},{\"value\":{\"isLiteral\":true,\"value\":\"from\"},\"key\":\"from\"},{\"value\":{\"isLiteral\":true,\"value\":\"to\"},\"key\":\"to\"},{\"value\":{\"isLiteral\":true,\"value\":\"remote_command\"},\"key\":\"remote_command\"}],\"stepFunc\":\"hostDeploy\"}', NULL, '主机上传文件后执行ssh命令', 1, 0, '2022-04-29 06:05:59', '2024-03-19 11:57:39', NULL, 1, 'hostDeploy', '0', '0', '2', 'def call(def map){\n    def deployEnv = map.startParamName_deployEnv?env[map.startParamName_deployEnv]:map.deployEnv\n    def deployHost = map.startParamName_deployHost?env[map.startParamName_deployHost]:map.deployHost\n    call(map.stepName,deployEnv,deployHost,map.from,map.to,map.remote_command)\n    echo env.endString\n\n}\n\ndef call(String stepName,int envId,String hostId,String from ,String to,String command){\n    call( stepName, \"${envId}\", hostId, from , to, command)\n}\n\ndef call(String stepName,String envId,String hostId,String from ,String to,String command){\n    if(env.deployHost){\n       hostId =  env.deployHost\n    }\n    \n    echo \"---${from}---${to}---${command}---\"\n    def hostArr =  hostId.split(\",\")\n    for(String host : hostArr) {\n        host = host.split(\"\\\\|\")[0]\n        echo \"主机：${host}\"\n        def response = sh returnStdout: true ,script:\"\"\"\n        curl -X GET \"${env.pipelineSvcUrl}/deploy/host/${host}/password\" -H \"accept: */*\"\n        \"\"\"\n        def resData = readJSON text: \"\"\"${response}\"\"\"\n        def remote = [name: \"remote\", host: resData.data.ip, port: resData.data.port, user: resData.data.credential.name, allowAnyHosts: true]\n        if(resData.data.credential.credentialType == 0){\n            remote.password=resData.data.credential.password\n        }else{\n            remote.identity =resData.data.credential.password\n        }    \n        def paths = from.split(\",\")\n        for(String path : paths) {\n           if(path != \'\'){\n                   flag = sh(script: \"[ -d \'${path}\' ]  && echo \'true\' || echo \'false\' \", returnStdout: true).trim()\n                   if(flag == \"false\"){\n                       path = sh(script: \"ls ${path}\", returnStdout: true).trim()\n                   }\n                   echo \"结果：${flag}\"\n                   if(flag == \"true\"){\n                        echo \"这是一个基于目录的拷贝，会先到host主机上删除已经存在的文件夹\" \n                        def arr = path.split(\"/\")\n                        def removePath = \'\'\n                        if(arr[arr.length-1] == \'\'){\n                           removePath =  to + \"/\" + arr[arr.length-2]\n                        }else{\n                           removePath =  to + \"/\" + arr[arr.length-1] \n                        }\n                        sshCommand remote: remote, command: \"\"\"rm -rf ${removePath}\"\"\"   \n                    }\n               \n                sshPut remote: remote, from: \"${path}\", into: \"${to}\"\n            } \n        }\n        \n        arr = command.split(\"\\n\").join(\" ; \")\n        sshCommand remote: remote, command: \"\"\"${command}\"\"\"\n    }\n\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (218, 1008, 'Curl命令', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"curlCommand\":{\"default\":\"\",\"x-decorator\":\"FormItem\",\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"qda8i2fedbe\",\"x-decorator-props\":{\"tooltip\":\"\",\"colon\":false},\"name\":\"curlCommand\",\"x-validator\":[],\"x-component-props\":{\"style\":{\"height\":\"300px\"}},\"type\":\"string\",\"title\":\"Curl命令\",\"x-index\":0,\"required\":true}},\"x-designable-id\":\"mcrw94g26fe\"}}]', '{\"name\":\"curlCommand\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"curlCommand\"},\"key\":\"curlCommand\"}],\"stepFunc\":\"curlCommand\"}', NULL, '执行Curl命令', 1, 0, '2022-05-10 07:21:24', '2024-02-04 16:34:39', NULL, 1, 'curlCommand', '0', '0', '2', 'def call(String stepName,String command){\n    sh \"\"\"\n    ${command}\n    \"\"\"\n}\n\ndef call(def map){\n    call(map.stepName,map.curlCommand)\n    echo env.endString\n\n}', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (219, 1008, '执行Groovy脚本', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"script\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"c00yykug75t\",\"x-decorator-props\":{\"tooltip\":\"\"},\"name\":\"script\",\"x-validator\":[],\"x-component-props\":{\"autoSize\":false,\"style\":{\"height\":\"300px\"}},\"type\":\"string\",\"title\":\"Groovy脚本\",\"x-index\":0,\"required\":true}},\"x-designable-id\":\"dpp3248dusr\"}}]', '{\"name\":\"script\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"script\"},\"key\":\"script\"}],\"stepFunc\":\"script\"}', NULL, '执行Groovy脚本', 1, 0, '2022-05-10 09:25:27', '2024-02-04 16:34:49', NULL, 1, 'script', '0', '2', '2', NULL, '2', '', '0', '');
