eFlag && !$form.fields[\'zjwjsc_dev1.startParamName_deployEnv\'].value){\\n      $form.fields[\'zjwjsc_dev1.startParamName_deployEnv\'].value = \'${deployEnv}\'\\n    }\\n    if(!$form.fields[\'zjwjsc_dev2.zjwjsc_dev2_1.zjwjsc_btn_2\'].value){\\n      $form.fields[\'zjwjsc_dev2.zjwjsc_dev2_1.zjwjsc_btn_2\'].value = !$form.fields[\'zjwjsc_dev2.zjwjsc_dev2_1.zjwjsc_btn_2\'].value\\n    }\\n  }else{\\n    if(state.updateFlag){\\n      $self.value = \'设置为变量\'\\n      $form.fields[\'zjwjsc_dev1.startParamName_deployEnv\'].value=\'\'\\n  }\\n  }\\n},[$form.fields[\'zjwjsc_dev1.zjwjsc_dev1_1.zjwjsc_btn_1\']?.value])\\n\\n\\n\",\"state\":{\"value\":\"{{\'设置为变量\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"content\":\"设置为变量\"},\"type\":\"string\",\"x-index\":0},\"zjwjsc_btn_1\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Switch\",\"x-designable-id\":\"bzfl17kg6o7\",\"x-decorator-props\":{},\"name\":\"zjwjsc_btn_1\",\"x-reactions\":{\"fulfill\":{\"state\":{\"hidden\":\"{{true}}\"}},\"dependencies\":[]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"\",\"x-index\":1}}}}},\"zjwjsc_dev2\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"5uz533s1b9x\",\"x-reactions\":{\"fulfill\":{\"state\":{\"componentProps\":\"{{{\\n    style: {\\n      position: \'relative\'\\n    }\\n  }}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"zjwjsc_dev2\",\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":1,\"properties\":{\"deployHost\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"rzggtyurugl\",\"x-decorator-props\":{\"tooltip\":\"支持选择已有主机或者设置为启动变量，例如${deployHost}，在执行流水线时指定\"},\"name\":\"deployHost\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.deployEnv) {\\n    $self.loading = true\\n    // $self.value = \\\"\\\"\\n    const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n    fetch(\\n      `${window.location.origin}/api/efficiency/deploy/host/listAll?envId=${$deps.deployEnv}&type=1,2,3`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data?.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"\\\",\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.deployEnv])\",\"state\":{\"visible\":\"{{!!!$deps.zjwjsc_btn_2}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployEnv\",\"source\":\"zjwjsc_dev1.deployEnv\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"zjwjsc_btn_2\",\"source\":\"zjwjsc_dev2.zjwjsc_dev2_1.zjwjsc_btn_2\",\"type\":\"boolean\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"主机\",\"x-index\":0,\"required\":true},\"startParamName_deployHost\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"qch9orug6ch\",\"x-decorator-props\":{\"tooltip\":\"支持选择已有主机或者设置为启动变量，例如${deployHost}，在执行流水线时指定\"},\"name\":\"startParamName_deployHost\",\"x-reactions\":{\"fulfill\":{\"run\":\"\",\"state\":{\"visible\":\"{{!!$deps.zjwjsc_btn_2}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployHost\",\"source\":\"zjwjsc_dev2.deployHost\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"zjwjsc_btn_2\",\"source\":\"zjwjsc_dev2.zjwjsc_dev2_1.zjwjsc_btn_2\",\"type\":\"boolean\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"主机\",\"x-index\":1,\"required\":true},\"zjwjsc_dev2_1\":{\"x-component\":\"BlankDiv\",\"x-designable-id\":\"sip9vbfi4gu\",\"x-reactions\":{\"fulfill\":