on,values)\n\n}\ndef call(String stepName,String release,String deployEnv,Integer clusterId,String namespace,String sourceType,String chartPath,String valuesPath,String chartRepoName,String chart,String version,String values){\n    call(stepName,release,deployEnv,\"${clusterId}\",namespace,sourceType,chartPath,valuesPath,chartRepoName,chart,version,values)\n}\n\ndef call(String stepName,String release,String deployEnv,String clusterId,String namespace,String sourceType,String chartPath,String valuesPath,String chartRepoName,String chart,String version,String values){\n    \n    if(env.deployCluster){\n        clusterId = env.deployCluster\n    }\n    if(env.namespace){\n        namespace = env.namespace\n    }\n\n    def response = sh returnStdout: true ,script:\"\"\"\n    curl -X GET \"${env.pipelineSvcUrl}/deploy/cluster/${clusterId}/token\" -H \"accept: */*\"\n    \"\"\"\n    def resData = readJSON text: \"\"\"${response}\"\"\"\n    def token = resData.data[0].token.trim()\n    if(token.startsWith(\"apiVersion\")){\n        writeFile encoding: \"utf-8\", file: \"kubeconfig\", text: \"\"\"${token}\"\"\"\n        sh \"\"\"\n        rm -rf /root/.kube/config\n        mkdir -p /root/.kube/\n        mv kubeconfig /root/.kube/config\n        \"\"\"\n    }else{\n        sh \"\"\"\n        kubectl config set-cluster kubernetes --server=https://${resData.data[0].ip}:${resData.data[0].port} --insecure-skip-tls-verify=true\n        set +x\n        kubectl config set-credentials admin --token=${token}\n        set -x\n        kubectl config set-context dev --cluster=kubernetes --user=admin\n        kubectl config use-context dev\n         \"\"\"\n    }\n\n    sh \"\"\"\n        chmod g-rw ~/.kube/config\n        chmod o-r ~/.kube/config\n    \"\"\"\n    if(sourceType == \'1\'){\n        valuesOpt = \'\'\n        if(values != \'\' && values != \'\\n\'){\n           valuesOpt = \"--set ${values}\" \n        }\n        if(env.tag){\n            valuesOpt = valuesOpt.replace(\'${tag}\',\"${tag}\")\n        }\n        productIdOp = \'\'\n        if(env.dockerDeployProduct){\n            productIdOp = \"-F \'productId=${env.dockerDeployProduct}\'\"\n        }\n        configCloneCommandOp = \'\'\n        if(env.configCloneCommand){\n            configCloneCommandOp = \"-F \'configCloneCommand=${env.configCloneCommand}\'\"\n        }\n        gitlabIdOpt = \'\'\n        if(env.mergeBranch){\n           gitlabIdOpt = \"-F \'gitRepo=${env.gitRepo}\' -F \'gitBranch=${env.mergeBranch}\' -F \'gitCommitId=${env.mergeCommitId}\' -F \'gitCredentialId=${env.mergeGitCredentialId}\'\"\n            if(env.mergeGitlabId){\n                gitlabIdOpt = gitlabIdOpt + \" -F \'serverId=${env.mergeServerId}\' -F \'gitlabId=${env.mergeGitlabId}\'\"\n            } \n        }\n        sh \"\"\"\n        curl -X POST \'${env.pipelineSvcUrl}/devops/buildDeploy/addK8sRecords\' -F \'buildId=${env.buildId}\' -F \'jobId=${params.job_id}\' -F \'deployType=Helm部署\' ${gitlabIdOpt} ${productIdOp} ${configCloneCommandOp} -F \'deployEnv=${env.deployEnv}\' -F \'hostId=${clusterId}\'  -F \'command=helm upgrade --recreate-pods --install ${release} ${chartPath} -n ${namespace} ${valuesOpt} -f ${valuesPath} --insecure-skip-tls-verify\' -H \'accept: */*\'\n        \"\"\"\n        \n        sh \"helm upgrade --recreate-pods --install ${release} ${chartPath} -n ${namespace} ${valuesOpt} -f ${valuesPath} --insecure-skip-tls-verify\"\n\n    }else{\n        chartRepoName = chartRepoName.split(\"\\\\|\")[1]\n        withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials\",passwordVariable: \'password\', usernameVariable: \'username\')]){\n            addCommand = \"helm repo add --username ${username} --password ${password} stable ${env.helmUrl}/${chartRepoName} --insecure-skip-tls-verify\"\n            sh \"helm repo add --username ${username} --password ${password} stable ${env.helmUrl}/${chartRepoName} --insecure-skip-tls-verify\"\n        }\n        valuesOpt = \'\'\n        if(values != \'\\n\' && values != \'\'){\n            valuesOpt = \"--set ${values}\"\n        }\n        productIdOp = \'\'\n        if(env.dockerDeployProduct){\n            productIdOp = \"-F \'productId=${env.dockerDeployProduct}\'\"\n        }\n        configCloneCommandOp = \'\'\n        if(env.configCloneCommand){\n            configCloneCommandOp = \"-F \'configCloneCommand=${env.configCloneCommand}\'\"\n        }\n        gitlabIdOpt = \'\'\n        if(env.mergeBranch){\n           gitlabIdOpt = \"-F \'gitRepo=${env.gitRepo}\' -F \'gitBranch=${env.mergeBranch}\' -F \'gitCommitId=${env.mergeCommitId}\' -F \'gitCredentialId=${env.mergeGitCredentialId}\'\"\n            if(env.mergeGitlabId){\n                gitlabIdOpt = gitlabIdOpt + \" -F \'serverId=${env.mergeServerId}\' -F \'gitlabId=${env.mergeGitlabId}\'\"\n            } \n        }\n        sh \"\"\"\n        set +x\n        curl -X POST \'${env.pipelineSvcUrl}/devops/buildDeploy/addK8sRecords\' -F \'buildId=${env.buildId}\' -F \'jobId=${params.job_id}\' -F \'deployType=Helm部署\' ${gitlabIdOpt} ${productIdOp} ${configCloneCommandOp} -F \'deployEnv=${env.deployEnv}\' -F \'hostId=${clusterId}\'  -F \'command=${addCommand}\nhelm upgrade --recreate-pods --install  ${release} stable/${chart} -n ${namespace} --version ${version} ${valuesOpt} --insecure-skip-tls-verif\' -H \'accept: */*\'\n        set -x\n        \"\"\"\n        \n        sh \"helm upgrade --recreate-pods --install  ${release} stable/${chart} -n ${namespace} --version ${version} ${valuesOpt} --insecure-skip-tls-verify\"\n    }\n}\n\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (223, 1001, '代码克隆', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"startParamName_subSystemBranch\":{\"x-component\":\"Input\",\"x-designable-id\":\"7glj6sfd2p9\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"分支\",\"x-index\":0,\"default\":\"${branch}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_subSystemBranch\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{false}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"subSystemBranch\":{\"x-component\":\"Select\",\"x-designable-id\":\"hx6jydbhsgy\",\"x-decorator-props\":{\"tooltip\":\"子系统关联代码仓库分支\"},\"description\":\"\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"分支\",\"x-index\":1,\"required\":true,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"subSystemBranch\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  if (true) {\\n    // $self.value = \\\"\\\"\\n    const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n   \\n    var subSystemId = window.sessionStorage.getItem(\\\"subSystemId\\\")\\n    fetch(\\n      `${window.location.origin}/api/cloud/open/pipeline/getSubSystemById?subSystemId=${subSystemId}`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId,Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          console.log(data.gitlabId)\\n          var stageStr = window.sessionStorage.getItem(\\\"pipelineStageInfo\\\")\\n          if (stageStr != null && stageStr != \\\"{}\\\") {\\n            var stageInfo = JSON.parse(stageStr)\\n            stageInfo.gitlabId = data.gitlabId\\n            stageStr = JSON.stringify(stageInfo)\\n            window.sessionStorage.setItem(\\\"pipelineStageInfo\\\", stageStr)\\n          }else{\\n            var stageInfo = {}\\n            stageInfo.gitlabId = data.gitlabId\\n            stageStr = JSON.stringify(stageInfo)\\n            window.sessionStorage.setItem(\\\"pipelineStageInfo\\\", stageStr)\\n          }\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n\\n    fetch(\\n      `${window.location.origin}/api/cloud/scm/${subSystemId}/branches`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId,Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          console.log(data)\\n          const re =\\n            data.map((k) => ({\\n              value: subSystemId + \\\"|\\\" + k.name,\\n              label: k.name,\\n            })) || []\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.$$service_id, $deps.$$project_id])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]}}},\"x-designable-id\":\"51npf93nmaa\"}}]', '{\"name\":\"subsystemClone\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_subSystemBranch\"},\"key\":\"startParamName_subSystemBranch\"},{\"value\":{\"isLiteral\":true,\"value\":\"subSystemBranch\"},\"key\":\"subSystemBranch\"}],\"stepFunc\":\"subsystemClone\"}', NULL, '将代码仓库文件下载至流水线工作目录，作为代码源，可用于执行单元测试、扫描代码质量、构建制品等任务', 1, 0, '2022-09-02 07:01:11', '2024-06-25 10:35:34', NULL, 1, 'subsystemClone', '2', '2', '2', 'import org.codehaus.groovy.runtime.GStringImpl\n\ndef call(def map){\n    def subSystemBranch = \'\'\n    if(map.startParamName_subSystemBranch){\n        if(map.startParamName_subSystemBranch instanceof GStringImpl){\n            subSystemBranch = map.startParamName_subSystemBranch\n        }else{\n            subSystemBranch = env[map.startParamName_subSystemBranch]\n        }\n    }else{\n        subSystemBranch = map.subSystemBranch\n    }\n    echo map.subSystemBranch\n    call(map.stepName,subSystemBranch)\n    echo env.endString\n}\n\ndef call(String stepName,String subSystemBranch){\n    echo \"subSystemBranch:\"\n    echo subSystemBranch\n    String[] arr = subSystemBranch.split(\"\\\\|\")\n    subSystemBranch = arr[arr.length -1]\n    def response = sh(returnStdout: true , script: \"\"\"\n    curl -X GET \"${env.developmentSvcUrl}open/pipeline/getSubSystemById?subSystemId=${env.subSystemId}\" -H \"Amp-Organ-Id: ${env.tenantId}\"\n    \"\"\")\n    echo \"${response}\"\n    def resData = readJSON text: \"\"\"${response}\"\"\"\n\n    data = resData.data\n    gitClone( \"${data.serverId}\", \"${data.gitlabId}\",  data.gitlabRepo , subSystemBranch)\n\n    env.gitlabId = data.gitlabId\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (226, 1002, '代码构建', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"language\":{\"x-component\":\"TreeSelect\",\"x-designable-id\":\"oqup6zl29y3\",\"x-display\":\"visible\",\"x-decorator-props\":{\"tooltip\":\"\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"语言\",\"x-index\":0,\"required\":true,\"default\":\"java8\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  const treeData = [\\n    {\\n      label: \\\"java\\\",\\n      value: \\\"java\\\",\\n      selectable: false,\\n      children: [\\n        {\\n          value: \\\"java8\\\",\\n          label: \\\"java8\\\",\\n        },\\n        {\\n          value: \\\"java11\\\",\\n          label: \\\"java11\\\",\\n        },\\n        {\\n          value: \\\"java17\\\",\\n          label: \\\"java17\\\",\\n        },\\n        {\\n          value: \\\"java11-4.0.2\\\",\\n          label: \\\"java11-4.0.2\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"node\\\",\\n      value: \\\"node\\\",\\n      selectable: false,\\n      children: [\\n        {\\n          value: \\\"node14\\\",\\n          label: \\\"node14\\\",\\n        },\\n        {\\n          value: \\\"node16\\\",\\n          label: \\\"node16\\\",\\n        },\\n        {\\n          value: \\\"node18\\\",\\n          label: \\\"node18\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"dotnet\\\",\\n      value: \\\"dotnet\\\",\\n      selectable: false,\\n      children: [\\n        {\\n          value: \\\"net5\\\",\\n          label: \\\"net5\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"php\\\",\\n      value: \\\"php\\\",\\n      selectable: false,\\n      children: [\\n        {\\n          value: \\\"php7\\\",\\n          label: \\\"php7\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"golang\\\",\\n      value: \\\"golang\\\",\\n      selectable: false,\\n      children: [\\n        {\\n          value: \\\"golang1\\\",\\n          label: \\\"golang1\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"python\\\",\\n      value: \\\"python\\\",\\n      selectable: false,\\n      children: [\\n        {\\n          value: \\\"python3\\\",\\n          label: \\\"python3\\\",\\n        },\\n      ],\\n    },\\n  ]\\n  $self.dataSource = treeData\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"string\"}]},\"name\":\"language\"},\"buildTool\":{\"x-component\":\"TreeSelect\",\"x-designable-id\":\"en2aaua08oj\",\"x-display\":\"visible\",\"x-decorator-props\":{\"tooltip\":\"java语言时，需要选择匹配的构建工具；其他语言会自动匹配对应的构建工具\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"构建工具\",\"x-index\":1,\"required\":false,\"default\":\"\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  treeData = [\\n    {\\n      label: \\\"maven\\\",\\n      value: \\\"maven\\\",\\n      selectable: false,\\n      children: [\\n        {\\n          label: \\\"maven3.5\\\",\\n          value: \\\"maven3.5\\\",\\n        },\\n        {\\n          label: \\\"java8-mvn3.8\\\",\\n          value: \\\"java8-mvn3.8\\\",\\n        },\\n        {\\n          label: \\\"maven3.8\\\",\\n          value: \\\"maven3.8\\\",\\n        },\\n      ],\\n    },\\n  ]\\n  $self.dataSource = treeData\\n}, [$deps.language])\\n\",\"state\":{\"visible\":\"{{$deps.language.startsWith(\\\"java\\\") || $deps.language.startsWith(\\\"openjdk\\\")}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"language\",\"source\":\"language\",\"type\":\"any\"}]},\"name\":\"buildTool\"},\"command\":{\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"r8k8ml4hijf\",\"x-decorator-props\":{\"tooltip\":\"\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"构建命令\",\"x-index\":2,\"required\":true,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"command\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(()=>{\\n  if(!$self.value){\\n    if($deps.language.startsWith(\'java\')){\\n      \\n      if($deps.buildTool){\\n        if($deps.buildTool.startsWith(\'maven\')){\\n          $self.value = \'mvn clean package -Dmaven.test.skip=true -B\'\\n        }else{\\n          $self.value = \'./gradlew build\'\\n        }\\n      }  \\n    }else if($deps.language.startsWith(\'node\')){\\n      $self.value = \'npm install \\\\nnpm run build\'\\n    }\\n  }\\n  \\n},[$deps.language,$deps.buildTool])\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"language\",\"source\":\"language\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"buildTool\",\"source\":\"buildTool\",\"type\":\"any\"}]}},\"file_setting\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Upload.Dragger\",\"x-designable-id\":\"dl2quvm4t6o\",\"x-decorator-props\":{\"tooltip\":\"可选项，如需使用指定的settings.xml，请在此处上传文件，通常使用平台内置的即可\"},\"name\":\"file_setting\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  var hp = `${window.location.host}`\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  $self.componentProps.headers = { Authorization: token }\\n  $self.componentProps.action = `${window.location.origin}/api/application/provider/files/upload/one?bucketName=application`\\n}, [])\\n\",\"state\":{\"visible\":\"{{$deps.language.startsWith(\\\"java\\\")}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"language\",\"source\":\"language\",\"type\":\"any\"}]},\"x-component-props\":{\"method\":\"POST\",\"withCredentials\":true,\"action\":\"api/application/provider/files/upload/one?bucketName=amp\",\"textContent\":\"点击或拖拽文件到此区域上传\",\"maxCount\":1,\"accept\":\".xml\"},\"x-validator\":[],\"type\":\"Array<object>\",\"title\":\"上传setting文件\",\"x-index\":3},\"null_settingContent\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"ybivkz35v55\",\"x-decorator-props\":{\"tooltip\":\"展示上传的setting文件的内容\"},\"name\":\"null_settingContent\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.file_setting) {\\n    var array =  $deps.file_setting\\n    if (array.length > 0) {\\n      var link = array[0].response.data.link\\n      link = window.location.origin + link\\n      const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n      var orgId = \\\"\\\"\\n      if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n      var token = localStorage.getItem(\\\"userToken\\\")\\n      fetch(\\n        `${window.location.origin}/api/efficiency/devops/pipeline/fileContent?url=${link}`,\\n        {\\n          headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n        }\\n      )\\n        .then((response) => response.json())\\n        .then(\\n          ({ data }) => {\\n            $self.value = data\\n          },\\n          () => {}\\n        )\\n    }else{\\n      $self.value = \\\"\\\"\\n    }\\n  }\\n}, [$deps.file_setting])\\n\",\"state\":{\"visible\":\"{{$deps.language.startsWith(\\\"java\\\")}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"file_setting\",\"source\":\"file_setting\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"language\",\"source\":\"language\",\"type\":\"any\"}]},\"x-pattern\":\"readOnly\",\"x-validator\":[],\"x-component-props\":{\"autoSize\":true},\"type\":\"string\",\"title\":\"文件内容\",\"x-index\":4},\"proxy\":{\"default\":\"\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"8s6rb4tej5k\",\"x-decorator-props\":{\"tooltip\":\"选择构建所需要的依赖库。先在制品仓库-组织二方库添加好对应类型的仓库组\"},\"name\":\"proxy\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if ($deps.language.startsWith(\\\"node\\\")) {\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/repository?format=npm&pageNum=1&pageSize=999&kind=0&repositoryType=group`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.records.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"|\\\" + k.url,\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {}\\n      )\\n  } else if ($deps.language.startsWith(\\\"go\\\")) {\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/repository?format=go&pageNum=1&pageSize=999&kind=0&repositoryType=group`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.records.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"|\\\" + k.url,\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {}\\n      )\\n  } else if ($deps.language.startsWith(\\\"python\\\")) {\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/repository?format=pypi&pageNum=1&pageSize=999&kind=0&repositoryType=group`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.records.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"|\\\" + k.url,\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {}\\n      )\\n  }\\n}, [$deps.language])\\n\",\"state\":{\"visible\":\"{{$deps.language.startsWith(\\\"node\\\") || \\n$deps.language.startsWith(\\\"go\\\") || \\n$deps.language.startsWith(\\\"python\\\")}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"language\",\"source\":\"language\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"依赖库\",\"x-index\":5}},\"x-designable-id\":\"c3n7xtujyff\"}}]', '{\"name\":\"codeBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"language\"},\"key\":\"language\"},{\"value\":{\"isLiteral\":true,\"value\":\"buildTool\"},\"key\":\"buildTool\"},{\"value\":{\"isLiteral\":true,\"value\":\"command\"},\"key\":\"command\"},{\"value\":{\"isLiteral\":true,\"value\":\"file_setting\"},\"key\":\"file_setting\"},{\"value\":{\"isLiteral\":true,\"value\":\"proxy\"},\"key\":\"proxy\"}],\"stepFunc\":\"codeBuild\"}', NULL, '使用构建工具构建不同语言的项目', 1, 0, '2022-10-20 12:47:51', '2025-01-06 17:03:42', NULL, 3267307713708539904, 'codeBuild', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.language,map.buildTool,map.command,map.file_setting,\'\',map.proxy)\n    echo env.endString\n\n}\n\ndef call(String stepName,String language,String buildTool,String buildCommand){\n    echo \"${buildCommand}\"\n    sh \"\"\" \n    ${buildCommand}\n     \"\"\"\n     \n}\n\n\ndef call(String stepName,String language,String buildTool,String buildCommand, String settingFile ,String fileContent,String proxy) {\n    echo \"${buildCommand}\"\n    \n    if(settingFile){\n        //获取文件内容\n        def response = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.pipelineSvcUrl}/devops/pipeline/fileContent?url=http://devops-app:8000/${settingFile}\" -H \"accept: */*\"\n        \"\"\")\n        def resData = readJSON text: \"\"\"${response}\"\"\"\n        fileContent = resData.data\n        writeFile encoding: \"utf-8\", file: \"settings.xml\", text: \"\"\"${fileContent}\"\"\"\n        buildCommand = \"${buildCommand.trim()} --settings ${WORKSPACE}/settings.xml\"\n    }\n    if(proxy){\n        arr = proxy.split(\"\\\\|\")\n        proxy = arr[arr.length-1]\n        echo \"代理地址 ${proxy}\"\n        if (language == \"node14\") {\n            sh \"\"\"\n            npm config set registry ${proxy}\n            \"\"\"\n        }else if (language == \"golang1\"){\n            sh \"\"\"\n            go env -w GO111MODULE=on\n            go env -w GOPROXY=${proxy}\n            \"\"\"\n        }else if (language == \"python3\"){\n            sh \"\"\"\n            pip config set global.index-url ${proxy}\n            pip config set install.trusted-host ${proxy}\n            \"\"\"\n        }\n    }else{\n        if (language == \"node14\") {\n            sh \"\"\"\n            npm config set registry http://nexus:8081/repository/proxy-npm\n            npm config set sass_binary_site=http://nexus:8081/repository/node-sass\n            \"\"\"\n        }else if (language == \"golang1\"){\n            sh \"\"\"\n            go env -w GO111MODULE=on\n            go env -w GOPROXY=http://nexus:8081/repository/proxy-go\n            \"\"\"\n        }else if (language == \"python3\"){\n            sh \"\"\"\n            pip config set global.index-url http://nexus:8081/repository/proxy-pypi\n            pip config set install.trusted-host http://nexus:8081/repository/proxy-pypi\n            \"\"\"\n        }    \n    }\n    \n    if(language.startsWith(\"node\")){\n        sh \"\"\"\n        npm config set strict-ssl false\n        yarn config set strict-ssl false\n        \"\"\"\n    }\n    env.MAVEN_OPTS = \"-Dmaven.wagon.http.ssl.insecure=true -Dmaven.wagon.http.ssl.allowall=true\"\n    sh \"\"\"\n    ${buildCommand}\n     \"\"\"\n    \n}\n', '2', '', '0', '');
