ops\":\"{{{\\n  style: {\\n    position: \'absolute\',\\n    top: -5,\\n    right: 0,\\n    zIndex: 10000,\\n    width: 74,\\n    cursor: \'pointer\',\\n    color: \'#226ee7\',\\n  }\\n}}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"placeholder\":\"空白块\"},\"type\":\"void\",\"x-index\":2,\"properties\":{\"tyzpxz_btn3\":{\"x-component\":\"Text\",\"x-designable-id\":\"f6xvaybcwvp\",\"x-decorator\":\"FormItem\",\"x-decorator-props\":{\"wrapperWrap\":false,\"labelWrap\":false,\"inset\":false,\"feedbackLayout\":\"none\",\"wrapperAlign\":\"left\"},\"name\":\"tyzpxz_btn3\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  updateFlag: false\\n})\\n\\n$props({\\n  onClick() {\\n    state.updateFlag = true\\n    if(!$form.fields[\'tyzpxz_dev2.tyzpxz_dev2_1.tyzpxz_btn_2\'].value && !$form.fields[\'tyzpxz_dev1.tyzpxz_dev1_1.tyzpxz_btn_1\'].value){  \\n      $form.fields[\'tyzpxz_dev3.tyzpxz_dev3_1.tyzpxz_btn_3\'].value = !$form.fields[\'tyzpxz_dev3.tyzpxz_dev3_1.tyzpxz_btn_3\'].value\\n    }\\n  }\\n})\\n\\n\\n$effect(()=>{\\n  \\n  if($form.fields[\'tyzpxz_dev2.tyzpxz_dev2_1.tyzpxz_btn_2\'].value){\\n    $form.fields[\'tyzpxz_dev3.tyzpxz_dev3_1.tyzpxz_btn_3\'].value = true\\n  }\\n  $self.value = $form.fields[\'tyzpxz_dev3.tyzpxz_dev3_1.tyzpxz_btn_3\'].value?\'设置为定值\':\'设置为变量\'\\n  \\n},[$form.fields[\'tyzpxz_dev2.tyzpxz_dev2_1.tyzpxz_btn_2\']?.value])\\n\\n\\n$effect(()=>{\\n  if($form.fields[\'tyzpxz_dev1.tyzpxz_dev1_1.tyzpxz_btn_1\'].value){\\n    $form.fields[\'tyzpxz_dev3.tyzpxz_dev3_1.tyzpxz_btn_3\'].value = true\\n  }\\n  $self.value = $form.fields[\'tyzpxz_dev3.tyzpxz_dev3_1.tyzpxz_btn_3\'].value?\'设置为定值\':\'设置为变量\'\\n  \\n},[$form.fields[\'tyzpxz_dev1.tyzpxz_dev1_1.tyzpxz_btn_1\']?.value])\\n\\n\\n$effect(()=>{\\n  if($form.fields[\'tyzpxz_dev3.tyzpxz_dev3_1.tyzpxz_btn_3\'].value){\\n    $self.value = \'设置为定值\'\\n    $form.fields[\'tyzpxz_dev3.rawDeployProduct\'].value=\'\'\\n    if(state.updateFlag && !$form.fields[\'tyzpxz_dev3.startParamName_rawDeployProduct\'].value){\\n      $form.fields[\'tyzpxz_dev3.startParamName_rawDeployProduct\'].value = \'${rawDeployProduct}\'\\n    }\\n  }else{\\n    if(state.updateFlag){\\n      $self.value = \'设置为变量\'\\n      $form.fields[\'tyzpxz_dev3.startParamName_rawDeployProduct\'].value=\'\'\\n    }  \\n  }\\n},[$form.fields[\'tyzpxz_dev3.tyzpxz_dev3_1.tyzpxz_btn_3\']?.value])\\n\\n\\n\",\"state\":{\"value\":\"{{\'设置为变量\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-component-props\":{\"content\":\"设置为变量\"},\"type\":\"string\",\"x-index\":0},\"tyzpxz_btn_3\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Switch\",\"x-designable-id\":\"afj6kwkfg1p\",\"x-decorator-props\":{},\"name\":\"tyzpxz_btn_3\",\"x-reactions\":{\"fulfill\":{\"state\":{\"hidden\":\"{{true}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"\",\"x-index\":1}}}}}},\"x-designable-id\":\"rxenl47clio\"}}]', '{\"name\":\"productDownloadFun\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"rawRepository\"},\"key\":\"rawRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_rawRepository\"},\"key\":\"startParamName_rawRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"tyzpxz_btn1\"},\"key\":\"tyzpxz_btn1\"},{\"value\":{\"isLiteral\":true,\"value\":\"tyzpxz_btn_1\"},\"key\":\"tyzpxz_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"version\"},\"key\":\"version\"},{\"value\":{\"isLiteral\":true,\"value\":\"str_version\"},\"key\":\"str_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_version\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"tyzpxz_btn2\"},\"key\":\"tyzpxz_btn2\"},{\"value\":{\"isLiteral\":true,\"value\":\"tyzpxz_btn_2\"},\"key\":\"tyzpxz_btn_2\"},{\"value\":{\"isLiteral\":true,\"value\":\"rawDeployProduct\"},\"key\":\"rawDeployProduct\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_rawDeployProduct\"},\"key\":\"startParamName_rawDeployProduct\"},{\"value\":{\"isLiteral\":true,\"value\":\"tyzpxz_btn3\"},\"key\":\"tyzpxz_btn3\"},{\"value\":{\"isLiteral\":true,\"value\":\"tyzpxz_btn_3\"},\"key\":\"tyzpxz_btn_3\"}],\"stepFunc\":\"productDownloadFun\"}', NULL, '从通用制品库下载制品', 1, 0, '2022-12-26 05:09:13', '2024-02-04 19:05:16', NULL, 1, 'productDownloadFun', '3', '2', '2', 'import org.codehaus.groovy.runtime.GStringImpl\n\ndef call(def map){\n    def rawRepository = \'\'\n    if(map.startParamName_rawRepository){\n        rawRepository = map.startParamName_rawRepository instanceof GStringImpl?map.startParamName_rawRepository:env[map.startParamName_rawRepository]\n    }else{\n        rawRepository = map.rawRepository\n    }\n    rawRepository = rawRepository.split(\"\\\\|\")[0]\n    def version = \'\'\n    if(map.startParamName_version){\n        version = map.startParamName_version instanceof GStringImpl?map.startParamName_version:env[map.startParamName_version]\n    }else{\n        version = env.subSystemId?map.version:map.str_version\n    }\n    \n    def product = \'\'\n    if(map.startParamName_rawDeployProduct){\n        product = map.startParamName_rawDeployProduct instanceof GStringImpl?map.startParamName_rawDeployProduct:env[map.startParamName_rawDeployProduct]\n    }else{\n        product = map.rawDeployProduct\n    }\n   \n    call(map.stepName,rawRepository,version,product)\n    echo env.endString\n\n}\n\ndef call(String stepName,String repoId,String version,String deployProduct){\n    //查询子系统下版本最新的制品\n    def productName = \'\'\n    if(deployProduct == \'0\'){\n        result = sh returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/provider/product/lastProduct?subsystemId=${env.subSystemId}&version=${version}&repoId=${repoId}\" -H \"accept: */*\" -d \"\"\n        \"\"\"\n        resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0 ){\n            error \"调用制品库服务报错，报错信息：${resData.msg}\"\n        }\n        repoId = resData.data.repoId\n        productName = resData.data.name\n        version = resData.data.version\n        env.rawDeployProduct = resData.data.id\n    }else{\n        result = sh returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/product/info/${deployProduct}\" -H \"accept: */*\" -d \"\"\n        \"\"\"\n        echo \"${result}\"\n        resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0 ){\n            error \"查询制品信息报错，报错信息：${resData.msg}\"\n        }\n        repoId = resData.data.repoId\n        productName = resData.data.name\n        version = resData.data.version\n        env.rawDeployProduct = resData.data.id\n    }\n    \n    \n    sh\"\"\"\n    curl --fail -X GET \"${env.repositorySvcUrl}/api/product/download?repoId=${repoId}&productName=${productName}&version=${version}\" -o ${productName}\n    \"\"\"\n\n}', '2', '', '0', '');
