\\",\\n      value: \\\"Oracle\\\",\\n      selectable: false,\\n      children: [\\n        {\\n          value: \\\"2\\\",\\n          label: \\\"Oracle11\\\",\\n        },\\n        {\\n          value: \\\"3\\\",\\n          label: \\\"Oracle12\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"达梦\\\",\\n      value: \\\"dameng\\\",\\n      selectable: false,\\n      children: [\\n        {\\n          value: \\\"4\\\",\\n          label: \\\"DM8\\\",\\n        },\\n      ],\\n    },\\n  ]\\n  $self.dataSource = treeData\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"databaseType\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"数据库类型\",\"x-index\":1,\"required\":true},\"database\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"1bxljrqa5ah\",\"x-decorator-props\":{},\"name\":\"database\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  productType: \\\"\\\",\\n})\\n\\n$effect(() => {\\n  if ($deps.deployEnv && $deps.databaseType) {\\n    if (state.productType == \\\"\\\") {\\n      state.productType = \\\"1\\\"\\n    } else {\\n      $self.value = \\\"\\\"\\n    }\\n\\n    $self.loading = true\\n  const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  // $self.value = \\\"\\\"\\n  fetch(\\n    `${window.location.origin}/api/efficiency/deploy/sql/list?envId=${$deps.deployEnv}&sqlType=${$deps.databaseType}`,\\n    {\\n      headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n    }\\n  )\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"\\\",\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n  }  \\n  \\n}, [$deps.deployEnv, $deps.databaseType])\\n\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployEnv\",\"source\":\"deployEnv\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"databaseType\",\"source\":\"databaseType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"数据库\",\"x-index\":2,\"required\":true},\"configRepo\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"zl6anyurz5r\",\"x-decorator-props\":{\"tooltip\":\"选择sql文件所在的配置库\"},\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\r\\n  $self.loading = true\\r\\n  const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\r\\n  var orgId = \\\"\\\"\\r\\n  var token = localStorage.getItem(\\\"userToken\\\")\\r\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\r\\n  fetch(`${window.location.origin}/api/code/api/config/list`, {\\r\\n    headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\r\\n  })\\r\\n    .then((response) => response.json())\\r\\n    .then(\\r\\n      ({ data }) => {\\r\\n        const re = data.map((k) => ({\\r\\n          ...k,\\r\\n          value: k.serverId + \\\"|\\\" + k.gitlabId,\\r\\n          label: k.projectName,\\r\\n        }))\\r\\n        $self.loading = false\\r\\n        $self.dataSource = re\\r\\n      },\\r\\n      () => {\\r\\n        $self.loading = false\\r\\n      }\\r\\n    )\\r\\n}, [])\\r\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"configRepo\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"配置库\",\"x-index\":3,\"required\":true},\"configEnv\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"jmd4p6ijjk6\",\"x-decorator-props\":{},\"name\":\"configEnv\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  productType: \\\"\\\",\\n})\\n\\n$effect(() => {\\n  \\n  if ($deps.configRepo) {\\n    // $self.value = \\\"\\\"\\n    $self.loading = true\\n    if (state.productType == \\\"\\\") {\\n      state.productType = \\\"1\\\"\\n    } else {\\n      $self.value = \\\"\\\"\\n    }\\n    var arr = $deps.configRepo.split(\\\"|\\\")\\n    var serverId = arr[0]\\n    var projectId = arr[1]\\n    const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n    console.log(projectId)\\n    fetch(\\n      `${window.location.origin}/api/code/api/open/codeserver/${serverId}/${projectId}/branches`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re =\\n            data.content.map((k) => ({\\n              ...k,\\n              value: k.branch.name,\\n              label: k.branch.name,\\n            })) || []\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.configRepo])\\n\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"configRepo\",\"source\":\"configRepo\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"环境\",\"x-index\":4,\"required\":true},\"sqlPath2\":{\"x-decorator\":\"FormItem\",\"x-component\":\"TreeSelect\",\"x-designable-id\":\"5oobmdug95h\",\"x-decorator-props\":{\"tooltip\":\"支持三级目录，且sql文件必须在当前目录下，不支持目录下子目录下的sql文件\"},\"name\":\"sqlPath2\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  productType: \\\"\\\",\\n})\\n\\n$effect(() => {\\n  if ($deps.configRepo && $deps.configEnv) {\\n    $self.loading = true\\n    if (state.productType == \\\"\\\") {\\n      state.productType = \\\"1\\\"\\n    } else {\\n      $self.value = \\\"\\\"\\n    }\\n    var arr = $deps.configRepo.split(\\\"|\\\")\\n    var gitlabId = arr[1]\\n    const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n    fetch(\\n      `${window.location.origin}/api/code/${gitlabId}/file/tree/rescuer?ref=${$deps.configEnv}&onlyDir=true`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k.path,\\n            label: k.name,\\n            children: k.subItems.map((z) => ({\\n              value: z.path,\\n              label: z.name,\\n              children: z.subItems.map((r) => ({\\n                value: r.path,\\n                label: r.name,\\n              })),\\n            })),\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.configRepo, $deps.configEnv])\\n\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"configRepo\",\"source\":\"configRepo\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"configEnv\",\"source\":\"configEnv\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"Sql文件目录\",\"x-index\":5,\"required\":true}},\"x-designable-id\":\"2kjnlq6r2gt\"}}]', '{\"name\":\"databaseExec\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployEnv\"},\"key\":\"deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"databaseType\"},\"key\":\"databaseType\"},{\"value\":{\"isLiteral\":true,\"value\":\"database\"},\"key\":\"database\"},{\"value\":{\"isLiteral\":true,\"value\":\"configRepo\"},\"key\":\"configRepo\"},{\"value\":{\"isLiteral\":true,\"value\":\"configEnv\"},\"key\":\"configEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"sqlPath2\"},\"key\":\"sqlPath2\"}],\"stepFunc\":\"databaseExec\"}', NULL, '执行数据库sql文件', 1, 0, '2023-06-01 11:13:19', '2024-02-04 16:33:24', 1, 1, 'databaseExec', '0', '2', '2', 'def call(String stepName,String envId,String databeseType,String databaseId,String repo,String configEnv,String path){\n\n    configRepo(\"配置库克隆\",repo,configEnv,\'sql_workspace\')\n    dir(\'sql_workspace\'){\n        echo \"下载sql执行工具\"\n        result = sh returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/repository/getByName?name=pipeline-plugin&format=raw\" -H \"accept: */*\" -d \"\"\n        \"\"\"\n        resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0 || resData.data == null){\n            error \"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\"\n        }\n        repoId = resData.data.id\n        sh\"\"\"\n        curl --fail -X GET \"${env.repositorySvcUrl}/api/product/download/${repoId}?repositoryId=${repoId}&path=1.0/sqlExec.jar\" -o sqlExec.jar\n        \"\"\"\n\n\n        response = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.pipelineSvcUrl}/deploy/sql/detail?id=${databaseId}\" -H \"accept: */*\"  -H \"Amp-organ-Id: ${env.tenantId}\"\n        \"\"\")    \n        resData = readJSON text: \"\"\"${response}\"\"\"\n        if(resData.code != 0){\n            error \"查询凭证对应用户信息报错\"\n        }\n        databaseUrl = resData.data.url\n        sqlType = resData.data.sqlType\n        databeseType = \'mysql\'\n        if(sqlType == \'2\' || sqlType == \'3\'){\n            databeseType = \'oracle\'\n        }else if(sqlType == \'4\'){\n            databeseType = \'dm\'\n        }\n        echo \"--------------------执行sql----------------------\"\n        configCloneCommandOp = \'\'\n        if(env.configCloneCommand){\n            configCloneCommandOp = \"-F \'configCloneCommand=${env.configCloneCommand}\'\"\n        }\n        gitlabIdOpt = \'\'\n        if(env.mergeBranch){\n           gitlabIdOpt = \"-F \'gitRepo=${env.gitRepo}\' -F \'gitBranch=${env.mergeBranch}\' -F \'gitCommitId=${env.mergeCommitId}\' -F \'gitCredentialId=${env.mergeGitCredentialId}\'\"\n            if(env.mergeGitlabId){\n                gitlabIdOpt = gitlabIdOpt + \" -F \'serverId=${env.mergeServerId}\' -F \'gitlabId=${env.mergeGitlabId}\'\"\n            } \n        }\n        echo \"---------------------\"\n        command = \"java -jar sqlExec.jar ${databeseType} \'${databaseUrl}\'  ${resData.data.credentialDetail.name} ${resData.data.credentialDetail.password} ${path}\"\n        sh \"\"\"\n        curl -X POST \'${env.pipelineSvcUrl}/devops/buildDeploy/addK8sRecords\' -F \'buildId=${env.buildId}\' -F \'jobId=${params.job_id}\' -F \'deployType=sql部署\' ${gitlabIdOpt}  ${configCloneCommandOp} -F \'deployEnv=${envId}\' -F \'hostId=${databaseId}\'  -F \"command=${command}\"\n        \"\"\"\n        \n        sh \"\"\"\n        export TZ=\'Asia/Shanghai\'\n        java -jar sqlExec.jar ${databeseType} \'${databaseUrl}\'  ${resData.data.credentialDetail.name} ${resData.data.credentialDetail.password} ${path}\n        \"\"\"\n    \n    }\n\n}\n\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (238, 1001, '创建代码库Tag', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"tagName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"cby4zl1w3hb\",\"x-decorator-props\":{\"tooltip\":\"为当前构建代码新建Tag\",\"colon\":false},\"name\":\"tagName\",\"description\":\"使用此插件需要先在上游添加 代码克隆 插件\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"Tag名称\",\"x-index\":0,\"required\":true}},\"x-designable-id\":\"tc65zxbme5t\"}}]', '{\"name\":\"createTag\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"tagName\"},\"key\":\"tagName\"}],\"stepFunc\":\"createTag\"}', NULL, '在代码仓库中创建标签', 1, 0, '2022-12-26 09:01:38', '2024-07-03 09:57:04', NULL, 2432053447000854528, 'createTag', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.tagName)\n    echo env.endString\n\n}\n\ndef call(String stepName,String tagName){\n    //  withCredentials([usernamePassword(credentialsId: \"${env.gitCreadentId}\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n    //      sh \"\"\"\n    //     sed -i  \"s|http://|http://${username}:${password}@|g\" .git/config\n    //     git config --global user.email \"you@example.com\"\n    //     git config --global user.name \"Your Name\"\n    //     echo -----------\n    //     cat .git/config\n    //     \"\"\"\n        \n    // }\n        sh \"\"\"\n        git config --global user.email \"root@jenkins.com\"\n        git config --global user.name \"jenkins\"\n        \"\"\"\n    \n\n    //git ls-remote --tags origin\n    def res = sh(returnStdout: true ,script: \"git ls-remote --tags origin \\\\| grep ${tagName}\").trim()\n    if(res != \'\'){\n        try{\n            sh \"\"\"\n            git push origin :refs/tags/${tagName}\n            git tag -d ${tagName}        \n            \"\"\"\n        }catch(Exception e){\n\n        }\n\n    }\n\n    sh \"\"\"\n    git tag -a ${tagName} -m \"pipeline create tag\"\n    git push origin ${tagName}\n    \"\"\"\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (239, 1004, 'python制品上传', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"nexusRepo\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"6t655kt9h63\",\"x-decorator-props\":{\"tooltip\":\"Python制品仓库\"},\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  fetch(`${window.location.origin}/api/warehouse/api/repository/pypi?repositoryType=hosted`, {\\n    headers: { Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.url,\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"nexusRepo\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"制品仓库\",\"x-index\":0}},\"x-designable-id\":\"21ry5gaz9rx\"}}]', '{\"name\":\"pypiProductUpload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"nexusRepo\"},\"key\":\"nexusRepo\"}],\"stepFunc\":\"pypiProductUpload\"}', NULL, '上传python制品到python类型组织二方库', 1, 0, '2022-12-16 10:50:52', '2024-02-04 16:26:24', 1, 1, 'pypiProductUpload', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.nexusRepo)\n    echo env.endString\n\n}\n\ndef call(String stepName,String nexusRepo) {\n    println(nexusRepo)\n    withCredentials([usernamePassword(credentialsId: \'nexus-admin\', passwordVariable: \'password\', usernameVariable: \'username\')]) {\n        sh \"\"\"\n        echo -e \"[distutils]\\nindex-servers =\\n    nexus\\n\\n[nexus]\\nrepository=${nexusRepo}/\\nusername=${username}\\npassword=${password}\\n\" > ~/.pypirc\n        \"\"\"\n    }\n    sh \"twine upload -r nexus dist/*\"\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (240, 1010, '人工卡点', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"array_confirmor\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"7bgdc2gmkkr\",\"x-decorator-props\":{\"tooltip\":\"卡点信息通知人员，支持多选\"},\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n\\n  fetch(\\n    `${window.location.origin}/api/application/users/page?current=1&size=999`,\\n    {\\n      headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n    }\\n  )\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.records.map((k) => ({\\n          ...k,\\n          value: k.id,\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"array_confirmor\",\"x-validator\":[],\"x-component-props\":{\"mode\":\"multiple\"},\"title\":\"确认人员\",\"x-index\":0}},\"x-designable-id\":\"9o875t0svxb\"}}]', '{\"name\":\"inputControl\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"array_confirmor\"},\"key\":\"array_confirmor\"}],\"stepFunc\":\"inputControl\"}', NULL, '人工确认是否继续执行构建', 1, 0, '2023-01-04 15:18:55', '2024-02-04 16:39:17', 1, 1, 'inputControl', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.confirmor)\n}\n\ndef call(String stepName, String confirmor){\n\n    content = \"${env.harmonyUiUrl}efficiency/list/detail/running_history_detail?id=${env.job_id}&detail_id=${BUILD_NUMBER}\"\n    def response = sh returnStdout: true, script: \"\"\"\n        curl -X POST \"${env.ampSvcUrl}provider/messages/sendMessage\" -H \"accept: */*\" -H \"Content-Type: application/json\" -d \"{\\\\\\\"title\\\\\\\":\\\\\\\"卡点消息通知\\\\\\\",\\\\\\\"userIds\\\\\\\":[${confirmor}],\\\\\\\"sendMode\\\\\\\":\\\\\\\"2\\\\\\\",\\\\\\\"sendType\\\\\\\":\\\\\\\"3\\\\\\\",\\\\\\\"content\\\\\\\":\\\\\\\"<p>${content}<p>\\\\\\\",\\\\\\\"tenantId\\\\\\\":1}\"\n    \"\"\"\n    echo \"${response}\"\n\n    echo \'人工确认\'\n    timeout(time: 10, unit: \'MINUTES\') {\n        input(message: \'\', id: \'input\', ok: \'\', submitter: \'admin\')\n    }\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (242, 1003, '通用代码扫描', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"scanPath\":{\"default\":\".\",\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"an883yyvci4\",\"x-decorator-props\":{\"tooltip\":\"默认当前路径，支持绝对路径和相对路径\"},\"name\":\"scanPath\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"扫描路径\",\"x-index\":0,\"required\":true},\"excludePath\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"9bmof924o86\",\"x-decorator-props\":{\"tooltip\":\"不扫描路径\"},\"name\":\"excludePath\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"排除路径\",\"x-index\":1},\"sonarProject\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"c2vd3s26baa\",\"x-decorator-props\":{\"tooltip\":\"选择代码扫描/扫描方案页面中添加的方案\"},\"name\":\"sonarProject\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  // $self.value = \\\"\\\"\\n  fetch(`${window.location.origin}/api/codeScan/scanPlans`, {\\n    headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"\\\",\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"扫描方案\",\"x-index\":2,\"required\":true},\"sonarGate\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"nvscji28t2d\",\"x-decorator-props\":{\"tooltip\":\"数据来源：质量门禁已启用方案\"},\"name\":\"sonarGate\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\r\\n  $self.loading = true\\r\\n  const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\r\\n  var orgId = \\\"\\\"\\r\\n  var token = localStorage.getItem(\\\"userToken\\\")\\r\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\r\\n  // $self.value = \\\"\\\"\\r\\n  fetch(`${window.location.origin}/api/codeScan/qualityGates`, {\\r\\n    headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\r\\n  })\\r\\n    .then((response) => response.json())\\r\\n    .then(\\r\\n      ({ data }) => {\\r\\n        const re = data.map((k) => ({\\r\\n          ...k,\\r\\n          value: k.id + \\\"\\\",\\r\\n          label: k.name,\\r\\n        }))\\r\\n        $self.loading = false\\r\\n        $self.dataSource = re\\r\\n      },\\r\\n      () => {\\r\\n        $self.loading = false\\r\\n      }\\r\\n    )\\r\\n}, [])\\r\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"质量门禁\",\"x-index\":3,\"required\":true},\"waitGate\":{\"default\":true,\"x-decorator\":\"FormItem\",\"x-component\":\"Switch\",\"x-designable-id\":\"ue1fovt779m\",\"x-decorator-props\":{\"tooltip\":\"\"},\"name\":\"waitGate\",\"description\":\"开启门禁，检查不通过时终止流水线构建\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"门禁卡点\",\"x-index\":4},\"addScan\":{\"default\":true,\"x-decorator\":\"FormItem\",\"x-component\":\"Switch\",\"x-designable-id\":\"wob8f3gudey\",\"x-decorator-props\":{},\"name\":\"addScan\",\"description\":\"\\n推荐开启增量扫描，基于 基线版本扫描后提交的diff代码进行扫描，速度更快 ；全量扫描将扫描分支的全部文件，适合扫描设置变更后执行，首次执行流水线默认执行全量分支\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"boolean\",\"title\":\"增量扫描\",\"x-index\":5},\"compareBranch\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"38zolxy8ydp\",\"x-decorator-props\":{\"tooltip\":\"选择commitId\"},\"name\":\"compareBranch\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  var pipelineStageInfoStr = sessionStorage.getItem(\\\"pipelineStageInfo\\\")\\n  var gitlabId = \\\"\\\"\\n  var gitUrl = \\\"\\\"\\n  var gitCredentialId = \\\"\\\"\\n  if (pipelineStageInfoStr != \\\"{}\\\") {\\n    var pipelineStageInfo = JSON.parse(pipelineStageInfoStr)\\n    gitlabId = pipelineStageInfo.gitlabId || \\\"\\\"\\n    gitUrl = pipelineStageInfo.gitUrl || \\\"\\\"\\n    gitCredentialId = pipelineStageInfo.gitCredentialId || \\\"\\\"\\n    if (gitlabId.indexOf(\\\"|\\\")) {\\n      gitlabId = gitlabId.split(\\\"|\\\")[0]\\n    }\\n    console.log(gitlabId)\\n    if (gitlabId != \\\"\\\") {\\n      fetch(\\n        `${window.location.origin}/api/code/commit/recent?gitlabId=${gitlabId}`,\\n        {\\n          headers: { Authorization: token },\\n        }\\n      )\\n        .then((response) => response.json())\\n        .then(\\n          ({ data }) => {\\n            const re = data.map((k) => ({\\n              ...k,\\n              value: k.shortId,\\n              label: k.shortId + \\\"    \\\" + k.committedDateFormat,\\n            }))\\n            $self.loading = false\\n            $self.dataSource = re\\n          },\\n          () => {\\n            $self.loading = false\\n          }\\n        )\\n    } else if (gitUrl != \\\"\\\" && gitCredentialId != \\\"\\\") {\\n      fetch(\\n        `${window.location.origin}/api/efficiency/devops/buildSonarRel/commitInfo?url=${gitUrl}&credentialId=${gitCredentialId}`,\\n        {\\n          headers: { Authorization: token },\\n        }\\n      )\\n        .then((response) => response.json())\\n        .then(\\n          ({ data }) => {\\n            const re = data.map((k) => ({\\n              ...k,\\n              value: k.commitId,\\n              label: k.commitId + \\\"    \\\" + k.commitTime,\\n            }))\\n            $self.loading = false\\n            $self.dataSource = re\\n          },\\n          () => {\\n            $self.loading = false\\n          }\\n        )\\n    }\\n  }\\n}, [$deps.addScan])\\n\",\"state\":{\"visible\":\"{{$deps.addScan == 1}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"addScan\",\"source\":\"addScan\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"基线版本\",\"x-index\":6,\"required\":true}},\"x-designable-id\":\"opwrr3xtibb\"}}]', '{\"name\":\"sonarScanByParams\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"scanPath\"},\"key\":\"scanPath\"},{\"value\":{\"isLiteral\":true,\"value\":\"excludePath\"},\"key\":\"excludePath\"},{\"value\":{\"isLiteral\":true,\"value\":\"sonarProject\"},\"key\":\"sonarProject\"},{\"value\":{\"isLiteral\":true,\"value\":\"sonarGate\"},\"key\":\"sonarGate\"},{\"value\":{\"isLiteral\":true,\"value\":\"waitGate\"},\"key\":\"waitGate\"},{\"value\":{\"isLiteral\":true,\"value\":\"addScan\"},\"key\":\"addScan\"},{\"value\":{\"isLiteral\":true,\"value\":\"compareBranch\"},\"key\":\"compareBranch\"}],\"stepFunc\":\"sonarScanByParams\"}', NULL, '使用平台配置的扫描方案检测代码质量，扫描完成后会生成报告（支持扫描外部代码仓库）', 1, 0, '2023-02-21 01:17:00', '2024-07-02 17:50:44', 1, 1, 'sonarScanByParams', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.excludePath,map.scanPath,map.sonarProject,map.sonarGate,map.waitGate,map.addScan,map.compareBranch)\n    echo env.endString\n\n}\n\ndef call(String stepName, String excludePath, String scanPath, String scanPlanId, String scanGateId, boolean waitGate, boolean addScan, String baseLine) {\n    call(stepName, excludePath, scanPath, scanPlanId, scanGateId, waitGate, addScan, baseLine, \"512\")\n\n}\n\ndef call(String stepName, String excludePath, String scanPath, String scanPlanId, String scanGateId, boolean waitGate, boolean addScan, String baseLine, String scanJvm) {\n    if (scanJvm == \'scanJvm\') {\n        scanJvm = \"512\"\n    }\n    sh \"\"\"\n        export SONAR_SCANNER_OPTS=\"-Xms${scanJvm}m -Xmx${scanJvm}m\"\n         \"\"\"\n    def excludesOp = \'\'\n    if (excludePath) {\n        excludesOp = \"sonar.exclusions=${excludePath}\"\n    }\n    def projectKey = \'\'\n    def taskId = \'\'\n    // scanTaskId  scanGateId job_id 返回 projectKey\n    if(!env.gitlabId){\n        echo \"参数gitlabId缺失\"\n    }\n    if (env.gitlabId) {\n        //编辑接口修改scanPlanId和scanGateId，返回正确的taskId\n        def response = sh returnStdout: true, script: \"\"\"\n        curl -X POST \"${env.scmSvcUrl}/codescan/${env.gitLabId}/pipeline\" -H \"accept: */*\" -H \"Content-Type: application/json\" -H \"Amp-Organ-Id: ${env.tenantId}\" -H \"X-SCM-TOKEN: SCM@2023\"  -d \"{\\\\\\\"codeRepoId\\\\\\\":\\\\\\\"${gitLabId}\\\\\\\",\\\\\\\"qualityGateIsOpen\\\\\\\":1,\\\\\\\"mergeIsCheck\\\\\\\":1,\\\\\\\"serverId\\\\\\\":\\\\\\\"${env.mergeServerId}\\\\\\\",\\\\\\\"exclusionPath\\\\\\\":\\\\\\\"${excludePath}\\\\\\\",\\\\\\\"scanMode\\\\\\\":1,\\\\\\\"scanPlanId\\\\\\\":\\\\\\\"${scanPlanId}\\\\\\\",\\\\\\\"qualityGateId\\\\\\\":\\\\\\\"${scanGateId}\\\\\\\"}\"\n        \"\"\"\n        echo \"${response}\"\n        def resData = readJSON text: \"\"\"${response}\"\"\"\n        if (resData.code != 0) {\n            error \"查询代码库的扫描任务失败\"\n        }\n        taskId = resData.data.taskId\n        projectKey = resData.data.projectKey\n    } else {\n        def response = sh returnStdout: true, script: \"\"\"\n        curl -X POST \"${env.codeInspectSvcUrl}/scanTasks/${params.job_id}/plans/${scanPlanId}/gates/${scanGateId}\" --data-urlencode \'taskName=${JOB_NAME}\' -H \"accept: */*\" -H \"Amp-Organ-Id: ${env.tenantId}\"\n        \"\"\"\n        echo \"${response}\"\n        def resData = readJSON text: \"\"\"${response}\"\"\"\n        if (resData.code != 0) {\n            error \"创建扫描任务失败\"\n        }\n        projectKey = resData.data\n        taskId = job_id\n    }\n    def historyId = sh returnStdout: true, script: \"\"\"\n        curl -X POST \"${env.codeInspectSvcUrl}/scanTasks/${taskId}/histories\" --data-urlencode branch=${env.mergeBranch} -H \"accept: */*\" -H \"Amp-Organ-Id: ${env.tenantId}\" -H \"X-SCM-TOKEN: SCM@2023\"   -d \"\"\n        \"\"\"\n    dir(scanPath) {\n        try {\n            def sonarConfigfile = \'sonar-project.properties\'\n\n            if(fileExists(sonarConfigfile)){\n                def properties = readProperties file: sonarConfigfile\n                sh script: \"rm ${sonarConfigfile}\", returnStatus: true\n                def jacoco = properties[\'sonar.java.coveragePlugin\']\n                if(jacoco != null) sh \"echo sonar.java.coveragePlugin=${jacoco} >>sonar-project.properties\"\n                def analysis = properties[\'sonar.dynamicAnalysis\']\n                if(analysis != null) sh \"echo sonar.dynamicAnalysis=${analysis} >>sonar-project.properties\"\n                def reportPath = properties[\'sonar.coverage.jacoco.xmlReportPaths\']\n                if(reportPath != null) sh \"echo sonar.coverage.jacoco.xmlReportPaths=${reportPath} >>sonar-project.properties\"\n            }\n\n            def commitId = sh(returnStdout: true, script: \'git rev-parse --verify  HEAD\').trim()\n            // def sonarModules = collectmodules(scanPath)\n            // 增量扫描逻辑\n            if (!baseLine) {\n                baseLine = sh returnStdout: true, script: \"\"\"\n        curl -X POST ${env.codeInspectSvcUrl}/scanTasks/${taskId}/baseLine -H \"accept: */*\" -H \"X-SCM-TOKEN: SCM@2023\"  -H \"Amp-Organ-Id: ${env.tenantId}\" -d \"\"\n        \"\"\"\n            }\n            if (addScan && baseLine) {\n                sh \"git fetch --unshallow\"\n                def changeFile = sh returnStdout: true, script: \"git diff ${baseLine} --name-only\"\n                if (changeFile) {\n                    files = changeFile.replaceAll(\"\\n\", \",\")\n                    sh \"echo sonar.inclusions=${files} >> sonar-project.properties\"\n                }\n                def commitWithDate = sh returnStdout: true, script: \"git log --remotes --pretty=%H@%cd --date=iso|grep ${baseLine}\"\n                def compareBaseTime = \"sonar.analysis.baseTime=\\\"\" + commitWithDate.split(\"@\")[1] + \"\\\"\"\n                sh \"echo ${compareBaseTime} >>sonar-project.properties\"\n            }\n            // 判断c++与ios语言\n            def sonarArg = \'\'\n            if (env.language == \"cxx\") {\n                sh \"cppcheck -j 4 --enable=all --xml ./* 1>cppcheck-result.xml\"\n                sh \"echo sonar.cxx.cppcheck.reportPaths=cppcheck-result.xml >>sonar-project.properties\"\n                sh \"echo sonar.cxx.file.suffixes=.cpp,.h >>sonar-project.properties\"\n                sh \"echo sonar.lang.patterns.objc=- >>sonar-project.properties\"\n            }\n            if(env.language==\"ios\"){\n                sh \"echo sonar.swift.infer.report=infer-out/report.json >>sonar-project.properties\"\n                sh \"echo sonar.swift.oclint.report=oclint.xml >>sonar-project.properties\"\n                sh \"echo sonar.swift.swiftlint.report=swiftlint.txt >>sonar-project.properties\"\n            }\n            sh \"echo sonar.java.binaries=./ >>sonar-project.properties\"\n            sh \"echo ${excludesOp} >>sonar-project.properties\"\n//            sh \"echo ${sonarModules} >>sonar-project.properties\"\n            sh \"echo sonar.branch.name=${env.mergeBranch} >>sonar-project.properties\"\n            sh \"echo sonar.analysis.doorFlag=${waitGate} >>sonar-project.properties\"\n            sh \"echo sonar.analysis.scanTaskId=${taskId} >>sonar-project.properties\"\n            sh \"echo sonar.analysis.historyId=${historyId} >>sonar-project.properties\"\n            sh \"echo sonar.analysis.buildId=${env.buildId} >>sonar-project.properties\"\n            sh \"echo sonar.host.url=${env.sonarUrl} >>sonar-project.properties\"\n            withCredentials([usernamePassword(credentialsId: \'sonar-username-password\',passwordVariable: \'sonarpassword\', usernameVariable: \'sonarusername\')]) {\n                sh \"\"\"\n                set +x\n                echo sonar.login=${sonarusername}>>sonar-project.properties\n                echo sonar.password=${sonarpassword}>>sonar-project.properties\n                set -x                \n                \"\"\"\n            }\n            sh \"echo sonar.projectKey=${projectKey}  >>sonar-project.properties\"\n            sh \"echo sonar.analysis.commitId=${commitId}  >>sonar-project.properties\"\n            sh \"sonar-scanner\"\n        } catch (Exception e) {\n            echo \"执行sonar scanner 报错，e:\"\n            echo \"${e}\"\n            echo \"标记扫描任务执行异常\"\n\n            sh returnStdout: true, script: \"\"\"\n            curl -X GET ${env.codeInspectSvcUrl}/scanTasks/history/${historyId}/error -H \"accept: */*\" -H \"X-SCM-TOKEN: SCM@2023\"  -H \"Amp-Organ-Id: ${env.tenantId}\"\n            \"\"\"\n            error \"扫描器执行异常\"\n\n            // sh \'\'\'\n            // curl \"${env.codeInspectSvcUrl}/scanTasks/history/${historyId}/error\"\n            // exit 1\n            // \'\'\'\n        }\n    }\n    env.sonarScanStepFlag = true\n    sh \"\"\"\n    curl -X POST \"${env.pipelineSvcUrl}/devops/buildSonarRel\" -H \"accept: */*\" -H \"Content-Type: application/json\" -H \"Amp-Organ-Id: ${env.tenantId}\" -d \"{\\\\\\\"buildId\\\\\\\":\\\\\\\"${env.buildId}\\\\\\\",\\\\\\\"gitlabId\\\\\\\":\\\\\\\"${env.gitlabId}\\\\\\\",\\\\\\\"serverId\\\\\\\":\\\\\\\"${env.mergeServerId}\\\\\\\",\\\\\\\"vulneHistoryId\\\\\\\":\\\\\\\"${historyId}\\\\\\\",\\\\\\\"vulneTaskId\\\\\\\":\\\\\\\"${taskId}\\\\\\\"}\"\n    \"\"\"\n\n    if (waitGate) {\n        timeout(time: 30, unit: \'MINUTES\') {\n            input(message: \'\', id: \'input\', ok: \'\', submitter: \'admin\')\n        }\n\n    }\n\n\n}\n\n// def collectmodules(String moduleName) {\n//     dir(moduleName) {\n//         def path = \'pom.xml\'\n//         if (fileExists(path)) {\n//             def project = readMavenPom file: path\n//             def modules = []\n//             for (def v : project.getModules()) {\n//                 modules.add(v)\n//             }\n//             if (modules.size() == 0) return \"\"\n//             if (moduleName == \".\") {\n//                 moduleName = \"\"\n//             } else {\n//                 moduleName = moduleName + \".\"\n//             }\n//             def sonarModules = \"\"\n//             sonarModules = moduleName + \"sonar.modules=\" + modules.join(\",\")\n//             for (def v : modules) {\n//                 sh \"echo ${sonarModules} >>sonar-project.properties\"\n//                 collectmodules(v)\n//             }\n//             return sonarModules\n//         } else {\n//             return \"\"\n//         }\n//     }\n\n// }\n\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (245, 1003, '蓝鲸部署', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"packageCatalog\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"dj8rnb3sst5\",\"x-decorator-props\":{},\"name\":\"packageCatalog\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"文件同步路径\",\"x-index\":0,\"required\":true},\"creator\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"gyw4i20sagx\",\"x-decorator-props\":{},\"name\":\"creator\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"文件同步创建人\",\"x-index\":1,\"required\":true}},\"x-designable-id\":\"tum1cxr1o2z\"}}]', '{\"name\":\"bluewhale\",\"arguments\":[{\"isLiteral\":true,\"value\":\"蓝鲸部署\"},{\"isLiteral\":true,\"value\":\"packageCatalog\"},{\"isLiteral\":true,\"value\":\"creator\"}],\"stepFunc\":\"bluewhale\"}', NULL, '蓝鲸部署', 0, 0, '2023-05-05 11:15:10', '2023-06-15 16:02:42', 1, 9999, 'bluewhale', '0', '0', '1', 'def call(String stepName,String packageCatalog, String creator){ //            | 字段名           | 是否必填  | 备注          | 提示                   | //            | --------------- | -------- | ------------- | --------------------- | //            | package_catalog | Y        | 文件同步路径   | /other/yunwei/20220628 | //            | creator         | Y        | 文件同步创建人 |  admin                 |     //前置需要生成制品的子步骤     //env.bluewhaleUrl：为蓝鲸平台的地址     //1.自动分拣     response1 = sh returnStdout: true ,script:\"\"\"         curl -X POST \"${env.bluewhaleUrl}/o/app-publish_v2/api/patch_new_file\" -H \"accept: */*\" -d \"{\\\\\\\"package_catalog\\\\\\\":\\\\\\\"${packageCatalog}\\\\\\\",\\\\\\\"creator\\\\\\\":\\\\\\\"${creator}\\\\\\\"}\"     \"\"\"     taskData1 = readJSON text: \"\"\"${response1}\"\"\"     def fileIds = taskData1.data.file_ids      //2.查询文件分拣状态     response2 = sh returnStdout: true ,script:\"\"\"         curl -X POST \"${env.bluewhaleUrl}/o/app-publish_v2/get_all_file_sort_status\" -H \"accept: */*\" -d \"{\\\\\\\"file_ids\\\\\\\":\\\\\\\"${fileIds}\\\\\\\"}\"     \"\"\"     taskData2 = readJSON text: \"\"\"${response2}\"\"\"     sortResult = taskData2.data     sortResult.each { data ->         if(data.status == \"error\" ){             error \"${data.file_name} ${data.reason}\"         }     }      //3.自动分发（自动分发默认标签类型的标签）     response3 = sh returnStdout: true ,script:\"\"\"         curl -X POST \"${env.bluewhaleUrl}/o/app-publish_v2/auto_batch_distribute_file\" -H \"accept: */*\" -d \"{\\\\\\\"file_ids\\\\\\\":\\\\\\\"${fileIds}\\\\\\\",\\\\\\\"username\\\\\\\":\\\\\\\"${creator}\\\\\\\"}\"     \"\"\"     taskData3 = readJSON text: \"\"\"${response3}\"\"\"      //4.查询文件分发状态     response4 = sh returnStdout: true ,script:\"\"\"         curl -X POST \"${env.bluewhaleUrl}/o/app-publish_v2/get_all_file_distribute_status\" -H \"accept: */*\" -d \"{\\\\\\\"file_ids\\\\\\\":\\\\\\\"${fileIds}\\\\\\\"}\"     \"\"\"     taskData4 = readJSON text: \"\"\"${response4}\"\"\"     disResult = taskData4.data     disResult.each { data ->         if(data.status == \"error\" ){             error \"${data.file_name} ${data.reason}\"         }     }      //5.生成批量发布任务（自动生成默认标签类型下的标签）     response5 = sh returnStdout: true ,script:\"\"\"         curl -X POST \"${env.bluewhaleUrl}/o/app-publish_v2/auto_create_publish_task\" -H \"accept: */*\" -d \"{\\\\\\\"file_ids\\\\\\\":\\\\\\\"${fileIds}\\\\\\\",\\\\\\\"username\\\\\\\":\\\\\\\"${creator}\\\\\\\"}\"     \"\"\"     taskData5 = readJSON text: \"\"\"${response5}\"\"\"     if(taskData5.result != true){         error \"${taskData5.message}\"     }      //6.执行任务     response6 = sh returnStdout: true ,script:\"\"\"         curl -X POST \"${env.bluewhaleUrl}/o/app-publish_v2/auto_run_application_task\" -H \"accept: */*\" -d \"{\\\\\\\"task_ids\\\\\\\":\\\\\\\"${taskData5.data}\\\\\\\",\\\\\\\"username\\\\\\\":\\\\\\\"${creator}\\\\\\\"}\"     \"\"\"     taskData6 = readJSON text: \"\"\"${response6}\"\"\"     if(taskData6.result != true){         error \"${taskData6.message}\"     } }', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (246, 1003, '可信源扫描', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"token\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"kunt57cw8ud\",\"x-decorator-props\":{},\"name\":\"token\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"孝道token\",\"x-index\":0,\"required\":true},\"systemNameCn\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"l4beuk6qi8t\",\"x-decorator-props\":{},\"name\":\"systemNameCn\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"系统中文名\",\"x-index\":1,\"required\":true},\"subSysNameCn\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"gx5hsbjxuc7\",\"x-decorator-props\":{},\"name\":\"subSysNameCn\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"子系统中文名\",\"x-index\":2,\"required\":true},\"systemCode\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"bcfebj8ua09\",\"x-decorator-props\":{},\"name\":\"systemCode\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"系统编码\",\"x-index\":3,\"required\":true},\"subSystemCode\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"0ytpyffq6fz\",\"x-decorator-props\":{},\"name\":\"subSystemCode\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"子系统编码\",\"x-index\":4,\"required\":true}},\"x-designable-id\":\"wvjhsfe8nvw\"}}]', '{\"name\":\"trustworthyScan\",\"arguments\":[{\"isLiteral\":true,\"value\":\"可信源扫描\"},{\"isLiteral\":true,\"value\":\"token\"},{\"isLiteral\":true,\"value\":\"systemNameCn\"},{\"isLiteral\":true,\"value\":\"subSysNameCn\"},{\"isLiteral\":true,\"value\":\"systemCode\"},{\"isLiteral\":true,\"value\":\"subSystemCode\"}],\"stepFunc\":\"trustworthyScan\"}', NULL, '可信源扫描', 0, 0, '2023-05-05 11:15:39', '2023-06-15 16:02:44', 1, 9999, 'trustworthyScan', '0', '0', '1', 'def call(String stepName, String token,String systemNameCn, String subSysNameCn, String systemCode, String subSystemCode){     env.commitId = sh returnStdout: true, script: \'git rev-parse --verify --short HEAD\'      sh \"\"\" /usr/local/xiaodao/xd/whalefall --url https://158.1.16.220:10000 \\      def rep = sh returnStdout: true, script: \"\"\"     curl -X POST \'${env.trustworthyUrl}/openApi/data/collect/file\' \\     \"\"\"     echo \"${rep}\" }', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (247, 1003, '制品扫描', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"nexusUrl\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"riyoklwobku\",\"x-decorator-props\":{},\"name\":\"nexusUrl\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"nexus制品地址\",\"x-index\":0,\"required\":true},\"productId\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"tjd21oqt5o3\",\"x-decorator-props\":{},\"name\":\"productId\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"制品ID\",\"x-index\":1,\"required\":true},\"productName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"spd3pjyor04\",\"x-decorator-props\":{},\"name\":\"productName\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"制品名称\",\"x-index\":2,\"required\":true},\"repositoryName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"cfnqdqnxkwe\",\"x-decorator-props\":{},\"name\":\"repositoryName\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"仓库名称\",\"x-index\":3,\"required\":true},\"token\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"hcsydw6unds\",\"x-decorator-props\":{},\"name\":\"token\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"孝道token\",\"x-index\":4,\"required\":true}},\"x-designable-id\":\"dq05a7gjldz\"}}]', '{\"name\":\"productTrustworthyScan\",\"arguments\":[{\"isLiteral\":true,\"value\":\"制品扫描\"},{\"isLiteral\":true,\"value\":\"nexusUrl\"},{\"isLiteral\":true,\"value\":\"productId\"},{\"isLiteral\":true,\"value\":\"productName\"},{\"isLiteral\":true,\"value\":\"repositoryName\"},{\"isLiteral\":true,\"value\":\"token\"}],\"stepFunc\":\"productTrustworthyScan\"}', NULL, 'nexus孝道扫描', 0, 0, '2023-06-02 15:15:08', '2023-06-15 16:14:23', 1, 9999, 'productTrustworthyScan', '0', '0', '2', 'def call(String stepName, String nexusUrl,String productId, String productName, String repositoryName, String token){     sh \"wget ${nexusUrl}\"      sh \'\'\'ls\'\'\'     sh \"\"\"/usr/local/xiaodao/xd/whalefall --url https://158.1.16.220:10000 --token \"${token}\" --appName \"${productName}\" --appkey \"${productId}\" --path./ --export.filepath report.json --export.json\"\"\"      def rep = sh returnStdout: true, script: \"\"\"     curl -X POST \'${env.trustworthyUrl}/openApi/data/collect/file\' \\     \"\"\"      echo \"${rep}\" } ', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (249, 1008, '执行Kubernetes命令', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"deployEnv\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"l0wxu932ssu\",\"x-decorator-props\":{\"tooltip\":\"数据来源：平台部署环境管理\"},\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  // $self.value = \\\"\\\"\\n  var systemId = sessionStorage.getItem(\\\"systemId\\\")\\n  fetch(`${window.location.origin}/api//efficiency/deploy/env?systemId=${systemId}`, {\\n    headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.records.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"\\\",\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"deployEnv\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"部署环境\",\"x-index\":0,\"required\":true},\"deployCluster\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"1f9hek5b42a\",\"x-decorator-props\":{\"tooltip\":\"数据来源：部署环境资源管理\"},\"name\":\"deployCluster\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.deployEnv) {\\n    $self.loading = true\\n    const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n   // $self.value = \\\"\\\"\\n    fetch(\\n      `${window.location.origin}/api/efficiency/deploy/host/listAll?envId=${$deps.deployEnv}&type=4`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId,Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"\\\",\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.deployEnv])\\n\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployEnv\",\"source\":\"deployEnv\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"集群\",\"x-index\":1,\"required\":true},\"command\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"24r7ghj67sw\",\"x-decorator-props\":{},\"name\":\"command\",\"x-validator\":[],\"x-component-props\":{\"style\":{\"height\":\"200px\"}},\"type\":\"string\",\"title\":\"kubectl命令\",\"x-index\":2,\"required\":true}},\"x-designable-id\":\"bbivnsdarod\"}}]', '{\"name\":\"kubernetesCommand\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployEnv\"},\"key\":\"deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployCluster\"},\"key\":\"deployCluster\"},{\"value\":{\"isLiteral\":true,\"value\":\"command\"},\"key\":\"command\"}],\"stepFunc\":\"kubernetesCommand\"}', NULL, '在kubernetes集群上执行命令', 1, 0, '2023-06-14 14:40:39', '2024-02-04 16:34:56', 1, 1, 'kubernetesCommand', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.deployEnv,map.deployCluster,map.command)\n    echo env.endString\n\n}\n\ndef call(String stepName,String envId,String clusterId,String command){\n    if(env.clusterId){\n        clusterId = env.clusterId\n    }\n    if(env.namespace){\n        namespace = env.namespace\n    }\n\n   def response = sh returnStdout: true ,script:\"\"\"\n    curl -X GET \"${env.pipelineSvcUrl}/deploy/cluster/${clusterId}/token\" -H \"accept: */*\"\n    \"\"\"\n    def resData = readJSON text: \"\"\"${response}\"\"\"\n    def token = resData.data[0].token.trim();\n    if(token.startsWith(\"apiVersion\")){\n        writeFile encoding: \"utf-8\", file: \"kubeconfig\", text: \"\"\"${token}\"\"\"\n        sh \"\"\"\n        rm -rf /root/.kube/config\n        mv kubeconfig /root/.kube/config\n        \"\"\"\n    }else{\n        sh \"\"\"\n        kubectl config set-cluster kubernetes --server=https://${resData.data[0].ip}:${resData.data[0].port} --insecure-skip-tls-verify=true\n        set +x\n        kubectl config set-credentials admin --token=${token}\n        set -x\n        kubectl config set-context dev --cluster=kubernetes --user=admin\n        kubectl config use-context dev\n         \"\"\"\n\n    }\n    sh \"\"\"\n        chmod g-rw ~/.kube/config\n        chmod o-r ~/.kube/config\n    \"\"\"\n\n    sh \"\"\"\n    ${command}\n    \"\"\"\n\n}', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (251, 1002, '镜像构建（子系统）', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"startParamName_dockerRepository\":{\"x-component\":\"Select\",\"x-designable-id\":\"n5ywvi2b3yi\",\"x-decorator-props\":{\"tooltip\":\"数据来源：平台制品仓库的docker仓库\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"镜像仓库\",\"x-index\":0,\"required\":true,\"default\":\"${dockerRepository}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_dockerRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"imageName\":{\"x-component\":\"Input\",\"x-designable-id\":\"9d6nrjboove\",\"x-decorator-props\":{\"tooltip\":\"镜像名称不能有大写，空格等字符\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"镜像名称\",\"x-index\":1,\"required\":false,\"x-decorator\":\"FormItem\",\"name\":\"imageName\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n\\n  // $self.value = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  var subSystemId = window.sessionStorage.getItem(\\\"subSystemId\\\")\\n  fetch(\\n    `${window.location.origin}/api/cloud/subSystem/getById/${subSystemId}`,\\n    {\\n      headers: { Authorization: token },\\n    }\\n  )\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        $self.value = data.subCode.toLowerCase()\\n        $self.loading = false\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"dockerfile\":{\"x-component\":\"Input\",\"x-designable-id\":\"qorm04hiij6\",\"x-decorator-props\":{\"tooltip\":\"镜像打包文件的相对路径\"},\"description\":\"\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"Dockerfile\",\"x-index\":2,\"required\":true,\"default\":\"Dockerfile\",\"x-decorator\":\"FormItem\",\"name\":\"dockerfile\"},\"platform\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"9fgf2o8tdei\",\"x-decorator-props\":{\"tooltip\":\"支持arm64和amd平台\",\"addonBefore\":\"\"},\"name\":\"platform\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"平台\",\"x-index\":3,\"required\":true,\"enum\":[{\"children\":[],\"label\":\"amd64\",\"value\":\"amd64\"},{\"children\":[],\"label\":\"arm64\",\"value\":\"arm64\"}]},\"startParamName_version\":{\"default\":\"${version}\",\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"4if625leaiu\",\"x-decorator-props\":{},\"name\":\"startParamName_version\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{false}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"版本\",\"x-index\":4},\"tag\":{\"x-component\":\"Input\",\"x-designable-id\":\"52v27r0372n\",\"x-decorator-props\":{\"tooltip\":\"自动生成镜像标签，命名规则：版本号_打包时间戳。版本号会设置为流水线启动变量，运行流水线时可以选择版本\"},\"x-validator\":[],\"x-component-props\":{\"placeholder\":\"${版本号}_${时间戳}\"},\"type\":\"string\",\"title\":\"镜像标签\",\"x-index\":5,\"required\":false,\"default\":\"${version}_${date}\",\"x-decorator\":\"FormItem\",\"name\":\"tag\",\"x-reactions\":{\"fulfill\":{\"state\":{}},\"dependencies\":[]},\"x-pattern\":\"disabled\"}},\"x-designable-id\":\"5gimo0b344q\"}}]', '{\"name\":\"subSystemImageBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_dockerRepository\"},\"key\":\"startParamName_dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"imageName\"},\"key\":\"imageName\"},{\"value\":{\"isLiteral\":true,\"value\":\"dockerfile\"},\"key\":\"dockerfile\"},{\"value\":{\"isLiteral\":true,\"value\":\"platform\"},\"key\":\"platform\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_version\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"tag\"},\"key\":\"tag\"}],\"stepFunc\":\"subSystemImageBuild\"}', NULL, '构建Docker镜像并推送镜像仓库', 1, 0, '2023-06-16 15:47:57', '2024-02-21 13:44:08', 1, 1, 'subSystemImageBuild', '2', '2', '2', '\ndef call(def map){\n    \n    def dockerRepository = map.startParamName_dockerRepository\n    echo \"repoId: ${dockerRepository}\"\n    def version = env.version\n    env.imageVersion = version\n    version = version + \"_\" + env.date\n    call(map.stepName,dockerRepository,map.imageName,map.dockerfile,map.platform,version)\n    echo env.endString\n\n}\n\ndef call(String stepName,String repoId,String imageName,String dockerfile,String platform,String version){\n     \n    def result = sh returnStdout: true ,script: \"\"\"\n    curl -X GET \"${env.repositorySvcUrl}/api/repository/detail?id=${repoId}\" -H \"accept: */*\" -d \"\"\n    \"\"\"\n    echo \"${result}\"\n    def resData = readJSON text: \"\"\"${result}\"\"\"\n    if(resData.code != 0){\n        error \"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\"\n    }\n    def repoUrl = resData.data.url.replace(\"https://\",\"\").replace(\"http://\",\'\')\n        \n  \n    \n    if(!fileExists(dockerfile)){\n        def language= env.language\n        println(\"-------------\"+language)\n        if(language == \'java8\' ||  language == \'java\'){\n            if(env.packageType == \'war\'){\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:8\nWORKDIR /app\nCOPY target/*.war ./app.war\n\"\"\"\n            }else {\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:8\nWORKDIR /app\nCOPY target/*.jar ./app.jar\nENTRYPOINT [\"java\", \"-jar\",\"/app/app.jar\"]\n\"\"\"\n            }\n        }else if(language == \'java11\'){\n            if(env.packageType == \'war\'){\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:11\nWORKDIR /app\nCOPY target/*.war ./app.war\n\"\"\"\n            }else {\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:11\nWORKDIR /app\nCOPY target/*.jar ./app.jar\nENTRYPOINT [\"java\", \"-jar\",\"/app/app.jar\"]\n\"\"\"\n            }\n        }else if(language == \'node14\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM node:14.16\nWORKDIR /app\nCOPY dist/ ./dist/\nENTRYPOINT npm run entrypoint\n\"\"\"\n        }else if(language == \'net5\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM mcr.microsoft.com/dotnet/runtime:3.1.31-buster-slim\nWORKDIR /app\nCOPY app/build/ ./\nENTRYPOINT [\"dotnet\", \"dotnetWebDemo.dll\"]\n\"\"\"\n        }else if(language == \'php7\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM php:7.4.33-cli-bullseye\nWORKDIR /app\nCOPY ./ ./\nRUN composer install\nCMD [\"php\", \"-S 0.0.0.0:80\", \"-t ./\"]\n\"\"\"\n        }else if(language == \'golang1.19\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM golang:1.19-bullseye\nUSER root\nWORKDIR /home/go\nCOPY ./ ./\nENTRYPOINT [\"./go-app\"]\n\"\"\"\n        }else if(language == \'python3\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM python:3.8-bullseye\nUSER root\nWORKDIR /home/python\nCOPY dist/ ./dist/\n\"\"\"\n        }else{\n            error \"error\"\n        }\n    }\n    incall(repoId,repoUrl,imageName,dockerfile,platform,version)\n}\n// 该方法是给脚本调用使用的\ndef incall(String harborRepoId,String harborUrl,String imageName,String dockerfile,String platform,String version){\n    if(platform == \'arm64\'){\n      sh \"\"\"\n      export DOCKER_HOST=tcp://10.10.102.93:2375\n      docker buildx build --platform linux/arm64 -f ${dockerfile} -t ${harborUrl}/${imageName}:${version} . --load \n      \"\"\"\n    }else{\n      sh \"docker build -f ${dockerfile} -t ${harborUrl}/${imageName}:${version} .\"\n    }\n\n    withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n         retry(3) {\n            sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n         }\n\n    }\n    \n    // if(\"${harborUrl}\".startsWith(\"10.120.1.233\")){\n    //     withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials-233\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n    //      retry(3) {\n    //         sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n    //      }\n\n    //     }\n    // } else {\n    // withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n    //      retry(3) {\n    //         if(platform == \'arm64\'){\n    //             sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n    //         }else{\n    //             sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n    //         }\n\n    //      }\n\n    //     }\n    // }\n    retry(3) {\n        if(platform == \'arm64\'){\n              sh \"\"\"\n              export DOCKER_HOST=tcp://10.10.102.93:2375\n              docker push ${harborUrl}/${imageName}:${version}\n              \"\"\"\n        }else{\n            sh \"docker push ${harborUrl}/${imageName}:${version}\"\n        }\n\n    }\n\n    if(platform == \'arm64\'){\n        sh \"\"\"\n        export DOCKER_HOST=tcp://10.10.102.93:2375\n        docker rmi -f ${harborUrl}/${imageName}:${version}\n        \"\"\"\n    }else{\n        sh \"docker rmi -f ${harborUrl}/${imageName}:${version}\"\n    }\n    \n    result = sh returnStdout: true ,script: \"\"\"\n    curl -X GET \"${env.codeInspectSvcUrl}/scanTasks/scanInfo/byBuildId?buildId=${env.buildId}\" -H \"accept: */*\" -d \"\"\n    \"\"\"\n    def resData = readJSON text: \"\"\"${result}\"\"\"\n    if(resData.code != 0){\n        error \"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\"\n    }\n    historyOpt = \'\'\n    if(env.soanrWaitGate || (resData.data.status != 3 && resData.data.histories.size() == 1)){\n        for(item in resData.data.histories){\n            historyOpt += \"-F \'historyId =${item.historyId}\' -F \'sonarResult =${item.status}\' \"\n        }\n    }\n\n    imageProjectName = harborUrl.split(\"/\")[1]\n    def systemOpt = \'\'\n    if(env.systemId){\n        systemOpt = \"-F \'subsystemId=${env.subsystemId}\' -F \'systemId=${env.systemId}\'\"\n    }\n    def gitInfoOpt = \'\'\n    if(env.mergeBranch){\n       gitInfoOpt = \" -F \'mergeBranch=${env.mergeBranch}\' -F \'commitId=${env.mergeCommitId}\' -F \'serverId=${env.mergeServerId}\' -F \'gitlabId=${env.mergeGitlabId}\' \" \n    }\n    result = sh returnStdout: true ,script: \"\"\"\n     curl -X POST \'${env.repositorySvcUrl}/api/provider/product/upload/container\' -H  \'accept: */*\' -H  \'Content-Type: multipart/form-data\' \\\n     -F \'jobId=${params.job_id}\' -F \'buildId=${env.buildId}\'  -F \'jobName=${env.JOB_NAME}\' -F \'repositoryName=${imageProjectName}\'\\\n     -F \'productName=${imageName}\' -F \'version=${env.imageVersion}\' -F \'versionTimestamp=${env.date}\' ${gitInfoOpt} ${historyOpt} -F \'repositoryId=${harborRepoId}\'  ${systemOpt}  -F \'userId=${env.runUserId}\'\n    \"\"\"\n    echo \"${result}\"\n    resData = readJSON text: \"\"\"${result}\"\"\"\n    if(resData.code != 0){\n        error \"上传元通用制品元数据失败\"\n    }\n    echo \"上传制品：${resData.data.id}\"\n    env.dockerDeployProduct = resData.data.id\n    env.harborUrl = harborUrl\n    env.imageName = imageName\n    env.tagert =  version\n    env.productUploadStepFlag = true\n}', '2', '', '0', '');
