 \n        }\n    }\n    \n    def sourceProduct = \'\'\n    if (map.imageSource == \'2\') {\n        if (map.startParamName_dockerDeployProduct) {\n            if(map.startParamName_dockerDeployProduct instanceof GStringImpl){\n                sourceProduct = map.startParamName_dockerDeployProduct\n            }else{\n                sourceProduct = env[map.startParamName_dockerDeployProduct]\n            }\n        } \n    } \n\n    if(sourceProduct == \'0\'){\n        def dockerRepository = map.dockerRepository\n        if(map.startParamName_dockerRepository){\n            if(map.startParamName_dockerRepository instanceof GStringImpl){\n                dockerRepository = map.startParamName_dockerRepository\n            }else{\n                dockerRepository = env[map.startParamName_dockerRepository] \n            }\n        }\n        \n    def version = \'\'\n    if(map.startParamName_version){\n        version = map.startParamName_version instanceof GStringImpl?map.startParamName_version:env[map.startParamName_version]\n    }else{\n        version = env.subSystemId?map.version:map.str_version\n    } \n        \n        \n        def subSystemIdOpt = \'\'\n        if(env.subSystemId){\n            subSystemIdOpt = \"&subsystemId=${env.subSystemId}\"\n        }\n        def result = sh returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/provider/product/lastProduct?version=${env.version}&repoId=${env.dockerRepository}${subSystemIdOpt}\" -H \"accept: */*\" -d \"\"\n        \"\"\"\n        def resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0 ){\n            error \"调用制品库服务报错，报错信息：${resData.msg}\"\n        }\n        sourceProduct = resData.data.id\n    }\n    \n    call(map.stepName,\'\',deployCluster,namespace,map.deployName,map.imageSource,sourceProduct)\n    echo env.endString\n\n}\n\ndef call(String stepName,String envId,String clusterId,String namespace,String deployment,String imageSource,String sourceRepository){\n    def imageProduct = \'\'\n    \n    if(imageSource == \'1\'){\n        imageProduct = \"${env.harborUrl}/${env.imageName}:${env.tagert}\"\n    }else{\n        def result = sh returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/product/info/${sourceRepository}\" -H \"accept: */*\" -d \"\"\n        \"\"\"\n        def resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0 ){\n            error \"查询制品信息报错，报错信息：${resData.msg}\"\n        }\n        def repoId = resData.data.repoId\n        def productName = resData.data.name\n        version = resData.data.version\n        def versionTimestamp = resData.data.versionTimestamp\n        \n        result = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/repository/detail?id=${repoId}\" -H \"accept: */*\"  \n        \"\"\")\n        resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0){\n            error \"查询凭证对应用户信息报错\"\n        }\n        sourceRepoId = resData.data.id\n        sourceRepoUrl = resData.data.url\n        \n        imageProduct = \"${sourceRepoUrl}/${productName}:${version}\"\n    }\n    \n    //根据clusterId查询环境url和token\n    response = sh returnStdout: true ,script:\"\"\"\n    curl -X GET \"${env.pipelineSvcUrl}/deploy/cluster/${clusterId}/token\" -H \"accept: */*\"\n    \"\"\"\n    resData = readJSON text: \"\"\"${response}\"\"\"\n    \n    token = resData.data[0].token.trim();\n    if(token.startsWith(\"apiVersion\")){\n        writeFile encoding: \"utf-8\", file: \"kubeconfig\", text: \"\"\"${token}\"\"\"\n        sh \"\"\"\n        rm -rf /root/.kube/config\n        mkdir -p /root/.kube\n        mv kubeconfig /root/.kube/config\n        \"\"\"\n    }else{\n        sh \"\"\"\n        kubectl config set-cluster kubernetes --server=https://${resData.data[0].ip}:${resData.data[0].port} --insecure-skip-tls-verify=true\n        set +x\n        kubectl config set-credentials admin --token=${token}\n        set -x\n        kubectl config set-context dev --cluster=kubernetes --user=admin\n        kubectl config use-context dev\n         \"\"\"\n\n    }\n    sh \"\"\"\n        chmod g-rw ~/.kube/config\n        chmod o-r ~/.kube/config\n    \"\"\"\n    \n    productIdOp = \'\'\n    if(env.dockerDeployProduct){\n        productIdOp = \"-F \'productId=${env.dockerDeployProduct}\'\"\n    }\n    configCloneCommandOp = \'\'\n    if(env.configCloneCommand){\n        configCloneCommandOp = \"-F \'configCloneCommand=${env.configCloneCommand}\'\"\n    }\n    gitlabIdOpt = \'\'\n    if(env.mergeBranch){\n       gitlabIdOpt = \"-F \'gitRepo=${env.gitRepo}\' -F \'gitBranch=${env.mergeBranch}\' -F \'gitCommitId=${env.mergeCommitId}\' -F \'gitCredentialId=${env.mergeGitCredentialId}\'\"\n        if(env.mergeGitlabId){\n            gitlabIdOpt = gitlabIdOpt + \" -F \'serverId=${env.mergeServerId}\' -F \'gitlabId=${env.mergeGitlabId}\'\"\n        } \n    }\n    \n    sh \"\"\"\n    curl -X POST \'${env.pipelineSvcUrl}/devops/buildDeploy/addK8sRecords\' -F \'buildId=${env.buildId}\' -F \'jobId=${params.job_id}\' -F \'deployType=Kubernetes镜像更新\' ${gitlabIdOpt} ${productIdOp} ${configCloneCommandOp} -F \'deployEnv=${env.deployEnv}\' -F \'hostId=${clusterId}\'  -F \'command=kubectl set image deployment ${deployment} *=${imageProduct} -n ${namespace} \nkubectl rollout restart deployment ${deployment} -n ${namespace}\' -H \'accept: */*\'\n    \"\"\"\n    \n    \n    res = sh returnStdout: true, script: \"\"\"  \n    kubectl set image deployment ${deployment} *=${imageProduct} -n ${namespace}       \n    \"\"\"\n    if (!res.contains(\"update\")) {\n        sh \"kubectl rollout restart deployment ${deployment} -n ${namespace}\"\n    }\n    \n    \n}', '2', 'v1', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (260, 1001, '应用分支合并', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"startParamName_sourceBranches\":{\"x-component\":\"Input\",\"x-designable-id\":\"78knkc2aym9\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"源分支\",\"x-index\":0,\"required\":true,\"default\":\"${sourceBranches}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_sourceBranches\",\"x-pattern\":\"disabled\"},\"targetType\":{\"default\":\"1\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"6gvzawmc9xw\",\"x-decorator-props\":{},\"name\":\"targetType\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"分支策略\",\"x-index\":1,\"enum\":[{\"children\":[],\"label\":\"新分支\",\"value\":\"1\"},{\"children\":[],\"label\":\"固定分支\",\"value\":\"2\"}],\"required\":true},\"params_targetBranch\":{\"x-component\":\"Input\",\"x-designable-id\":\"gb2iqu32efv\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"分支前缀\",\"x-index\":2,\"required\":true,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"params_targetBranch\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.targetType == \\\"1\\\") {\\n    $self.value = \\\"${targetBranch}\\\"\\n  } else {\\n    $self.value = \\\"\\\"\\n  }\\n}, [$deps.targetType])\\n\",\"state\":{\"visible\":\"{{$deps.targetType === \'1\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"targetType\",\"source\":\"targetType\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"mergeBranch\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"6nfsznacerc\",\"x-decorator-props\":{},\"name\":\"mergeBranch\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  if (true) {\\n    // $self.value = \\\"\\\"\\n    const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n    var subSystemId = window.sessionStorage.getItem(\\\"subSystemId\\\")\\n    fetch(`${window.location.origin}/api/cloud/scm/${subSystemId}/branches`, {\\n      headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n    })\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          console.log(data)\\n          const re =\\n            data.map((k) => ({\\n              value: k.name,\\n              label: k.name,\\n            })) || []\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [])\\n\",\"state\":{\"visible\":\"{{$deps.targetType === \'2\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"targetType\",\"source\":\"targetType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"目标分支\",\"x-index\":3,\"required\":true}},\"x-designable-id\":\"rqa2hv8ka4o\"}}]', '{\"name\":\"subSystemBranchMerge\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_sourceBranches\"},\"key\":\"startParamName_sourceBranches\"},{\"value\":{\"isLiteral\":true,\"value\":\"targetType\"},\"key\":\"targetType\"},{\"value\":{\"isLiteral\":true,\"value\":\"params_targetBranch\"},\"key\":\"params_targetBranch\"},{\"value\":{\"isLiteral\":true,\"value\":\"mergeBranch\"},\"key\":\"mergeBranch\"}],\"stepFunc\":\"subSystemBranchMerge\"}', NULL, '将源分支合并到目标分支', 1, 0, '2023-07-28 09:16:37', '2024-06-26 10:43:11', 1, 1, 'subSystemBranchMerge', '2', '2', '2', 'import org.codehaus.groovy.runtime.GStringImpl\n\ndef call(def map){\n    def sourceBranches = \'\'\n    if(map.startParamName_sourceBranches){\n        if(map.startParamName_sourceBranches instanceof GStringImpl){\n            sourceBranches = map.startParamName_sourceBranches\n        }else{\n            sourceBranches = env[map.startParamName_sourceBranches]\n        }\n    }else{\n       sourceBranches = map.array_sourceBranches\n    }\n    call(map.stepName,sourceBranches,map.targetType,map.params_targetBranch,map.mergeBranch)\n    echo env.endString\n}\n\ndef call(String stepName,String sourceBranchs,String targetBranchType,String targetTail,String targetBranch){\n    \n    //test\n    def response = sh(returnStdout: true , script: \"\"\"\n    curl -X GET \"${env.developmentSvcUrl}open/pipeline/getSubSystemById?subSystemId=${env.subSystemId}\" -H \"Amp-Organ-Id: ${env.tenantId}\"\n    \"\"\")\n    echo \"${response}\"\n    def resData = readJSON text: \"\"\"${response}\"\"\"\n    serverId = resData.data.serverId\n    gitlabId = resData.data.gitlabId\n    gitRepo = resData.data.gitlabRepo\n    branchMerge(stepName,serverId,gitlabId+\"|\"+gitRepo,sourceBranchs,targetBranchType,targetTail,targetBranch)\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (262, 1004, '子系统制品晋级', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"productType\":{\"x-component\":\"Radio.Group\",\"x-designable-id\":\"hxr6s1vlbs1\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string | number\",\"title\":\"仓库类型\",\"x-index\":0,\"enum\":[{\"children\":[],\"label\":\"通用制品\",\"value\":\"raw\"},{\"children\":[],\"label\":\"Docker制品\",\"value\":\"docker\"}],\"required\":true,\"default\":\"raw\",\"x-decorator\":\"FormItem\",\"name\":\"productType\"},\"startParamName_rawRepository\":{\"x-component\":\"Input\",\"x-designable-id\":\"k2l3y3ygth2\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"title\":\"来源仓库\",\"x-index\":1,\"required\":true,\"default\":\"${rawRepository}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_rawRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  productType: \\\"\\\",\\n})\\n$effect(() => {\\n  if ($deps.productType) {\\n    if (state.productType == \\\"\\\") {\\n      state.productType = \\\"1\\\"\\n    } else {\\n      $self.value = \\\"\\\"\\n    }\\n    if($deps.productType === \\\"raw\\\"){\\n      $self.value = \\\"${rawRepository}\\\"\\n    }else{\\n      $self.value = \\\"${dockerRepository}\\\"\\n    }\\n  }\\n}, [$deps.systemId, $deps.productType])\\n\",\"state\":{\"visible\":\"{{$deps.productType === \'raw\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"productType\",\"source\":\"productType\",\"type\":\"string | number\"}]},\"x-pattern\":\"disabled\"},\"startParamName_dockerRepository\":{\"x-component\":\"Input\",\"x-designable-id\":\"p71sejrciyp\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"title\":\"来源仓库\",\"x-index\":2,\"required\":true,\"default\":\"${dockerRepository}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_dockerRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  productType: \\\"\\\",\\n})\\n$effect(() => {\\n  if ($deps.productType) {\\n    if (state.productType == \\\"\\\") {\\n      state.productType = \\\"1\\\"\\n    } else {\\n      $self.value = \\\"\\\"\\n    }\\n    if($deps.productType === \\\"raw\\\"){\\n      $self.value = \\\"${rawRepository}\\\"\\n    }else{\\n      $self.value = \\\"${dockerRepository}\\\"\\n    }\\n  }\\n}, [$deps.systemId, $deps.productType])\\n\",\"state\":{\"visible\":\"{{$deps.productType === \'docker\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"productType\",\"source\":\"productType\",\"type\":\"string | number\"}]},\"x-pattern\":\"disabled\"},\"startParamName_version\":{\"x-component\":\"Input\",\"x-designable-id\":\"fcz7ipyb000\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{\"placeholder\":\"\"},\"title\":\"制品版本\",\"x-index\":3,\"required\":true,\"default\":\"${version}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_version\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[]},\"x-pattern\":\"disabled\"},\"startParamName_promotionPackage\":{\"x-component\":\"Input\",\"x-designable-id\":\"uhv5qeqknj7\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{\"placeholder\":\"\"},\"title\":\"晋级制品\",\"x-index\":4,\"required\":true,\"default\":\"${promotionPackage}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_promotionPackage\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[]},\"x-pattern\":\"disabled\"},\"startParamName_promotionRawRepository\":{\"x-component\":\"Select\",\"x-designable-id\":\"nfe3mnz5odv\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"title\":\"目标仓库\",\"x-index\":5,\"required\":true,\"default\":\"${promotionRawRepository}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_promotionRawRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"\",\"state\":{\"visible\":\"{{$deps.productType === \'raw\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"productType\",\"source\":\"productType\",\"type\":\"string | number\"}]},\"x-pattern\":\"disabled\"},\"startParamName_promotionDockerRepository\":{\"x-component\":\"Select\",\"x-designable-id\":\"22abygtprr4\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"title\":\"目标仓库\",\"x-index\":6,\"required\":true,\"default\":\"${promotionDockerRepository}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_promotionDockerRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"\",\"state\":{\"visible\":\"{{$deps.productType === \'docker\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"productType\",\"source\":\"productType\",\"type\":\"string | number\"}]},\"x-pattern\":\"disabled\"}},\"x-designable-id\":\"r5gbg5krya9\"}}]', '{\"name\":\"subSystemProductPromotion\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"productType\"},\"key\":\"productType\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_rawRepository\"},\"key\":\"startParamName_rawRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_dockerRepository\"},\"key\":\"startParamName_dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_version\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_promotionPackage\"},\"key\":\"startParamName_promotionPackage\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_promotionRawRepository\"},\"key\":\"startParamName_promotionRawRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_promotionDockerRepository\"},\"key\":\"startParamName_promotionDockerRepository\"}],\"stepFunc\":\"subSystemProductPromotion\"}', NULL, '制品晋级', 1, 0, '2023-08-04 16:32:44', '2024-02-02 11:22:22', 1, 1, 'subSystemProductPromotion', '0', '0', '2', 'def call(def map){\n    productPromotion_v1(map)\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (270, 1004, '制品晋级', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"productType\":{\"x-component\":\"Radio.Group\",\"x-designable-id\":\"hxr6s1vlbs1\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string | number\",\"title\":\"制品类型\",\"x-index\":0,\"enum\":[{\"children\":[],\"label\":\"通用制品\",\"value\":\"raw\"},{\"children\":[],\"label\":\"Docker制品\",\"value\":\"docker\"}],\"required\":true,\"default\":\"raw\",\"x-decorator\":\"FormItem\",\"name\":\"productType\"},\"sourceRepository\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"azm28mnqs27\",\"x-decorator-props\":{},\"name\":\"sourceRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.productType == \\\"raw\\\") {\\n    $self.value = \\\"${rawRepository}\\\"\\n  } else {\\n    $self.value = \\\"${dockerRepository}\\\"\\n  }\\n}, [$deps.productType])\\n\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"productType\",\"source\":\"productType\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"来源仓库\",\"x-index\":1,\"required\":true},\"productId\":{\"x-component\":\"Select\",\"x-designable-id\":\"fcz7ipyb000\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{\"placeholder\":\"\"},\"title\":\"晋级制品\",\"x-index\":2,\"required\":true,\"default\":\"${promotionPackage}\",\"x-decorator\":\"FormItem\",\"name\":\"productId\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[]},\"x-pattern\":\"disabled\"},\"goalRepository\":{\"x-component\":\"Select\",\"x-designable-id\":\"nfe3mnz5odv\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"title\":\"目标环境\",\"x-index\":3,\"required\":true,\"default\":\"${promotionRepository}\",\"x-decorator\":\"FormItem\",\"name\":\"goalRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[]},\"x-pattern\":\"disabled\"}},\"x-designable-id\":\"xycz2gb2duh\"}}]', '{\"name\":\"productPromotion\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"productType\"},\"key\":\"productType\"},{\"value\":{\"isLiteral\":true,\"value\":\"sourceRepository\"},\"key\":\"sourceRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"productId\"},\"key\":\"productId\"},{\"value\":{\"isLiteral\":true,\"value\":\"goalRepository\"},\"key\":\"goalRepository\"}],\"stepFunc\":\"productPromotion\"}', NULL, '将制品从源制品库推送到指定目标制品库中', 1, 0, '2023-08-08 21:16:45', '2024-02-04 16:26:52', 1, 1, 'productPromotion', '0', '0', '2', 'def call(def map){\n    call(map.stepName,map.sourceRepository,map.productId,map.goalRepository)\n    echo env.endString\n}\n\ndef call(String  stepName, String productType, String repository, String productId, String goalRepository ) {\n    println(\"---执行子步骤${stepName}----\")\n    \n    if(productType == \'raw\'){\n        repository = env.rawRepository\n    }else {\n        repository = env.dockerRepository\n    }\n    def response = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/repository/detail?id=${repository}\" -H \"accept: */*\"  \n    \"\"\")\n    echo \"${response}\"\n    def resData = readJSON text: \"\"\"${response}\"\"\"\n    if(resData.code != 0){\n        error \"查询凭证对应用户信息报错\"\n    }\n    echo \"-------- 返回${resData}-----\"\n    sourceRepoId = resData.data.id\n    sourceRepoUrl = resData.data.url.replace(\"https://\",\"\")\n    \n    //最新制品\n    repoId = \'\'\n    productName = \'\'\n    version = \'\'\n    versionTimestamp = \'\'\n    \n    if(env.promotionPackage == \'0\'){\n        result = sh returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/provider/product/lastProduct?version=${env.version}&repoId=${repository}\" -H \"accept: */*\" -d \"\"\n        \"\"\"\n        resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0 ){\n            error \"调用制品库服务报错，报错信息：${resData.msg}\"\n        }\n        repoId = resData.data.repoId\n        productName = resData.data.name\n        version = resData.data.version\n        versionTimestamp = resData.data.versionTimestamp\n        env.sourceProductId = resData.data.id\n        if(productType == \'raw\'){\n            env.rawDeployProduct = resData.data.id\n        }else{\n            env.dockerDeployProduct = resData.data.id\n        }\n    }else{\n        result = sh returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/product/info/${env.promotionPackage}\" -H \"accept: */*\" -d \"\"\n        \"\"\"\n        echo \"${result}\"\n        resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0 ){\n            error \"查询制品信息报错，报错信息：${resData.msg}\"\n        }\n        repoId = resData.data.repoId\n        productName = resData.data.name\n        version = resData.data.version\n        versionTimestamp = resData.data.versionTimestamp\n        env.sourceProductId = resData.data.id\n    }\n    \n    echo \"version: ${version}\"\n    echo \"versionTimestamp: ${versionTimestamp}\"\n    \n    if(\"${versionTimestamp}\" != \'null\'){\n        versionTimestamp = \"_${versionTimestamp}\"\n    }else{\n        versionTimestamp = \'\'\n    }\n    echo \"versionTimestamp:   ${versionTimestamp}\"\n    productVersion = version.split(\"_\")[0]\n    productTimestamp = version.split(\"_\")[1]\n    if(productType == \'raw\'){\n        //下载通用制品\n        sh\"\"\"\n        curl --fail -X GET \"${env.repositorySvcUrl}/api/product/download?repoId=${repoId}&productName=${productName}&version=${version}\" -o ${productName}\n        \"\"\"\n        //上传通用制品\n        universalProductUpload(\'内部调用\',goalRepository,version,productName,version)\n\n    }else if(productType == \'docker\'){\n        \n        response = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/repository/detail?id=${goalRepository}\" -H \"accept: */*\"  \n        \"\"\")\n        echo \"${response}\"\n        resData = readJSON text: \"\"\"${response}\"\"\"\n        goalRepoUrl = resData.data.url\n    \n        \n        goalRepoUrl = goalRepoUrl.replace(\"https://\",\"\")\n    withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n            sh \"\"\"\n             docker login -u ${username} -p ${password} ${sourceRepoUrl}\n             docker pull ${sourceRepoUrl}/${productName}:${version}\n             docker login -u ${username} -p ${password} ${goalRepoUrl}\n             docker tag ${sourceRepoUrl}/${productName}:${version} ${goalRepoUrl}/${productName}:${version}\n             docker push ${goalRepoUrl}/${productName}:${version}\n             \"\"\"\n        }\n        subSystemOp = \'\'\n        if(env.subsystemId){\n            subSystemOp = \"-F \'subsystemId=${env.subsystemId}\'\"\n        }\n        result = sh returnStdout: true ,script: \"\"\"\n        curl -X POST \'${env.repositorySvcUrl}/api/provider/product/upload/container\' -H  \'accept: */*\' -H  \'Content-Type: multipart/form-data\' \\\n        -F \'jobId=${params.job_id}\' -F \'sourceProductId=${env.sourceProductId}\' -F \'buildId=${env.buildId}\' -F \'jobName=${env.JOB_NAME}\' \\\n        -F \'productName=${productName}\' -F \'version=${productVersion}\' -F \'versionTimestamp=${productTimestamp}\' -F \'repositoryId=${goalRepository}\'   -F \'systemId=${systemId}\' ${subSystemOp}\n        \"\"\"\n        resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0){\n            error \"上传元通用制品元数据失败\"\n        }\n        env.productUploadStepFlag = true\n\n    }\n\n\n\n}\n\n', '2', '', '0', '');
