m\",\"name\":\"to\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.fileFlag }}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"fileFlag\",\"source\":\"fileFlag\",\"type\":\"boolean\"},{\"property\":\"value\",\"name\":\"fileSource\",\"source\":\"fileSource\",\"type\":\"string | number\"}]}},\"remote_command\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"nveidvdz2o4\",\"x-decorator-props\":{\"tooltip\":\"在部署主机上执行shell命令\"},\"name\":\"remote_command\",\"description\":\"\",\"x-validator\":[],\"x-component-props\":{\"style\":{\"height\":\"200px\"}},\"type\":\"string\",\"title\":\"shell命令\",\"x-index\":9,\"required\":true}},\"x-designable-id\":\"x6yfnv2xzxo\"}}]', '{\"name\":\"hostDeployFun\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployEnv\"},\"key\":\"deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployEnv\"},\"key\":\"startParamName_deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"zjbs_btn_1\"},\"key\":\"zjbs_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployHost\"},\"key\":\"deployHost\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployHost\"},\"key\":\"startParamName_deployHost\"},{\"value\":{\"isLiteral\":true,\"value\":\"zjbs_btn_2\"},\"key\":\"zjbs_btn_2\"},{\"value\":{\"isLiteral\":true,\"value\":\"fileFlag\"},\"key\":\"fileFlag\"},{\"value\":{\"isLiteral\":true,\"value\":\"fileSource\"},\"key\":\"fileSource\"},{\"value\":{\"isLiteral\":true,\"value\":\"rawRepository\"},\"key\":\"rawRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_rawRepository\"},\"key\":\"startParamName_rawRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"zjbs_btn_3\"},\"key\":\"zjbs_btn_3\"},{\"value\":{\"isLiteral\":true,\"value\":\"version\"},\"key\":\"version\"},{\"value\":{\"isLiteral\":true,\"value\":\"str_version\"},\"key\":\"str_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_version\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"zjbs_btn_4\"},\"key\":\"zjbs_btn_4\"},{\"value\":{\"isLiteral\":true,\"value\":\"rawDeployProduct\"},\"key\":\"rawDeployProduct\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_rawDeployProduct\"},\"key\":\"startParamName_rawDeployProduct\"},{\"value\":{\"isLiteral\":true,\"value\":\"zjbs_btn_5\"},\"key\":\"zjbs_btn_5\"},{\"value\":{\"isLiteral\":true,\"value\":\"from\"},\"key\":\"from\"},{\"value\":{\"isLiteral\":true,\"value\":\"to\"},\"key\":\"to\"},{\"value\":{\"isLiteral\":true,\"value\":\"remote_command\"},\"key\":\"remote_command\"}],\"stepFunc\":\"hostDeployFun\"}', NULL, '将制品上传到指定主机并执行脚本部署', 1, 0, '2023-08-17 10:51:05', '2024-12-26 14:03:04', 1, 1, 'hostDeployFun', '3', '2', '2', 'import org.codehaus.groovy.runtime.GStringImpl\n\n\n\ndef call(def map){\n    def deployEnv = map.deployEnv\n    if(map.startParamName_deployEnv){\n        if(map.startParamName_deployEnv instanceof GStringImpl){\n            deployEnv = map.startParamName_deployEnv\n        }else{\n            deployEnv = env[map.startParamName_deployEnv] \n        }\n    }\n    def deployHost = map.deployHost\n    if(map.startParamName_deployHost){\n        if(map.startParamName_deployHost instanceof GStringImpl){\n            deployHost = map.startParamName_deployHost\n        }else{\n            deployHost = env[map.startParamName_deployHost] \n        }\n    }\n    def dockerRepository = map.dockerRepository\n    if(map.dockerRepository){\n        if(map.startParamName_dockerRepository instanceof GStringImpl){\n            dockerRepository = map.startParamName_dockerRepository\n        }else{\n            dockerRepository = env[map.startParamName_dockerRepository] \n        }\n    }\n    \n    def version = \'\'\n    if(map.startParamName_version){\n        version = map.startParamName_version instanceof GStringImpl?map.startParamName_version:env[map.startParamName_version]\n    }else{\n        version = env.subSystemId?map.version:map.str_version\n    }\n    \n    def dockerDeployProduct = map.dockerDeployProduct\n    if(map.startParamName_dockerDeployProduct){\n        if(map.startParamName_dockerDeployProduct instanceof GStringImpl){\n            dockerDeployProduct = map.startParamName_dockerDeployProduct\n        }else{\n            dockerDeployProduct = env[map.startParamName_dockerDeployProduct] \n        }\n    }\n    call(map.stepName,deployEnv,deployHost,map.fileFlag,map.fileSource,dockerRepository,version,dockerDeployProduct,map.from,map.to,map.remote_command)\n}\ndef call(String stepName,String envId,String hostId,Boolean fileFlag, String fileSource,String rawRepository,String version,String rawDeployProduct, String from ,String to,String command){\n    if(env.deployHost){\n       hostId =  env.deployHost\n    }\n   \n    \n    configCloneCommandOp = \'\'\n    if(env.configCloneCommand){\n        configCloneCommandOp = \"-F \'configCloneCommand=${env.configCloneCommand}\' \"\n    }\n    gitlabIdOpt = \'\'\n    if(env.mergeBranch){\n       gitlabIdOpt = \"-F \'gitRepo=${env.gitRepo}\' -F \'gitBranch=${env.mergeBranch}\' -F \'gitCommitId=${env.mergeCommitId}\' -F \'gitCredentialId=${env.mergeGitCredentialId}\'\"\n        if(env.mergeGitlabId){\n            gitlabIdOpt = gitlabIdOpt + \" -F \'serverId=${env.mergeServerId}\' -F \'gitlabId=${env.mergeGitlabId}\'\"\n        } \n    }\n    \n    \n    if(fileFlag){\n        if(fileSource == \'1\'){\n            productName = \'\'\n            repoId = \'\'\n            version = \'\'\n            def subsystemIdOpt = \'\'\n            if(env.subSystemId){\n                subsystemIdOpt = \"subsystemId=${env.subSystemId}&\"\n            }\n            if(env.rawDeployProduct == \'0\'){\n                result = sh returnStdout: true ,script: \"\"\"\n                curl -X GET \"${env.repositorySvcUrl}/api/provider/product/lastProduct?${subsystemIdOpt}version=${env.version}&repoId=${env.rawRepository}\" -H \"accept: */*\" -d \"\"\n                \"\"\"\n                resData = readJSON text: \"\"\"${result}\"\"\"\n                if(resData.code != 0 ){\n                    error \"调用制品库服务报错，报错信息：${resData.msg}\"\n                }\n                repoId = resData.data.repoId\n                productName = resData.data.name\n                version = resData.data.version\n                env.rawDeployProduct = resData.data.id\n            }else{\n                result = sh returnStdout: true ,script: \"\"\"\n                curl -X GET \"${env.repositorySvcUrl}/api/product/info/${env.rawDeployProduct}\" -H \"accept: */*\" -d \"\"\n                \"\"\"\n                echo \"${result}\"\n                resData = readJSON text: \"\"\"${result}\"\"\"\n                if(resData.code != 0 ){\n                    error \"查询制品信息报错，报错信息：${resData.msg}\"\n                }\n                repoId = resData.data.repoId\n                productName = resData.data.name\n                version = resData.data.version\n                \n            }\n            sh\"\"\"\n            curl --fail -X GET \"${env.repositorySvcUrl}/api/product/download?repoId=${repoId}&productName=${productName}&version=${version}\" -o ${productName}\n            \"\"\"\n            from = productName\n        }\n    }else{\n        from = \'\'\n    }\n    productIdOp = \'\'\n    deployFromOpt = \'\'\n    deployFromOpt = \"-F \'deployFrom=${from}\' -F \'hostPath=${to}\'\"\n    if(env.rawDeployProduct){\n        productIdOp = \"-F \'productId=${env.rawDeployProduct}\'\"\n    }\n    sh \"\"\"\n    curl -X POST \'${env.pipelineSvcUrl}/devops/buildDeploy/addHostRecords\' -F \'buildId=${env.buildId}\' -F \'jobId=${params.job_id}\' -F \'deployType=主机部署\' ${productIdOp} ${configCloneCommandOp} -F \'deployEnv=${env.deployEnv}\' -F \'hostId=${hostId}\' ${gitlabIdOpt} ${deployFromOpt}  -F \'command=${command}\' -H \'accept: */*\'\n    \"\"\"\n           \n    def hostArr =  hostId.split(\",\")\n    for(String host : hostArr) {\n        host = host.split(\"\\\\|\")[0]\n        def response = sh returnStdout: true ,script:\"\"\"\n        curl -X GET \"${env.pipelineSvcUrl}/deploy/host/${host}/password\" -H \"accept: */*\"\n        \"\"\"\n        def resData = readJSON text: \"\"\"${response}\"\"\"\n        def remote = [name: \"remote\", host: resData.data.ip, port: resData.data.port, user: resData.data.credential.name, allowAnyHosts: true]\n        if(resData.data.credential.credentialType == \'0\'){\n            remote.password=resData.data.credential.password\n        }else{\n            remote.identity =resData.data.credential.password\n        }\n        if(fileFlag){\n            def paths = from.split(\",\")\n            for(String path : paths) {\n               if(path != \'\'){\n                   flag = sh(script: \"[ -d \'${path}\' ]  && echo \'true\' || echo \'false\' \", returnStdout: true).trim()\n                   if(flag == \"false\"){\n                       path = sh(script: \"ls ${path}\", returnStdout: true).trim()\n                   }\n                   echo \"结果：${flag}\"\n                   if(flag == \"true\"){\n                        echo \"这是一个基于目录的拷贝，会先到host主机上删除已经存在的文件夹\" \n                        if(path == \'.\'){\n                            path = env.WORKSPACE\n                        }\n                        def arr = path.split(\"/\")\n                        def removePath = \'\'\n                        if(arr[arr.length-1] == \'\'){\n                           removePath =  to + \"/\" + arr[arr.length-2]\n                        }else{\n                           removePath =  to + \"/\" + arr[arr.length-1] \n                        }\n                        removePath = removePath.replace(\"//\",\"/\")\n                        sshCommand remote: remote, command: \"\"\"rm -rf ${removePath}\"\"\"   \n                    }\n                    sshPut remote: remote, from: \"${path}\", into: \"${to}\"\n                } \n            } \n        }\n        \n        arr = command.split(\"\\n\").join(\" ; \")\n        sshCommand remote: remote, command: \"\"\"${command}\"\"\"\n    }\n    \n}\n', '2', 'v1', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (276, 1007, 'jmeter压力测试', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"reportName\":{\"default\":\"stressTest\",\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"8deqe2pcpn5\",\"x-decorator-props\":{},\"name\":\"reportName\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"报告名称\",\"x-index\":0,\"required\":true},\"jmxPath\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"3spkot86mqf\",\"x-decorator-props\":{},\"name\":\"jmxPath\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"测试文件路径\",\"x-index\":1,\"required\":true}},\"x-designable-id\":\"b8mzd2uhbwl\"}}]', '{\"name\":\"stressTest\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"reportName\"},\"key\":\"reportName\"},{\"value\":{\"isLiteral\":true,\"value\":\"jmxPath\"},\"key\":\"jmxPath\"}],\"stepFunc\":\"stressTest\"}', NULL, '执行JMeter的jmx脚本，用于性能或接口测试', 1, 0, '2023-09-01 16:23:01', '2024-07-04 20:03:30', 1, 2432053447000854528, 'stressTest', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.reportName,map.jmxPath)\n    echo env.endString\n\n}\n\ndef call(String stepName,String reportName,String filePath){\n        echo \"下载压力测试工具\"\n        result = sh returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.repositorySvcUrl}/api/repository/getByName?name=pipeline-plugin&format=raw\" -H \"accept: */*\" -d \"\"\n        \"\"\"\n        resData = readJSON text: \"\"\"${result}\"\"\"\n        if(resData.code != 0 || resData.data == null){\n            error \"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\"\n        }\n        repoId = resData.data.id\n        //-n -t 后面跟的是要执行的脚本 -l 后面跟的是一个后缀为jtl的文件 -e -o后面的跟的是生成的测试报告的文件名\n\n        sh\"\"\"\n        set +x\n        curl --fail -X GET \"${env.repositorySvcUrl}/api/product/download/${repoId}?repositoryId=${repoId}&path=jmeter/5.5/jmeter.tar.gz\" -o jmeter.tar.gz\n        tar -zxvf jmeter.tar.gz > /dev/null 2>&1\n        mkdir -p stressTestReport/${reportName}\n        ./jmeter/bin/jmeter -n -t ${filePath} -l ${reportName}.jtl -e -o stressTestReport/${reportName}\n        set -x\n        \"\"\"\n        \n        //收集通用报告\n        sh \"echo 收集通用报告\"\n        publishHTML([allowMissing: false, alwaysLinkToLastBuild: false, keepAll: true, reportDir: \"stressTestReport/${reportName}\", reportFiles: \"index.html\", reportName: \"${reportName}\", reportTitles: \"stressTest\"])\n        \n        sh \"\"\"\n        curl -X POST \"${env.pipelineSvcUrl}/publishHtml\" -H \"accept: */*\" -H \"Content-Type: application/json\" -d \"{\\\\\\\"buildId\\\\\\\":${env.buildId},\\\\\\\"reportDir\\\\\\\":\\\\\\\"stressTestReport/${reportName}\\\\\\\",\\\\\\\"reportFiles\\\\\\\":\\\\\\\"index.html\\\\\\\",\\\\\\\"reportName\\\\\\\":\\\\\\\"${reportName}\\\\\\\"}\"\n        \"\"\"\n        \n    \n}', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (277, 1003, '制品扫描', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"analisisProductType\":{\"x-component\":\"Radio.Group\",\"x-designable-id\":\"p6gjtk3glwb\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string | number\",\"title\":\"制品类型\",\"x-index\":0,\"enum\":[{\"children\":[],\"label\":\"文件\",\"value\":\"file\"},{\"children\":[],\"label\":\"镜像\",\"value\":\"image\"}],\"required\":true,\"default\":\"file\",\"x-decorator\":\"FormItem\",\"name\":\"analisisProductType\"},\"analisisFile\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"es9verdjy3x\",\"x-decorator-props\":{},\"name\":\"analisisFile\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.analisisProductType == \'file\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"analisisProductType\",\"source\":\"analisisProductType\",\"type\":\"string | number\"}]},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"文件路径\",\"x-index\":1,\"required\":true},\"analisisSource\":{\"x-component\":\"Radio.Group\",\"x-designable-id\":\"qlx7swdx9ro\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string | number\",\"title\":\"镜像来源\",\"x-index\":2,\"enum\":[{\"children\":[],\"label\":\"上游构建步骤\",\"value\":\"1\"},{\"children\":[],\"label\":\"自定义\",\"value\":\"2\"}],\"required\":true,\"default\":\"1\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.analisisProductType == \'image\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"analisisProductType\",\"source\":\"analisisProductType\",\"type\":\"string | number\"}]},\"name\":\"analisisSource\"},\"analisisImageName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"4pltbblktmd\",\"x-decorator-props\":{},\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.analisisSource == 2}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"analisisSource\",\"source\":\"analisisSource\",\"type\":\"string | number\"}]},\"name\":\"analisisImageName\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"镜像名称\",\"x-index\":3,\"required\":true}},\"x-designable-id\":\"wcqe6eagkke\"}}]', '{\"name\":\"productAnalisis\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"analisisProductType\"},\"key\":\"analisisProductType\"},{\"value\":{\"isLiteral\":true,\"value\":\"analisisFile\"},\"key\":\"analisisFile\"},{\"value\":{\"isLiteral\":true,\"value\":\"analisisSource\"},\"key\":\"analisisSource\"},{\"value\":{\"isLiteral\":true,\"value\":\"analisisImageName\"},\"key\":\"analisisImageName\"}],\"stepFunc\":\"productAnalisis\"}', NULL, '制品扫描', 1, 0, '2023-09-13 18:37:30', '2024-02-04 18:15:04', 1, 1, 'productAnalisis', '0', '2', '2', 'def call(def map){\n    call(map.stepName,map.analisisProductType,map.analisisFile,map.analisisSource,map.analisisImageName)\n    echo env.endString\n}\n\ndef call(String stepName, String productType, String path, String imageSource, String imageName){\n    \n    if(productType == \'file\'){\n        command = \"hawkeye-linux scan \"\n        target = path\n    }else {\n        command = \"hawkeye-linux image \"\n        if(imageSource == \'1\'){\n            imageName = \"${env.harborUrl}/${env.imageName}:${env.tagert}\"\n        }else{\n            array = imageName.split(\'/\')\n            if(array.size() >= 3) {\n                harborUrl = array[0]\n                withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n                    retry(3) {\n                        sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n                    }\n                }\n            }\n        }\n        sh \"docker pull ${imageName}\"\n        target = imageName\n    }\n    env.TRIVY_SKIP_DB_UPDATE=true\n    env.TRIVY_SKIP_JAVA_DB_UPDATE=true\n    env.MAVEN_CENTRAL_URL=\"${env.trustworthySvcUrl}/dp/query\"\n    env.TRIVY_SERVER=\"http://trivy:4954\"\n    sh \"\"\"\n    ${command} ${target} -r ${env.trustworthySvcUrl}\n    \"\"\"\n    \n}', '2', 'v1', '0', '');
