 = $observable({\\n  productType: \\\"\\\",\\n})\\n$effect(() => {\\n  if ($deps.productType == \'docker\') {\\n    if (state.productType == \\\"\\\") {\\n      state.productType = \\\"1\\\"\\n    } else {\\n      $self.value = \\\"\\\"\\n    }\\n    $self.loading = true\\n    const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/provider/sitRepository/repository/listAll?format=docker&kind=3`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k.id,\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.productType])\\n\",\"state\":{\"visible\":\"{{!!!$deps.zpjjsc_btn_1 && $deps.productType === \'docker\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"productType\",\"source\":\"productType\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"zpjjsc_btn_1\",\"source\":\"zpjjsc_dev1.zpjjsc_dev1_1.zpjjsc_btn_1\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"来源docker仓库\",\"x-index\":2,\"required\":true},\"startParamName_preDockerRepository\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"nkmm6t94l1i\",\"x-decorator-props\":{},\"name\":\"startParamName_preDockerRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"\",\"state\":{\"visible\":\"{{!!$deps.zpjjsc_btn_1 && $deps.productType === \'docker\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"productType\",\"source\":\"productTyp