INSERT INTO `devops_jenkinsfile_stage_component` VALUES (303, 1004, '通用制品上传', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"startParamName_rawRepository\":{\"x-component\":\"Select\",\"x-designable-id\":\"i2ooohyxuuq\",\"x-decorator-props\":{\"tooltip\":\"数据来源:制品仓库的通用制品仓库\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"制品仓库\",\"x-index\":0,\"required\":true,\"default\":\"${rawRepository}\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"startParamName_rawRepository\",\"x-pattern\":\"disabled\"},\"startParamName_version\":{\"x-component\":\"Input\",\"x-designable-id\":\"m06fxpk9fu5\",\"x-decorator-props\":{\"tooltip\":\"制品上传到仓库的路径\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"制品版本\",\"x-index\":1,\"required\":true,\"default\":\"${version}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_version\",\"x-pattern\":\"disabled\"},\"file\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"48fdybdzgbl\",\"x-decorator-props\":{\"tooltip\":\"支持正则表达式，例如target/*.jar，仅能上传一个制品\"},\"name\":\"file\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"上传文件\",\"x-index\":2,\"required\":true},\"productName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"jqi5ool1xff\",\"x-decorator-props\":{\"tooltip\":\"按照命名规则生成新名称覆盖上传制品名称，便于规范管理制品。命名规则：子系统编码_版本号\"},\"name\":\"productName\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{sessionStorage.getItem(\'subSystemId\') !== \'null\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"editable\",\"x-validator\":[],\"x-component-props\":{\"placeholder\":\"${子系统编码}_${版本号}\"},\"type\":\"string\",\"title\":\"制品重命名\",\"x-index\":3}},\"x-designable-id\":\"ij2b0l3x1xi\"}}]', '{\"name\":\"universalProductUpload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_rawRepository\"},\"key\":\"startParamName_rawRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_version\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"file\"},\"key\":\"file\"},{\"value\":{\"isLiteral\":true,\"value\":\"productName\"},\"key\":\"productName\"}],\"stepFunc\":\"universalProductUpload\"}', NULL, '上传制品到通用制品库', 1, 0, '2024-02-01 17:15:50', '2024-05-21 19:24:40', 1, 1, 'universalProductUpload', '2', '2', '2', 'def call(def map){\n    universalProductUploadFun(map)\n}\n\n\ndef call(String stepName,String repoId,String version,String file,String productName) {\n    universalProductUploadFun(stepName,repoId,version,file,productName)\n}', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (304, 1004, '通用制品下载', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"startParamName_rawRepository\":{\"x-component\":\"Select\",\"x-designable-id\":\"4dpe79wdgh9\",\"x-decorator-props\":{\"tooltip\":\"\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"制品仓库\",\"x-index\":0,\"required\":true,\"default\":\"${rawRepository}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_rawRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"startParamName_version\":{\"x-component\":\"Input\",\"x-designable-id\":\"6ucxhhxar6m\",\"x-decorator-props\":{\"tooltip\":\"  制品在仓库中的存储目录\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"制品版本\",\"x-index\":1,\"required\":true,\"default\":\"${version}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_version\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(()=>{\\n  if(sessionStorage.getItem(\\\"subSystemId\\\") !== \'null\'){\\n    $self.value = \'${version}\'\\n  }else{\\n    $self.value = \'${version}\'\\n  }\\n},[])\",\"state\":{}},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"startParamName_rawDeployProduct\":{\"x-component\":\"Select\",\"x-designable-id\":\"75r53o8uwsy\",\"x-decorator-props\":{\"tooltip\":\"\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"选择制品\",\"x-index\":2,\"required\":true,\"default\":\"${rawDeployProduct}\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"const state = $observable({\\n  productType: \\\"\\\",\\n})\\n$effect(() => {\\n  if ($deps.repositoryName) {\\n    $self.loading = true\\n    if (state.productType == \\\"\\\") {\\n      state.productType = \\\"1\\\"\\n    } else {\\n      $self.value = \\\"\\\"\\n    }\\n    const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n    var repoId = $deps.repositoryName\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/product/list?repoId=${repoId}`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k.version + \\\"/\\\" + k.name,\\n            label: k.version + \\\"/\\\" + k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.repositoryName])\\n\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"repositoryName\",\"source\":\"repositoryName\",\"type\":\"any\"}]},\"name\":\"startParamName_rawDeployProduct\",\"x-pattern\":\"disabled\"}},\"x-designable-id\":\"4yyxc1z8fjr\"}}]', '{\"name\":\"productDownload\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_rawRepository\"},\"key\":\"startParamName_rawRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_version\"},\"key\":\"startParamName_version\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_rawDeployProduct\"},\"key\":\"startParamName_rawDeployProduct\"}],\"stepFunc\":\"productDownload\"}', NULL, '从通用制品库下载制品', 1, 0, '2024-02-01 17:06:37', '2024-12-27 11:40:40', 1, 1, 'productDownload', '2', '2', '2', 'def call(def map){\n    productDownloadFun(map)\n}\n\ndef call(String stepName,String repoId,String version,String deployProduct){\n    productDownloadFun(stepName,repoId,version,deployProduct)\n}', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (305, 1005, 'kubernetes命令', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"deployEnv\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"l0wxu932ssu\",\"x-decorator-props\":{\"tooltip\":\"数据来源：平台部署环境管理\"},\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  // $self.value = \\\"\\\"\\n  var systemId = sessionStorage.getItem(\\\"systemId\\\")\\n  fetch(`${window.location.origin}/api//efficiency/deploy/env?systemId=${systemId}`, {\\n    headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.records.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"\\\",\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"deployEnv\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"部署环境\",\"x-index\":0,\"required\":true},\"$$deployCluster\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"1f9hek5b42a\",\"x-decorator-props\":{\"tooltip\":\"数据来源：部署环境资源管理\"},\"name\":\"$$deployCluster\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.deployEnv) {\\n    $self.loading = true\\n    const org = localStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n    var orgId = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n   // $self.value = \\\"\\\"\\n    fetch(\\n      `${window.location.origin}/api/efficiency/deploy/host/listAll?envId=${$deps.deployEnv}&type=4`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId,Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"\\\",\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.deployEnv])\\n\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployEnv\",\"source\":\"deployEnv\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"集群\",\"x-index\":1,\"required\":true},\"command\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"24r7ghj67sw\",\"x-decorator-props\":{},\"name\":\"command\",\"x-validator\":[],\"x-component-props\":{\"style\":{\"height\":\"200px\"}},\"type\":\"string\",\"title\":\"kubectl命令\",\"x-index\":2,\"required\":true}},\"x-designable-id\":\"iv5uy5892yy\"}}]', '{\"name\":\"kubernetesCommand\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployEnv\"},\"key\":\"deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"$$deployCluster\"},\"key\":\"$$deployCluster\"},{\"value\":{\"isLiteral\":true,\"value\":\"command\"},\"key\":\"command\"}],\"stepFunc\":\"kubernetesCommand\"}', NULL, '在kubernetes集群上执行命令', 1, 1, '2023-06-14 14:40:39', '2024-02-01 16:55:26', 1, 1, 'kubernetesCommand', '0', '2', '2', 'def call(String stepName,String envId,String clusterId,String command){\n    if(env.clusterId){\n        clusterId = env.clusterId\n    }else{\n        echo \"参数clusterId丢失\"\n    }\n    if(env.namespace){\n        namespace = env.namespace\n    }else{\n        echo \"参数namespace丢失\"\n    }\n\n   def response = sh returnStdout: true ,script:\"\"\"\n    curl -X GET \"${env.pipelineSvcUrl}/deploy/cluster/${clusterId}/token\" -H \"accept: */*\"\n    \"\"\"\n    def resData = readJSON text: \"\"\"${response}\"\"\"\n    def token = resData.data[0].token.trim();\n    if(token.startsWith(\"apiVersion\")){\n        writeFile encoding: \"utf-8\", file: \"kubeconfig\", text: \"\"\"${token}\"\"\"\n        sh \"\"\"\n        rm -rf /root/.kube/config\n        mv kubeconfig /root/.kube/config\n        \"\"\"\n    }else{\n        sh \"\"\"\n        kubectl config set-cluster kubernetes --server=https://${resData.data[0].ip}:${resData.data[0].port} --insecure-skip-tls-verify=true\n        set +x\n        kubectl config set-credentials admin --token=${token}\n        set -x\n        kubectl config set-context dev --cluster=kubernetes --user=admin\n        kubectl config use-context dev\n         \"\"\"\n\n    }\n    sh \"\"\"\n        chmod g-rw ~/.kube/config\n        chmod o-r ~/.kube/config\n    \"\"\"\n\n    sh \"\"\"\n    ${command}\n    \"\"\"\n    echo \"-----------------------------------子步骤分隔线----------------------------------------------------\"\n}', '0', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (306, 1002, '镜像构建（子系统）', '[{\"form\":{\"wrapperCol\":12,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"startParamName_dockerRepository\":{\"x-component\":\"Select\",\"x-designable-id\":\"n5ywvi2b3yi\",\"x-decorator-props\":{\"tooltip\":\"数据来源：平台制品仓库的docker仓库\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"镜像仓库\",\"x-index\":0,\"required\":true,\"default\":\"${dockerRepository}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_dockerRepository\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"imageName\":{\"x-component\":\"Input\",\"x-designable-id\":\"9d6nrjboove\",\"x-decorator-props\":{\"tooltip\":\"镜像名称不能有大写，空格等字符\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"镜像名称\",\"x-index\":1,\"required\":false,\"x-decorator\":\"FormItem\",\"name\":\"imageName\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n\\n  // $self.value = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  var subSystemId = window.sessionStorage.getItem(\\\"subSystemId\\\")\\n  fetch(\\n    `${window.location.origin}/api/cloud/subSystem/getById/${subSystemId}`,\\n    {\\n      headers: { Authorization: token },\\n    }\\n  )\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        $self.value = data.subCode.toLowerCase()\\n        $self.loading = false\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"dockerfile\":{\"x-component\":\"Input\",\"x-designable-id\":\"qorm04hiij6\",\"x-decorator-props\":{\"tooltip\":\"镜像打包文件的相对路径\"},\"description\":\"\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"Dockerfile\",\"x-index\":2,\"required\":true,\"default\":\"Dockerfile\",\"x-decorator\":\"FormItem\",\"name\":\"dockerfile\"},\"platform\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"9fgf2o8tdei\",\"x-decorator-props\":{\"tooltip\":\"支持arm64和amd平台\",\"addonBefore\":\"\"},\"name\":\"platform\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"平台\",\"x-index\":3,\"required\":true,\"enum\":[{\"children\":[],\"label\":\"amd64\",\"value\":\"amd64\"},{\"children\":[],\"label\":\"arm64\",\"value\":\"arm64\"}]},\"version\":{\"x-component\":\"Input\",\"x-designable-id\":\"52v27r0372n\",\"x-decorator-props\":{\"tooltip\":\"自动生成镜像标签，命名规则：版本号_打包时间戳。版本号会设置为流水线启动变量，运行流水线时可以选择版本\"},\"x-validator\":[],\"x-component-props\":{\"placeholder\":\"${版本号}_${时间戳}\"},\"type\":\"string\",\"title\":\"镜像标签\",\"x-index\":4,\"required\":false,\"default\":\"${version}_${date}\",\"x-decorator\":\"FormItem\",\"name\":\"version\",\"x-reactions\":{\"fulfill\":{\"state\":{}},\"dependencies\":[]},\"x-pattern\":\"disabled\"}},\"x-designable-id\":\"3t8z73jk3gj\"}}]', '{\"name\":\"subSystemImageBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_dockerRepository\"},\"key\":\"startParamName_dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"imageName\"},\"key\":\"imageName\"},{\"value\":{\"isLiteral\":true,\"value\":\"dockerfile\"},\"key\":\"dockerfile\"},{\"value\":{\"isLiteral\":true,\"value\":\"platform\"},\"key\":\"platform\"},{\"value\":{\"isLiteral\":true,\"value\":\"version\"},\"key\":\"version\"}],\"stepFunc\":\"subSystemImageBuild\"}', NULL, '镜像构建（子系统）', 1, 1, '2023-06-16 15:47:57', '2024-02-01 16:35:31', 1, 1, 'subSystemImageBuild', '2', '2', '2', '\ndef call(def map){\n    \n    def dockerRepository = map.startParamName_dockerRepository\n    echo \"repoId: ${dockerRepository}\"\n    def version = env.version\n    env.imageVersion = version\n    version = version + \"_\" + env.date\n    call(map.stepName,dockerRepository,map.imageName,map.dockerfile,map.platform,version)\n    echo env.endString\n\n}\n\ndef call(String stepName,String repoId,String imageName,String dockerfile,String platform,String version){\n     \n    def result = sh returnStdout: true ,script: \"\"\"\n    curl -X GET \"${env.repositorySvcUrl}/api/repository/detail?id=${repoId}\" -H \"accept: */*\" -d \"\"\n    \"\"\"\n    echo \"${result}\"\n    def resData = readJSON text: \"\"\"${result}\"\"\"\n    if(resData.code != 0){\n        error \"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\"\n    }\n    def repoUrl = resData.data.url.replace(\"https://\",\"\").replace(\"http://\",\'\')\n        \n  \n    \n    if(!fileExists(dockerfile)){\n        def language= env.language\n        println(\"-------------\"+language)\n        if(language == \'java8\' ||  language == \'java\'){\n            if(env.packageType == \'war\'){\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:8\nWORKDIR /app\nCOPY target/*.war ./app.war\n\"\"\"\n            }else {\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:8\nWORKDIR /app\nCOPY target/*.jar ./app.jar\nENTRYPOINT [\"java\", \"-jar\",\"/app/app.jar\"]\n\"\"\"\n            }\n        }else if(language == \'java11\'){\n            if(env.packageType == \'war\'){\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:11\nWORKDIR /app\nCOPY target/*.war ./app.war\n\"\"\"\n            }else {\n                writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM openjdk:11\nWORKDIR /app\nCOPY target/*.jar ./app.jar\nENTRYPOINT [\"java\", \"-jar\",\"/app/app.jar\"]\n\"\"\"\n            }\n        }else if(language == \'node14\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM node:14.16\nWORKDIR /app\nCOPY dist/ ./dist/\nENTRYPOINT npm run entrypoint\n\"\"\"\n        }else if(language == \'net5\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM mcr.microsoft.com/dotnet/runtime:3.1.31-buster-slim\nWORKDIR /app\nCOPY app/build/ ./\nENTRYPOINT [\"dotnet\", \"dotnetWebDemo.dll\"]\n\"\"\"\n        }else if(language == \'php7\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM php:7.4.33-cli-bullseye\nWORKDIR /app\nCOPY ./ ./\nRUN composer install\nCMD [\"php\", \"-S 0.0.0.0:80\", \"-t ./\"]\n\"\"\"\n        }else if(language == \'golang1.19\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM golang:1.19-bullseye\nUSER root\nWORKDIR /home/go\nCOPY ./ ./\nENTRYPOINT [\"./go-app\"]\n\"\"\"\n        }else if(language == \'python3\'){\n            writeFile encoding: \'utf-8\', file: \'Dockerfile\', text: \"\"\"FROM python:3.8-bullseye\nUSER root\nWORKDIR /home/python\nCOPY dist/ ./dist/\n\"\"\"\n        }else{\n            error \"error\"\n        }\n    }\n    incall(repoId,repoUrl,imageName,dockerfile,platform,version)\n}\n// 该方法是给脚本调用使用的\ndef incall(String harborRepoId,String harborUrl,String imageName,String dockerfile,String platform,String version){\n    if(platform == \'arm64\'){\n      sh \"\"\"\n      export DOCKER_HOST=tcp://10.10.102.93:2375\n      docker buildx build --platform linux/arm64 -f ${dockerfile} -t ${harborUrl}/${imageName}:${version} . --load \n      \"\"\"\n    }else{\n      sh \"docker build -f ${dockerfile} -t ${harborUrl}/${imageName}:${version} .\"\n    }\n\n    withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n         retry(3) {\n            sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n         }\n\n    }\n    retry(3) {\n        if(platform == \'arm64\'){\n              sh \"\"\"\n              export DOCKER_HOST=tcp://10.10.102.93:2375\n              docker push ${harborUrl}/${imageName}:${version}\n              \"\"\"\n        }else{\n            sh \"docker push ${harborUrl}/${imageName}:${version}\"\n        }\n\n    }\n\n    if(platform == \'arm64\'){\n        sh \"\"\"\n        export DOCKER_HOST=tcp://10.10.102.93:2375\n        docker rmi -f ${harborUrl}/${imageName}:${version}\n        \"\"\"\n    }else{\n        sh \"docker rmi -f ${harborUrl}/${imageName}:${version}\"\n    }\n    \n    result = sh returnStdout: true ,script: \"\"\"\n    curl -X GET \"${env.codeInspectSvcUrl}/scanTasks/scanInfo/byBuildId?buildId=${env.buildId}\" -H \"accept: */*\" -d \"\"\n    \"\"\"\n    def resData = readJSON text: \"\"\"${result}\"\"\"\n    if(resData.code != 0){\n        error \"调用代码扫描服务查询扫描结果报错，报错信息：${resData.msg}\"\n    }\n    historyOpt = \'\'\n    if(env.soanrWaitGate || (resData.data.status != 3 && resData.data.histories.size() == 1)){\n        for(item in resData.data.histories){\n            historyOpt += \"-F \'historyId =${item.historyId}\' -F \'sonarResult =${item.status}\' \"\n        }\n    }\n\n    imageProjectName = harborUrl.split(\"/\")[1]\n    def systemOpt = \'\'\n    if(env.systemId){\n        systemOpt = \"-F \'subsystemId=${env.subsystemId}\' -F \'systemId=${env.systemId}\'\"\n    }\n    def gitInfoOpt = \'\'\n    if(env.mergeBranch){\n       gitInfoOpt = \" -F \'mergeBranch=${env.mergeBranch}\' -F \'commitId=${env.mergeCommitId}\' -F \'serverId=${env.mergeServerId}\' -F \'gitlabId=${env.mergeGitlabId}\' \" \n    }\n    result = sh returnStdout: true ,script: \"\"\"\n     curl -X POST \'${env.repositorySvcUrl}/api/provider/product/upload/container\' -H  \'accept: */*\' -H  \'Content-Type: multipart/form-data\' \\\n     -F \'jobId=${params.job_id}\' -F \'buildId=${env.buildId}\'  -F \'jobName=${env.JOB_NAME}\' -F \'repositoryName=${imageProjectName}\'\\\n     -F \'productName=${imageName}\' -F \'version=${env.imageVersion}\' -F \'versionTimestamp=${env.date}\' ${gitInfoOpt} ${historyOpt} -F \'repositoryId=${harborRepoId}\'  ${systemOpt}  -F \'userId=${env.runUserId}\'\n    \"\"\"\n    echo \"${result}\"\n    resData = readJSON text: \"\"\"${result}\"\"\"\n    if(resData.code != 0){\n        error \"上传元通用制品元数据失败\"\n    }\n    echo \"上传制品：${resData.data.id}\"\n    env.dockerDeployProduct = resData.data.id\n    env.harborUrl = harborUrl\n    env.imageName = imageName\n    env.tagert =  version\n    env.productUploadStepFlag = true\n}', '0', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (307, 1005, 'Kubernetes部署', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"startParamName_deployEnv\":{\"x-component\":\"Select\",\"x-designable-id\":\"l0wxu932ssu\",\"x-decorator-props\":{\"tooltip\":\"环境在 持续交付或系统下的部署环境菜单中配置。在环境下添加集群、命名空间后才能用于发布\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"部署环境\",\"x-index\":0,\"required\":true,\"default\":\"${deployEnv}\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"name\":\"startParamName_deployEnv\",\"x-pattern\":\"disabled\"},\"startParamName_deployCluster\":{\"x-component\":\"Select\",\"x-designable-id\":\"1f9hek5b42a\",\"x-decorator-props\":{\"tooltip\":\"命名空间在yaml配置文件中设置\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"集群\",\"x-index\":1,\"required\":true,\"default\":\"${deployCluster}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_deployCluster\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployEnv\",\"source\":\"deployEnv\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"deployPath\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"haru4qlxonf\",\"x-decorator-props\":{\"tooltip\":\"输入yaml配置所在文件夹的相对路径\"},\"name\":\"deployPath\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"yaml文件路径\",\"x-index\":2,\"required\":true}},\"x-designable-id\":\"q6cbj2k29mp\"}}]', '{\"name\":\"k8sDeploy\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployEnv\"},\"key\":\"startParamName_deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployCluster\"},\"key\":\"startParamName_deployCluster\"},{\"value\":{\"isLiteral\":true,\"value\":\"deployPath\"},\"key\":\"deployPath\"}],\"stepFunc\":\"k8sDeploy\"}', '', '基于 yaml 文件向 Kubernetes 集群部署应用', 1, 0, '2022-03-21 15:16:37', '2024-02-23 11:39:33', NULL, 1, 'k8sDeploy', '2', '2', '2', 'def call(def map){\n    k8sDeployFun(map.stepName,map.startParamName_deployEnv,map.startParamName_deployCluster,map.deployPath)\n}\n\n\ndef call(String stepName,String envId,String clusterId,String path){\n    k8sDeployFun(stepName,envId,clusterId,path)\n}\n\n\ndef call(String stepName,Integer envId,Integer clusterId,String path){\n   call(stepName,\"${envId}\",\"${clusterId}\",path)\n}\n', '2', '', '0', '');
INSERT INTO `devops_jenkinsfile_stage_component` VALUES (308, 1005, 'Helm部署', '[{\"form\":{\"layout\":\"vertical\",\"wrapperCol\":12,\"colon\":false,\"labelCol\":6},\"schema\":{\"type\":\"object\",\"properties\":{\"release\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Input\",\"x-designable-id\":\"d1j99zl47qy\",\"x-decorator-props\":{},\"name\":\"release\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"Release名称\",\"x-index\":0,\"required\":true},\"startParamName_deployEnv\":{\"x-component\":\"Select\",\"x-designable-id\":\"easga8o7hur\",\"x-decorator-props\":{\"tooltip\":\"环境在 持续交付或系统下的部署环境菜单中配置。在环境下添加集群、命名空间后才能用于发布\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"部署环境\",\"x-index\":1,\"required\":true,\"default\":\"${deployEnv}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_deployEnv\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"startParamName_deployCluster\":{\"x-component\":\"Select\",\"x-designable-id\":\"485s3exahlx\",\"x-decorator-props\":{\"tooltip\":\"\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"k8s集群\",\"x-index\":2,\"required\":true,\"default\":\"${deployCluster}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_deployCluster\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployEnv\",\"source\":\"deployEnv\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"startParamName_namespace\":{\"x-component\":\"Select\",\"x-designable-id\":\"56pfharefx1\",\"x-decorator-props\":{\"tooltip\":\"更新应用所在命名空间，可在部署环境资源管理中配置\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"命名空间\",\"x-index\":3,\"required\":true,\"default\":\"${namespace}\",\"x-decorator\":\"FormItem\",\"name\":\"startParamName_namespace\",\"x-reactions\":{\"fulfill\":{\"run\":\"\"},\"dependencies\":[{\"property\":\"value\",\"name\":\"deployCluster\",\"source\":\"deployCluster\",\"type\":\"any\"}]},\"x-pattern\":\"disabled\"},\"chartType\":{\"default\":\"1\",\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"avpejaofm0e\",\"x-decorator-props\":{\"tooltip\":\"支持项目路径和chart库\"},\"name\":\"chartType\",\"x-validator\":[],\"x-component-props\":{},\"title\":\"chart来源\",\"x-index\":4,\"required\":true,\"enum\":[{\"children\":[],\"label\":\"helm仓库\",\"value\":\"2\"},{\"children\":[],\"label\":\"项目路径\",\"value\":\"1\"}]},\"chartPath\":{\"x-component\":\"Input\",\"x-designable-id\":\"8gbgijtbhz0\",\"x-decorator-props\":{},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"chart路径\",\"x-index\":5,\"required\":true,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"chartPath\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.chartType === \'1\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"chartType\",\"source\":\"chartType\",\"type\":\"any\"}]}},\"valuesPath\":{\"x-component\":\"Input\",\"x-designable-id\":\"4oeq13bpsiy\",\"x-decorator-props\":{\"tooltip\":\"填写values.yaml在Chart目录下的路径,默认使用values.yaml\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"values文件\",\"x-index\":6,\"required\":true,\"default\":\"values.yaml\",\"x-decorator\":\"FormItem\",\"name\":\"valuesPath\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.chartType === \'1\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"chartType\",\"source\":\"chartType\",\"type\":\"any\"}]}},\"chartRepoName\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"kx3rsgmv4eb\",\"x-decorator-props\":{},\"name\":\"chartRepoName\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  fetch(`${window.location.origin}/api/warehouse/api/repository/helm`, {\\n    headers: { Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.id + \\\"|\\\" + k.name,\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\",\"state\":{\"visible\":\"{{$deps.chartType !== \'1\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"chartType\",\"source\":\"chartType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{\"labelInValue\":false},\"title\":\"选择仓库\",\"x-index\":7,\"required\":true},\"chart\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"jjy2pl74j5f\",\"x-decorator-props\":{},\"name\":\"chart\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.chartRepoName) {\\n    $self.loading = true\\n    var repo = $deps.chartRepoName.split(\\\"|\\\")[0]\\n    // $self.value = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/product/package/list?id=${repo}`,\\n      {\\n        headers: { Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.records.map((k) => ({\\n            ...k,\\n            value: k.packageName,\\n            label: k.packageName,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.chartRepoName])\\n\",\"state\":{\"visible\":\"{{$deps.chartType !== \'1\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"chartRepoName\",\"source\":\"chartRepoName\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"chartType\",\"source\":\"chartType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"选择Chart包\",\"x-index\":8,\"required\":true},\"chartVersion\":{\"x-decorator\":\"FormItem\",\"x-component\":\"Select\",\"x-designable-id\":\"tfrbu1qbks1\",\"x-decorator-props\":{},\"name\":\"chartVersion\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.chartRepoName && $deps.chart) {\\n    var repo = $deps.chartRepoName.split(\\\"|\\\")[0]\\n    $self.loading = true\\n    // $self.value = \\\"\\\"\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/product/package/list?id=${repo}&packageName=${$deps.chart}`,\\n      {\\n        headers: { Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re =\\n            data.records[0]?.versions?.map((k) => ({\\n              ...k,\\n              value: k.id,\\n              label: k.version,\\n            })) || []\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.chartRepoName, $deps.chart])\\n\",\"state\":{\"visible\":\"{{$deps.chartType !== \'1\'}}\"}},\"dependencies\":[{\"property\":\"value\",\"name\":\"chartRepoName\",\"source\":\"chartRepoName\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"chart\",\"source\":\"chart\",\"type\":\"any\"},{\"property\":\"value\",\"name\":\"chartType\",\"source\":\"chartType\",\"type\":\"any\"}]},\"x-validator\":[],\"x-component-props\":{},\"title\":\"选择版本\",\"x-index\":9,\"required\":true},\"setValue\":{\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"jidxqwu4i2i\",\"x-decorator-props\":{\"tooltip\":\"部署时，会将value值和chart包中的value值合并，相同项优先使用此处value设置;value中支持环境变量\"},\"description\":\"格式：key1=value1,key2=value2,key3=value3\",\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"设置Values \",\"x-index\":10,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"setValue\",\"x-reactions\":{\"fulfill\":{\"state\":{}},\"dependencies\":[{\"property\":\"value\",\"name\":\"sourceType\",\"source\":\"sourceType\",\"type\":\"any\"}]}}},\"x-designable-id\":\"9ewefezaz7w\"}}]', '{\"name\":\"helmDeploy\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"stepName\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"release\"},\"key\":\"release\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployEnv\"},\"key\":\"startParamName_deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_deployCluster\"},\"key\":\"startParamName_deployCluster\"},{\"value\":{\"isLiteral\":true,\"value\":\"startParamName_namespace\"},\"key\":\"startParamName_namespace\"},{\"value\":{\"isLiteral\":true,\"value\":\"chartType\"},\"key\":\"chartType\"},{\"value\":{\"isLiteral\":true,\"value\":\"chartPath\"},\"key\":\"chartPath\"},{\"value\":{\"isLiteral\":true,\"value\":\"valuesPath\"},\"key\":\"valuesPath\"},{\"value\":{\"isLiteral\":true,\"value\":\"chartRepoName\"},\"key\":\"chartRepoName\"},{\"value\":{\"isLiteral\":true,\"value\":\"chart\"},\"key\":\"chart\"},{\"value\":{\"isLiteral\":true,\"value\":\"chartVersion\"},\"key\":\"chartVersion\"},{\"value\":{\"isLiteral\":true,\"value\":\"setValue\"},\"key\":\"setValue\"}],\"stepFunc\":\"helmDeploy\"}', NULL, '使用Helm Chart 部署 Release 到Kubernetes 集群', 1, 0, '2022-05-31 06:43:25', '2024-02-23 11:37:26', NULL, 1, 'helmDeploy', '2', '2', '2', 'def call(def map){\n    helmDeployFun(map)\n}\n\ndef call(String stepName,String release,String deployEnv,String clusterId,String namespace,String sourceType,String chartPath,String valuesPath,String chartRepoName,String chart,String version,String values){\n    helmDeployFun(stepName,release,deployEnv,clusterId,namespace,sourceType,chartPath,valuesPath,chartRepoName,chart,version,values)\n}', '2', '', '0', '');
