INSERT INTO `devops_jenkinsfile_template` VALUES (2, 'Java+ Docker', '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    imagePullPolicy: IfNotPresent\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: IfNotPresent\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"branches\":[{\"steps\":[{\"stepName\":\"代码克隆\",\"name\":\"gitClone\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码克隆\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"1\"},\"key\":\"serviceType\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"gitUrl\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"gitCredentialId\"},{\"value\":{\"isLiteral\":true,\"value\":\"1\"},\"key\":\"serverId\"},{\"value\":{\"isLiteral\":true,\"value\":\"18|http://10.10.103.230:32480/devops-config/ceshimiaoshu.git\"},\"key\":\"gitlabId\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"branch\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${branch}\\\"\"},\"key\":\"startParamName_branch\"},{\"value\":{\"isLiteral\":true,\"value\":\"选择已有\"},\"key\":\"dmkl_btn1\"},{\"value\":{\"isLiteral\":true,\"value\":true},\"key\":\"dmkl_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"gitPath\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码克隆\"},\"key\":\"stageName\"}],\"name\":\"代码克隆\"},{\"branches\":[{\"steps\":[{\"stepName\":\"代码构建\",\"name\":\"codeBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码构建\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"java8\"},\"key\":\"language\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven3.5\"},\"key\":\"buildTool\"},{\"value\":{\"isLiteral\":true,\"value\":\"mvn clean package\\n\"},\"key\":\"command\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码构建\"},\"key\":\"stageName\"}],\"name\":\"代码构建\"},{\"branches\":[{\"steps\":[{\"stepName\":\"单元测试\",\"name\":\"shCommand\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"单元测试\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"mvn test\"},\"key\":\"shCommand\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"单元测试\"},\"key\":\"stageName\"}],\"name\":\"单元测试\"},{\"branches\":[{\"steps\":[{\"stepName\":\"镜像构建\",\"name\":\"imageBuild\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"镜像构建\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${dockerRepository}\\\"\"},\"key\":\"startParamName_dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"设置为定值\"},\"key\":\"jxgj_btn1\"},{\"value\":{\"isLiteral\":true,\"value\":true},\"key\":\"jxgj_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"Dockerfile\"},\"key\":\"dockerfile\"},{\"value\":{\"isLiteral\":true,\"value\":\"amd64\"},\"key\":\"platform\"},{\"value\":{\"isLiteral\":true,\"value\":\"app\"},\"key\":\"imageName\"},{\"value\":{\"isLiteral\":true,\"value\":\"defin\"},\"key\":\"tagType\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${tag}\\\"\"},\"key\":\"params_tag\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"构建Docker镜像\"},\"key\":\"stageName\"}],\"name\":\"构建Docker镜像\"},{\"branches\":[{\"steps\":[{\"stepName\":\"镜像更新\",\"name\":\"k8sApplicationDeployFun_v1\",\"arguments\":[{\"value\":{\"isLiteral\":true,\"value\":\"镜像更新\"},\"key\":\"stepName\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"deployEnv\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${deployEnv}\\\"\"},\"key\":\"startParamName_deployEnv\"},{\"value\":{\"isLiteral\":true,\"value\":\"选择已有\"},\"key\":\"k8sjxgx_btn1\"},{\"value\":{\"isLiteral\":true,\"value\":true},\"key\":\"k8sjxgx_btn_1\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"deployCluster\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${deployCluster}\\\"\"},\"key\":\"startParamName_deployCluster\"},{\"value\":{\"isLiteral\":true,\"value\":\"选择已有\"},\"key\":\"k8sjxgx_btn2\"},{\"value\":{\"isLiteral\":true,\"value\":true},\"key\":\"k8sjxgx_btn_2\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"namespace\"},{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${namespace}\\\"\"},\"key\":\"startParamName_namespace\"},{\"value\":{\"isLiteral\":true,\"value\":\"选择已有\"},\"key\":\"k8sjxgx_btn3\"},{\"value\":{\"isLiteral\":true,\"value\":true},\"key\":\"k8sjxgx_btn_3\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"deployName\"},{\"value\":{\"isLiteral\":true,\"value\":\"1\"},\"key\":\"imageSource\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"startParamName_dockerRepository\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"k8sjxgx_btn4\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"k8sjxgx_btn_4\"},{\"value\":{\"isLiteral\":true,\"value\":\"\"},\"key\":\"version\"},