Id: \'1\', gitlabId: \'18|http://10.10.103.230:32480/devops-config/ceshimiaoshu.git\', branch: \'\', startParamName_branch: \"${branch}\", dmkl_btn1: \'选择已有\', dmkl_btn_1: true, gitPath: \'\')\n      }\n    }\n\n    stage(\'代码构建\') {\n      environment {\n        stageName = \'代码构建\'\n      }\n      steps {\n        codeBuild(stepName: \'代码构建\', language: \'java8\', buildTool: \'maven3.5\', command: \'\'\'mvn clean package\n\'\'\')\n      }\n    }\n\n    stage(\'单元测试\') {\n      environment {\n        stageName = \'单元测试\'\n      }\n      steps {\n        shCommand(stepName: \'单元测试\', shCommand: \'mvn test\')\n      }\n    }\n\n    stage(\'构建Docker镜像\') {\n      environment {\n        stageName = \'构建Docker镜像\'\n      }\n      steps {\n        imageBuild(stepName: \'镜像构建\', startParamName_dockerRepository: \"${dockerRepository}\", jxgj_btn1: \'设置为定值\', jxgj_btn_1: true, dockerfile: \'Dockerfile\', platform: \'amd64\', imageName: \'app\', tagType: \'defin\', params_tag: \"${tag}\")\n      }\n    }\n\n    stage(\'部署到云端\') {\n      environment {\n        stageName = \'部署到云端\'\n      }\n      steps {\n        k8sApplicationDeployFun_v1(stepName: \'镜像更新\', deployEnv: \'\', startParamName_deployEnv: \"${deployEnv}\", k8sjxgx_btn1: \'选择已有\', k8sjxgx_btn_1: true, deployCluster: \'\', startParamName_deployCluster: \"${deployCluster}\", k8sjxgx_btn2: \'选择已有\', k8sjxgx_btn_2: true, namespace: \'\', startParamName_namespace: \"${namespace}\", k8sjxgx_btn3: \'选择已有\', k8sjxgx_btn_3: true, deployName: \'\', imageSource: \'1\', dockerRepository: \'\', startParamName_dockerRepository: \'\', k8sjxgx_btn4: \'\', k8sjxgx_btn_4: \'\', version: \'\', str_version: \'\', startParamName_version: \'\', k8sjxgx_btn5: \'\', k8sjxgx_btn_5: \'\', dockerDeployProduct: \'\', startParamName_dockerDeployProduct: \'\', k8sjxgx_btn6: \'\', k8sjxgx_btn_6: \'\')\n      }\n    }\n\n  }\n}', '[]', '[]', 0, '发布', 1, 0, '2022-06-23 15:39:34', '2024-06-26 10:55:59', NULL, 1, '该模板演示基于 Java + Docker 实现全自动检出代码 -