ch(\\n      `${window.location.origin}/api/code/api/open/codeserver/${$deps.service_id}/${project_id}/branches`,\\n      {\\n        headers: { Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re =\\n            data.content.map((k) => ({\\n              ...k,\\n              value: k.branch.name,\\n              label: k.branch.name,\\n            })) || []\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.service_id, $deps.project_id])\\n\",\"state\":{\"visible\":\"{{// !!$deps.$$ck && ( $deps.serviceType == \'1\')\\n$deps.serviceType == \'1\'\\n}}\"}},\"dependencies\":[{\"source\":\"serviceType\",\"type\":\"any\",\"property\":\"value\",\"name\":\"serviceType\"},{\"source\":\"service_id\",\"type\":\"any\",\"property\":\"value\",\"name\":\"service_id\"},{\"source\":\"project_id\",\"type\":\"any\",\"property\":\"value\",\"name\":\"project_id\"}]},\"name\":\"branch_2\"},\"90ra1sjbhwq\":{\"x-component\":\"Input\",\"x-designable-id\":\"90ra1sjbhwq\",\"x-decorator-props\":{\"fullness\":false,\"bordered\":false,\"layout\":\"horizontal\",\"labelAlign\":\"left\",\"colon\":false,\"feedbackLayout\":\"terse\",\"style\":{\"margin\":\"0px 0px 0px 0px\",\"display\":\"block\",\"fontWeight\":800,\"height\":\"40px\"}},\"x-validator\":[],\"x-component-props\":{\"bordered\":false,\"style\":{\"height\":\"0%\"}},\"type\":\"string\",\"title\":\"制品上传\",\"x-index\":17,\"default\":\"\",\"x-decorator\":\"FormItem\",\"x-pattern\":\"disabled\"},\"deployEnv\":{\"x-component\":\"Select\",\"x-designable-id\":\"owo120ib9xe\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"主机部署-环境\",\"x-index\":23,\"required\":true,\"x-decorator\":\"FormItem\",\"name\":\"deployEnv\",\"x-reactions\":{\"fulfill\":{\"run\"