   value: \\\"gradle4.10\\\",\\n    //     },\\n    //   ],\\n    // },\\n    {\\n      label: \\\"sdk\\\",\\n      value: \\\"sdk\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          label: \\\"sdk-30\\\",\\n          value: \\\"sdk-30\\\",\\n        },\\n      ],\\n    },\\n  ]\\n  $self.dataSource = treeData\\n}, [$deps.params_language])\\n\",\"state\":{\"visible\":\"{{$deps.params_language.startsWith(\\\"java\\\") || $deps.params_language.startsWith(\\\"openjdk\\\")}}\"}},\"dependencies\":[{\"source\":\"params_language\",\"type\":\"any\",\"property\":\"value\",\"name\":\"params_language\"}]},\"name\":\"params_buildTool\"},\"command2\":{\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"r8k8ml4hijf\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"构建命令\",\"x-index\":12,\"required\":true,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"command2\"},\"file\":{\"x-component\":\"Input\",\"x-designable-id\":\"scg0ka9smut\",\"x-decorator-props\":{\"tooltip\":\"包含文件路径，支持相对路径和绝对路径\",\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"上传文件\",\"x-index\":20,\"x-decorator\":\"FormItem\",\"name\":\"file\"},\"project_id\":{\"x-component\":\"Select\",\"x-designable-id\":\"t189up47dxd\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"仓库\",\"x-index\":6,\"required\":true,\"x-decorator\":\"FormItem\",\"name\":\"project_id\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.service_id) {\\n    $self.loading = true\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    var subSystemId = window.location.search\\n      .split(\\\"subSystemId=\\\")[1]\\n    var gitlabId = 0\\n    var gitlabRepo = \\\"\\\"\\n    if (subSystemId) {\\n      subSystemId = subSystemId.split(\\\"&\\\")[0]\\n      fetch(\\n        `${window.location.origin}/api/cloud/open/pipeline/getSubSystemById?subSystemId=${subSystemId}`,\\n        {\\n          headers: { Authorization: token },\\n        }\\n      )\\n        .then((response) => response.json())\\n        .then(\\n          ({ data }) => {\\n            gitlabId = data.gitlabId\\n            gitlabRepo = data.gitlabRepo\\n            fetch(\\n              `${window.location.origin}/api/code/api/open/codeserver/projects/list?serverId=${$deps.service_id}`,\\n              {\\n                headers: { Authorization: token },\\n              }\\n            )\\n              .then((response) => response.json())\\n              .then(\\n                ({ data }) => {\\n                  const re = data.map((k) => ({\\n                    ...k,\\n                    value: k.id + \\\"|\\\" + k.httpUrlToRepo,\\n                    label: k.name,\\n                  }))\\n                  $self.loading = false\\n                  $self.dataSource = re\\n                  $self.initialValue = gitlabId + \\\"|\\\" + gitlabRepo\\n                },\\n                () => {\\n                  //$self.loading = false\\n                }\\n              )\\n          },\\n          () => {\\n            $self.loading = false\\n          }\\n        )\\n    } else {\\n      fetch(\\n        `${window.location.origin}/api/code/api/open/codeserver/projects/list?serverId=${$deps.service_id}`,\\n        {\\n          headers: { Authorization: token },\\n        }\\n      )\\n        .then((response) => response.json())\\n        .then(\\n          ({ data }) => {\\n            const re = data.map((k) => ({\\n              ...k,\\n              value: k.id + \\\"|\\\" + k.httpUrlToRepo,\\n              label: k.name,\\n            }))\\n            $self.loading = false\\n            $self.dataSource = re\\n          },\\n          () => {\\n            $self.loading = false\\n          }\\n        )\\n    }\\n  }\\n}, [$deps.service_id])\\n\",\"state\":{\"visible\":\"{{$deps.serviceType == \'1\'}}\"}},\"dependencies\":[{\"source\":\"serviceType\",\"type\":\"any\",\"property\":\"value\",\"name\":\"serviceType\"},{\"source\":\"service_id\",\"type\":\"any\",\"property\":\"value\",\"name\":\"service_id\"}]}},\"git_repo\":{\"x-component\":\"Input\",\"x-designable-id\":\"0lq86d9jpyp\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"GIT仓库\",\"x-index\":2,\"required\":true,\"x-decorator\":\"FormItem\",\"name\":\"git_repo\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.serviceType === \'2\'}}\"}},\"dependencies\":[{\"source\":\"serviceType\",\"type\":\"any\",\"property\":\"value\",\"name\":\"serviceType\"}]}},\"service_id\":{\"x-component\":\"Select\",\"x-designable-id\":\"6v8w2psykwx\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"服务器\",\"x-index\":4,\"required\":true,\"x-decorator\":\"FormItem\",\"name\":\"service_id\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  var subSystemId = window.location.search\\n    .split(\\\"subSystemId=\\\")[1]\\n  var serverId = \\\"\\\"\\n  if (subSystemId) {\\n    subSystemId = subSystemId.split(\\\"&\\\")[0]\\n    fetch(\\n      `${window.location.origin}/api/cloud/open/pipeline/getSubSystemById?subSystemId=${subSystemId}`,\\n      {\\n        headers: { Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          serverId = data.serverId\\n          fetch(`${window.location.origin}/api/code/api/open/codeserver`, {\\n            headers: { Authorization: token },\\n          })\\n            .then((response) => response.json())\\n            .then(\\n              ({ data }) => {\\n                $self.initialValue = serverId\\n                const re = data.map((k) => ({\\n                  ...k,\\n                  value: k.id,\\n                  label: k.name,\\n                }))\\n                $self.loading = false\\n                $self.dataSource = re\\n              },\\n              () => {\\n                //$self.loading = false\\n              }\\n            )\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  } else {\\n    fetch(`${window.location.origin}/api/code/api/open/codeserver`, {\\n      headers: { Authorization: token },\\n    })\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          data.map((k) => {\\n            if (k.systemFlag == true) {\\n              $self.initialValue = k.id\\n            }\\n          })\\n          const re = data.map((k) => ({ ...k, value: k.id, label: k.name }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [])\\n\",\"state\":{\"visible\":\"{{$deps.serviceType == \'1\'}}\"}},\"dependencies\":[{\"source\":\"serviceType\",\"type\":\"any\",\"property\":\"value\",\"name\":\"serviceType\"}]}},\"8cfifqhln23\":{\"x-component\":\"Input\",\"x-designable-id\":\"8cfifqhln23\",\"x-decorator-props\":{\"fullness\":false,\"bordered\":false,\"layout\":\"horizontal\",\"labelAlign\":\"left\",\"colon\":false,\"feedbackLayout\":\"terse\",\"style\":{\"margin\":\"0px 0px 0px 0px\",\"display\":\"block\",\"fontWeight\":800,\"height\":\"40px\"}},\"x-validator\":[],\"x-component-props\":{\"bordered\":false,\"style\":{\"height\":\"0%\"}},\"type\":\"string\",\"title\":\"代码构建\",\"x-index\":9,\"default\":\"\",\"x-decorator\":\"FormItem\",\"x-pattern\":\"disabled\"},\"from\":{\"x-component\":\"Input\",\"x-designable-id\":\"lutr6cjuskf\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"des