n\\\")\\n    // $self.value = \\\"\\\"\\n    fetch(\\n      `${window.location.origin}/api/code/api/open/codeserver/branchTag?username=${$deps.user}&repositoryUrl=${$deps.git_repo}&password=${$deps.aes_password}`,\\n      {\\n        headers: { Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.map((k) => ({\\n            ...k,\\n            value: k,\\n            label: k,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {\\n          $self.loading = false\\n        }\\n      )\\n  }\\n}, [$deps.aes_password, $deps.git_repo, $deps.user])\\n\",\"state\":{\"visible\":\"{{$deps.serviceType === \'2\'}}\"}},\"dependencies\":[{\"source\":\"serviceType\",\"type\":\"any\",\"property\":\"value\",\"name\":\"serviceType\"},{\"source\":\"git_repo\",\"type\":\"any\",\"property\":\"value\",\"name\":\"git_repo\"},{\"source\":\"user\",\"type\":\"any\",\"property\":\"value\",\"name\":\"user\"},{\"source\":\"aes_password\",\"type\":\"any\",\"property\":\"value\",\"name\":\"aes_password\"}]}},\"branch_2\":{\"x-component\":\"Select\",\"x-designable-id\":\"5onh9q80qfk\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"分支\",\"x-index\":7,\"required\":true,\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.service_id && $deps.project_id) {\\n    $self.loading = true\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    // $self.value = \\\"\\\"\\n    var project_id = $deps.project_id.split(\\\"|\\\")[0]\\n    console.log(project_id)\\n    fetch(\\n      `${window.location.origin}/api/code/api/open/codeserver/${$deps.service_id}/${project_id}/branches`,\\n      {\\n        headers: { Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n 