gin\":\"0px 0px 0px 0px\",\"display\":\"block\",\"fontWeight\":800,\"height\":\"40px\"}},\"x-validator\":[],\"x-component-props\":{\"bordered\":false,\"style\":{\"height\":\"0%\"}},\"type\":\"string\",\"title\":\"依赖\",\"x-index\":9,\"default\":\"\",\"x-decorator\":\"FormItem\",\"x-pattern\":\"disabled\"},\"dependencies\":{\"x-component\":\"Input\",\"x-designable-id\":\"1n5er98ky8c\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"安装依赖\",\"x-index\":10,\"x-decorator\":\"FormItem\",\"name\":\"dependencies\"},\"proxy\":{\"x-component\":\"Input\",\"x-designable-id\":\"8s6rb4tej5k\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"仓库代理\",\"x-index\":18,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"proxy\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if ($deps.params_language.startsWith(\\\"node\\\")) {\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/repository/proxy?format=npm`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          $self.initialValue = data.repository.url\\n        },\\n        () => {}\\n      )\\n  } else if ($deps.params_language.startsWith(\\\"go\\\")) {\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/repository/proxy?format=go`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          $self.initialValue = data.repository.url\\n        },\\n        () => {}\\n      )\\n  } else if ($deps.params_language.startsWith(\\\"python\\\")) {\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/repository/proxy?format=pypi`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          $self.initialValue = data.repository.url\\n        },\\n        () => {}\\n      )\\n  }\\n}, [$deps.params_language])\\n\",\"state\":{\"visible\":\"{{$deps.params_language.startsWith(\\\"node\\\") || \\n$deps.params_language.startsWith(\\\"go\\\") || \\n$deps.params_language.startsWith(\\\"python\\\")}}\"}},\"dependencies\":[{\"source\":\"params_language\",\"type\":\"any\",\"property\":\"value\",\"name\":\"params_language\"}]}},\"file_setting\":{\"x-component\":\"Upload.Dragger\",\"x-designable-id\":\"dl2quvm4t6o\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-component-props\":{\"method\":\"POST\",\"textContent\":\"点击或拖拽文件到此区域上传\",\"maxCount\":1,\"accept\":\".xml\",\"withCredentials\":true,\"action\":\"api/application/provider/files/upload/one?bucketName=application\"},\"x-validator\":[],\"type\":\"Array<object>\",\"title\":\"setting文件上传\",\"x-index\":16,\"x-decorator\":\"FormItem\",\"name\":\"file_setting\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  var hp = `${window.location.host}`\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  $self.componentProps.headers = {\\\"Authorization\\\":token}\\n  $self.componentProps.action = `${window.location.origin}/api/application/provider/files/upload/one?bucketName=application`\\n}, [])\\n\",\"state\":{\"visible\":\"{{$deps.params_language.startsWith(\\\"java\\\")}}\"}},\"dependencies\":[{\"source\":\"params_language\",\"type\":\"any\",\"property\":\"value\",\"name\":\"params_language\"}]}},\"harborUrl\":{\"x-component\":\"Select\",\"x-designable-id\":\"phlxmkcnpag\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"镜像仓库\",\"x-index\":21,\"required\":true,\"x-decorator\":\"FormItem\",\"name\":\"harborUrl\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  $self.loading = true\\n  const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n  var orgId = \\\"\\\"\\n  var token = localStorage.getItem(\\\"userToken\\\")\\n  if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n  fetch(`${window.location.origin}/api/warehouse/api/repository/docker`, {\\n    headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n  })\\n    .then((response) => response.json())\\n    .then(\\n      ({ data }) => {\\n        const re = data.map((k) => ({\\n          ...k,\\n          value: k.url,\\n          label: k.name,\\n        }))\\n        $self.loading = false\\n        $self.dataSource = re\\n      },\\n      () => {\\n        $self.loading = false\\n      }\\n    )\\n}, [])\\n\"},\"dependencies\":[{\"type\":\"any\",\"property\":\"value\"}]}},\"tagert\":{\"x-component\":\"Input\",\"x-designable-id\":\"drtf2ffogdu\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"镜像标签\",\"x-index\":24,\"required\":true,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"tagert\",\"x-reactions\":{\"fulfill\":{\"state\":{\"visible\":\"{{$deps.tagType == \'defin\'}}\"}},\"dependencies\":[{\"source\":\"tagType\",\"type\":\"any\",\"property\":\"value\",\"name\":\"tagType\"}]}},\"params_language\":{\"x-component\":\"TreeSelect\",\"x-designable-id\":\"oqup6zl29y3\",\"x-display\":\"visible\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"语言\",\"x-index\":13,\"required\":true,\"default\":\"golang1.19\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  const treeData = [\\n    {\\n      label: \\\"java\\\",\\n      value: \\\"java\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          value: \\\"java8\\\",\\n          label: \\\"java8\\\",\\n        },\\n        {\\n          value: \\\"java11\\\",\\n          label: \\\"java11\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"openjdk\\\",\\n      value: \\\"openjdk\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          value: \\\"openjdk8\\\",\\n          label: \\\"openjdk8\\\",\\n        },\\n        {\\n          value: \\\"openjdk11\\\",\\n          label: \\\"openjdk11\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"node\\\",\\n      value: \\\"node\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          value: \\\"node14\\\",\\n          label: \\\"node14\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"dotnet\\\",\\n      value: \\\"dotnet\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          value: \\\"net5\\\",\\n          label: \\\"net5\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"python\\\",\\n      value: \\\"python\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          value: \\\"python3\\\",\\n          label: \\\"python3\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"golang\\\",\\n      value: \\\"golang\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          value: \\\"golang1.19\\\",\\n          label: \\\"golang1.19\\\",\\n        },\\n      ],\\n    },\\n    {\\n      label: \\\"php\\\",\\n      value: \\\"php\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          value: \\\"php7\\\",\\n          label: \\\"php7\\\",\\n        },\\n      ],\\n    },\\n  ]\\n  $self.dataSource = treeData\\n}, [])\\n\"},\"dependencies\":[{\"type\":\"string\",\"property\":\"value\"}]},\"name\":\"params_language\"},\"dkycbdmg8m4\":{\"x-component\":\"Input\",\"x-designable-id\":\"dkycbdmg8m4\",\"x-decorator-props\":{\"layout\":\"horizontal\",\"size\":\"small\",\"labelAlign\":\"left\",\"feedbackLayout\":\"terse\",\"style\":{\"height\":\"10px\"}},\"x-validator\":[],\"x-component-props\":{\"bordered\":false,\"style\":{\"padding\":\"0px 0px 0px 0px\",\"margin\":\"0px 0px 0px 0px\"}},\"type\":\"string\",\"title\":\"\",\"x-index\":25,\"default\":\"-------------------------------------------------------------------------------------------------------------------------------\",\"x-decorator\":\"FormItem\",\"x-pattern\":\"disabled\"},\"h1rak8alc92\":{\"x-component\":\"Input\",\"x-designable-id\":\"h1rak8alc92\",\"x-decorator-props\":{\"layout\":\"horizontal\",\"size\":\"small\",\"labelAlign\":\"left\",\"feedbackLayout\":\"terse\",\"style\":{\"height\":\"10px\"}},\"x-validator\":[],\"x-component-props\":{\"bordered\":false,\"style\":{\"padding\":\"0px 0px 0px 0px\",\"margin\":\"0px 0px 0px 0px\"}},\"type\":\"string\",\"title\":\"\",\"x-index\":8,\"default\":\"-------------------------------------------------------------------------------------------------------------------------------\",\"x-decorator\":\"FormItem\",\"x-pattern\":\"disabled\"},\"k4mdrl3w0nf\":{\"x-component\":\"Input\",\"x-designable-id\":\"k4mdrl3w0nf\",\"x-decorator-props\":{\"fullness\":false,\"bordered\":false,\"layout\":\"horizontal\",\"labelAlign\":\"left\",\"colon\":false,\"feedbackLayout\":\"terse\",\"style\":{\"margin\":\"0px 0px 0px 0px\",\"display\":\"block\",\"fontWeight\":800,\"height\":\"40px\"}},\"x-validator\":[],\"x-component-props\":{\"bordered\":false,\"style\":{\"height\":\"0%\"}},\"type\":\"string\",\"title\":\"容器部署\",\"x-index\":26,\"default\":\"\",\"x-decorator\":\"FormItem\",\"x-pattern\":\"disabled\"}}},\"form\":{\"wrapperCol\":12,\"labelCol\":6}}', '\n该模板演示基于 GoLang + Gin +docker实现全自动检出代码 -> 单元测试 -> 编译构建->构建 Docker 镜像 -> 推送到 Docker 制品库 -> 部署到远端服务器,主要子步骤包括：gitClone, codeBuild, shCommand, imageBuild, k8sApplicationDeploy，这里介绍用法和入参含义。\n\n1  **代码克隆（gitClone）**\n    代码克隆子步骤可以选择从内部仓库（type==1）或者是外部仓库（type==2）克隆代码到流水线执行；\n    从内部仓库克隆时，需要填写服务器ID （gitServerId），仓库ID（gitGitLabId），和分支名称（branch2）\n    如果是从外部仓库克隆，除了需要代码http地址（gitUrl）和分支（branch1），还需要账号名（gitUser）和密码（password），以下是完整的子步骤代码：\n```\n/**\n * 定义一个可以本地使用的\n */\ndef call(String stepName,String type,String gitUrl,String gitUser,String password,String branch1,String gitServerId ,String gitGitLabId,String branch2){\n    echo \"代码克隆\"\n    if(gitServerId == \'\'){\n        gitServerId = \'2274147683644780544\'\n    }\n    def branch = branch1\n    def credentialsId = \"3d07ff58-2cd4-4939-b119-f44c32a6f7b6\"\n    if( type == \'1\'){\n        gitUrl = gitGitLabId.split(\"\\\\|\")[1]\n        branch = branch2\n    }else{\n        //根据用户名、密码和jobId来动态查询凭证id\n        def response = sh(returnStdout: true ,script: \"\"\"\n        curl -X GET \"${env.pipelineSvcUrl}/deploy/credentials/gitCredentialsId?jobId=${env.job_id}&gitUserName=${gitUser}&gitPassword=${password}\" -H \"accept: */*\"\n        \"\"\")\n        def resData = readJSON text: \"\"\"${response}\"\"\"\n        credentialsId = resData.data\n    }\n    echo \"${gitUrl}\"\n    echo \"${branch}\"\n    checkout([$class: \"GitSCM\",\n              branches: [[name: branch]],\n              extensions: [[\n                                   $class: \'CloneOption\',\n                                   shallow: true,\n                                   depth:   1,\n                                   timeout: 30\n                           ]],\n              userRemoteConfigs: [[\n                                          credentialsId: credentialsId,\n                                          url: gitUrl\n                                  ]]])\n    //通知流水线serviceId、gitlabId、commitId\n    if(type == \'1\'){\n        def commitId = sh(returnStdout: true ,script: \'git rev-parse --verify HEAD\').replaceAll(\"\\\\s+\", \"\")\n        env.gitCommitId = commitId\n        gitGitLabId = gitGitLabId.split(\"\\\\|\")[0]\n        sh \"\"\"\n        curl -X POST \"${env.pipelineSvcUrl}/devops/pipeline/${env.job_id}/${env.BUILD_NUMBER}/commitId?serverId=${gitServerId}&gitLabId=${gitGitLabId}&branch=${branch}&commitId=${commitId}&gitRepo=${gitUrl}\" -H \"accept: */*\" -d \"\" \n        \"\"\"\n        env.gitLabId = gitGitLabId\n\n    }\n    env.gitRepo = gitUrl\n\n}\n\n```\n2 **安装依赖（shCommand）**\ngolang通常需要安装第三方依赖来实现一些特定功能，例如可以使用go-junit-report工具，将go test 输出转换为XML报告，例如，使用shell命令子步骤来执行\"go install github.com/jstemmer/go-junit-report/v2@latest\" 安装工具\n\n\n3 **代码构建（codeBuild）**\n    构建代码时，可以选择不同的语言版本（language），不同的构建工具（buildTool），以满足不同代码构建环境需求，最后输入代码构建指令（buildCommand），具体子步骤代码如下：\n```\ndef call(String stepName,String language,String buildTool,String buildCommand){\n    echo \"${buildCommand}\"\n    retry(3) {\n        sh \"\"\"\n        ${buildCommand}\n         \"\"\"\n    }\n}\n```\n4 **单元测试（shCommand）** \n这里选择可以执行任意shell脚本的shell命令子步骤来实现单元测试，需要手动输入自定义单元测试指令，例如“npm run test”\n```\ndef call(String  stepName,String command) {\n    println(\"---${command}----\")\n    sh \"\"\"\n    ${command}\n    \"\"\"\n}\n```\n5 **构建 Docker 镜像（imageBuild）**\n    此子步骤将步骤2构建完成的代码，通过dockerfile制作成docker镜像，因此代码根目录需要提供相对应的Dockerfile，若没有提供，子步骤将使用如下默认Dockerfile：\n```\nFROM golang:1.19-bullseye\nUSER root\nWORKDIR /home/go\nCOPY ./ ./\nENTRYPOINT [\"./go-app\"]\n```\n镜像构建子步骤主要参数包括：harbor地址（harborUrl），自定义镜像名称（imageName），dockerfile文件名（dockerfile）,镜像标签名（tagert），具体代码如下：\n```\ndef call(String stepName,String harborUrl,String imageName,String dockerfile,String tagert){\n    if(!fileExists(dockerfile)){\n        def language= params.language\n        println(\"-------------\"+language)\n        if(language == \'java8\' ||  language == \'java\'){\n            sh \"\"\"\n            echo -e \"FROM openjdk:8\\nWORKDIR /app\\nCOPY target/*.jar ./app.jar\\nENTRYPOINT [\"java\", \"-jar\",\"/app/app.jar\"]\" > Dockerfile\n            \"\"\"\n        }else if(language == \'java11\'){\n            sh \"\"\"\n            echo -e \"FROM openjdk:11\\nWORKDIR /app\\nCOPY target/*.jar ./app.jar\\nENTRYPOINT [\"java\", \"-jar\",\"/app/app.jar\"]\" > Dockerfile\n            \"\"\"\n        }else if(language == \'node14\'){\n            sh \"\"\"\n            echo -e \"FROM node:14.16\\nWORKDIR /app\\nCOPY dist/ ./dist/\\nENTRYPOINT npm run entrypoint\" > Dockerfile\n            \"\"\"\n        }else if(language == \'net5\'){\n            sh \"\"\"\n            echo -e \"FROM mcr.microsoft.com/dotnet/runtime:3.1.31-buster-slim\\nWORKDIR /app\\nCOPY app/build/ ./\\nENTRYPOINT [\"dotnet\", \"dotnetWebDemo.dll\"]\" > Dockerfile\n            \"\"\"\n        }else if(language == \'php7\'){\n            sh \"\"\"\n            echo -e \"FROM php:7.4.33-cli-bullseye\\nWORKDIR /app\\nCOPY ./ ./\\nRUN composer install\\nCMD [\"php\", \"-S 0.0.0.0:80\", \"-t ./\"]\" > Dockerfile\n            \"\"\"\n        }else if(language == \'golang1.19\'){\n            sh \"\"\"\n            echo -e \"FROM golang:1.19-bullseye\\nUSER root\\nWORKDIR /home/go\\nCOPY ./ ./\\nENTRYPOINT [\"./go-app\"]\" > Dockerfile\n            \"\"\"\n        }else if(language == \'python3\'){\n            sh \"\"\"\n            echo -e \"FROM python:3.8-bullseye\\nUSER root\\nWORKDIR /home/python\\nCOPY dist/ ./dist/\" > Dockerfile\n            \"\"\"\n        }else{\n            error \"error\"\n        }\n    }\n    sh \"docker build -f ${dockerfile} -t ${harborUrl}/${imageName}:${tagert} .\"\n    withCredentials([usernamePassword(credentialsId: \"harbor-pipeline-credentials\",passwordVariable: \'password\', usernameVariable: \'username\')]) {\n        sh \"docker login -u ${username} -p ${password} ${harborUrl}\"\n    }\n    retry(3) {\n        sh \"docker push ${harborUrl}/${imageName}:${tagert}\"\n    }\n    sh \"docker rmi -f ${harborUrl}/${imageName}:${tagert}\"\n\n    env.harborUrl = harborUrl\n    env.imageName = imageName\n    env.tagert = tagert\n}\n```\n5 **部署到云端**\n将构建完成的Docker部署到k8s集群上，在此步骤中，需要提供k8s的环境ID（envId）、部署集群ID（clusterId）、命名空间（namespace）和deployment，具体代码如下：\n```\ndef call(String stepName,String envId,String clusterId,String namespace,String deployment){\n    //根据clusterId查询环境url和token\n    def response = sh returnStdout: true ,script:\"\"\"\n    curl -X GET \"${env.pipelineSvcUrl}/deploy/cluster/${clusterId}/token\" -H \"accept: */*\"\n    \"\"\"\n    def resData = readJSON text: \"\"\"${response}\"\"\"\n    \n    sh \"\"\"\n        kubectl config set-cluster kubernetes --server=https://${resData.data[0].ip}:${resData.data[0].port} --insecure-skip-tls-verify=true\n        set +x\n        kubectl config set-credentials admin --token=${resData.data[0].token}\n        set -x\n        kubectl config set-context dev --cluster=kubernetes --user=admin\n        kubectl config use-context dev\n    \"\"\"\n    if(env.imageName) {\n        def res = sh returnStdout: true, script: \"\"\"  \n        kubectl set image deployment ${deployment} *=${env.harborUrl}/${env.imageName}:${env.tagert} -n ${namespace}       \n        \"\"\"\n        if (!res.contains(\"update\")) {\n            sh \"kubectl rollout restart deployment ${deployment} -n ${namespace}\"\n        } else {\n            sh \"kubectl rollout restart deployment ${deployment} -n ${namespace}\"\n        }\n    }\n}\n```\n');
INSERT INTO `devops_jenkinsfile_template` VALUES (11, 'GoLang + Gin +虚拟机', '{\"pipeline\":{\"agent\":{\"type\":\"kubernetes\",\"arguments\":[{\"value\":{\"isLiteral\":false,\"value\":\"\\\"${env.runCluster}\\\"\"},\"key\":\"cloud\"},{\"value\":{\"isLiteral\":true,\"value\":\"maven\"},\"key\":\"defaultContainer\"},{\"value\":{\"isLiteral\":true,\"value\":\"\\napiVersion: v1\\nkind: Pod\\nspec:\\n  containers:\\n  - name: jnlp\\n    imagePullPolicy: Always\\n    image: ${env.inboundImage}\\n  - name: maven\\n    imagePullPolicy: Always\\n    image: ${env.agentImage}\\n    command:\\n    - sleep\\n    args:\\n    - 99d\\n    resources:\\n      requests:\\n        cpu: \\\"100m\\\"\\n        memory: \\\"100Mi\\\"\\n      limits:\\n        cpu: \\\"4000m\\\"\\n        memory: \\\"8192Mi\\\"\\n    volumeMounts:\\n      - mountPath: \\\"/root/.m2/repository\\\"\\n        name: \\\"volume-0\\\"\\n        readOnly: false\\n      - mountPath: \\\"/var/run/docker.sock\\\"\\n        name: \\\"volume-1\\\"\\n        readOnly: false\\n      - mountPath: /root/.m2/settings.xml\\n        name: config\\n        subPath: settings.xml\\n  volumes:\\n    - hostPath:\\n        path: \\\"/var/run/docker.sock\\\"\\n      name: \\\"volume-1\\\"\\n    - hostPath:\\n        path: \\\"/root/.m2/repository\\\"\\n      name: \\\"volume-0\\\"\\n    - configMap:\\n        items:\\n        - key: settings.xml\\n          path: settings.xml\\n        name: jenkins-agent-config\\n      name: config\\n\"},\"key\":\"yaml\"}]},\"stages\":[{\"branches\":[{\"steps\":[{\"stepName\":\"代码克隆\",\"name\":\"gitClone\",\"arguments\":[{\"isLiteral\":true,\"value\":\"代码克隆\"},{\"isLiteral\":true,\"value\":\"[serviceType]\"},{\"isLiteral\":true,\"value\":\"[git_repo]\"},{\"isLiteral\":true,\"value\":\"[credentiail]\"},{\"isLiteral\":true,\"value\":\"[branch_1]\"},{\"isLiteral\":true,\"value\":\"[service_id]\"},{\"isLiteral\":true,\"value\":\"[project_id]\"},{\"isLiteral\":true,\"value\":\"[branch_2]\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"代码拉取\"},\"key\":\"stageName\"}],\"name\":\"代码拉取\"},{\"branches\":[{\"steps\":[{\"stepName\":\"安装依赖\",\"name\":\"shCommand\",\"arguments\":[{\"isLiteral\":true,\"value\":\"安装依赖\"},{\"isLiteral\":true,\"value\":\"[dependencies]\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"依赖安装\"},\"key\":\"stageName\"}],\"name\":\"依赖安装\"},{\"branches\":[{\"steps\":[{\"stepName\":\"单元测试\",\"name\":\"shCommand\",\"arguments\":[{\"isLiteral\":true,\"value\":\"单元测试\"},{\"isLiteral\":true,\"value\":\"go test\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"单元测试\"},\"key\":\"stageName\"}],\"name\":\"单元测试\"},{\"branches\":[{\"steps\":[{\"stepName\":\"代码构建\",\"name\":\"codeBuild\",\"arguments\":[{\"isLiteral\":true,\"value\":\"代码构建\"},{\"isLiteral\":true,\"value\":\"[params_language]\"},{\"isLiteral\":true,\"value\":\"[params_buildTool]\"},{\"isLiteral\":true,\"value\":\"[command2]\"},{\"isLiteral\":true,\"value\":\"[file_setting]\"},{\"isLiteral\":true,\"value\":\"[null_settingContent]\"},{\"isLiteral\":true,\"value\":\"[proxy]\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"编译构建\"},\"key\":\"stageName\"}],\"name\":\"编译构建\"},{\"branches\":[{\"steps\":[{\"stepName\":\"通用制品上传\",\"name\":\"universalProductUpload\",\"arguments\":[{\"isLiteral\":true,\"value\":\"通用制品上传\"},{\"isLiteral\":true,\"value\":\"[repoId]\"},{\"isLiteral\":true,\"value\":\"[file]\"},{\"isLiteral\":true,\"value\":\"[filePath]\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"推送到制品库\"},\"key\":\"stageName\"}],\"name\":\"推送到制品库\"},{\"branches\":[{\"steps\":[{\"stepName\":\"主机部署\",\"name\":\"hostDeploy\",\"arguments\":[{\"isLiteral\":true,\"value\":\"主机部署\"},{\"isLiteral\":true,\"value\":\"[deployEnv]\"},{\"isLiteral\":true,\"value\":\"[deployHost]\"},{\"isLiteral\":true,\"value\":\"[from]\"},{\"isLiteral\":true,\"value\":\"[to]\"},{\"isLiteral\":true,\"value\":\"[command]\"}]}],\"name\":\"default\"}],\"environment\":[{\"value\":{\"isLiteral\":true,\"value\":\"部署到云端\"},\"key\":\"stageName\"}],\"name\":\"部署到云端\"}]]', 'pipeline {\n  agent {\n    kubernetes {\n      cloud \"${env.runCluster}\"\n      defaultContainer \'maven\'\n      yaml \'\'\'\napiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: jnlp\n    imagePullPolicy: Always\n    image: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/root/.m2/repository\"\n        name: \"volume-0\"\n        readOnly: false\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n      - mountPath: /root/.m2/settings.xml\n        name: config\n        subPath: settings.xml\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - hostPath:\n        path: \"/root/.m2/repository\"\n      name: \"volume-0\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码拉取\') {\n      environment {\n        stageName = \'代码拉取\'\n      }\n      steps {\n        gitClone(\'代码克隆\', \'[serviceType]\', \'[git_repo]\', \'[credentiail]\', \'[branch_1]\', \'[service_id]\', \'[project_id]\', \'[branch_2]\')\n      }\n    }\n\n    stage(\'依赖安装\') {\n      environment {\n        stageName = \'依赖安装\'\n      }\n      steps {\n        shCommand(\'安装依赖\', \'[dependencies]\')\n      }\n    }\n\n    stage(\'单元测试\') {\n      environment {\n        stageName = \'单元测试\'\n      }\n      steps {\n        shCommand(\'单元测试\', \'go test\')\n      }\n    }\n\n    stage(\'编译构建\') {\n      environment {\n        stageName = \'编译构建\'\n      }\n      steps {\n        codeBuild(\'代码构建\', \'[params_language]\', \'[params_buildTool]\', \'[command2]\', \'[file_setting]\', \'[null_settingContent]\', \'[proxy]\')\n      }\n    }\n\n    stage(\'推送到制品库\') {\n      environment {\n        stageName = \'推送到制品库\'\n      }\n      steps {\n        universalProductUpload(\'通用制品上传\', \'[repoId]\', \'[file]\', \'[filePath]\')\n      }\n    }\n\n    stage(\'部署到云端\') {\n      environment {\n        stageName = \'部署到云端\'\n      }\n      steps {\n        hostDeploy(\'主机部署\', \'[deployEnv]\', \'[deployHost]\', \'[from]\', \'[to]\', \'[command]\')\n      }\n    }\n\n  }\n}', '[{\"defaultValue\":\"latest\",\"paramName\":\"tag\",\"type\":\"string\",\"showFlag\":true,\"trim\":false},{\"defaultValue\":\"main\",\"paramName\":\"branch\",\"type\":\"string\",\"showFlag\":true,\"trim\":false}]', '[{\"updateFlag\":true,\"paramName\":\"buildTool\",\"paramValue\":\"golang\"},{\"updateFlag\":true,\"paramName\":\"language\",\"paramValue\":\"golang1.19\"}]', 0, NULL, 0, 0, '2022-12-16 09:08:59', '2023-05-29 09:46:24', NULL, 1, '该模板演示基于 GoLang + Gin 实现全自动检出代码 -> 单元测试 -> 编译构建 -> 推送到 制品库 -> 部署到远端服务器', '1', '{}', 'go_img', '{\"schema\":{\"x-designable-id\":\"okj11idinxs\",\"type\":\"object\",\"properties\":{\"e38uia797su\":{\"x-component\":\"Input\",\"x-designable-id\":\"e38uia797su\",\"x-decorator-props\":{\"fullness\":false,\"bordered\":false,\"layout\":\"horizontal\",\"labelAlign\":\"left\",\"colon\":false,\"feedbackLayout\":\"terse\",\"style\":{\"margin\":\"0px 0px 0px 0px\",\"display\":\"block\",\"fontWeight\":800,\"height\":\"40px\"}},\"x-validator\":[],\"x-component-props\":{\"bordered\":false,\"style\":{\"height\":\"0%\"}},\"type\":\"string\",\"title\":\"代码库\",\"x-index\":0,\"default\":\"\",\"x-decorator\":\"FormItem\",\"x-pattern\":\"disabled\"},\"serviceType\":{\"x-component\":\"Select\",\"x-designable-id\":\"mnue2j6knv9\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"代码库类型\",\"x-index\":1,\"enum\":[{\"label\":\"内部\",\"children\":[],\"value\":\"1\"},{\"label\":\"外部\",\"children\":[],\"value\":\"2\"}],\"default\":\"1\",\"x-decorator\":\"FormItem\",\"name\":\"serviceType\",\"x-reactions\":{\"dependencies\":[{\"type\":\"any\",\"property\":\"value\"}]}},\"null_settingContent\":{\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"ybivkz35v55\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{\"autoSize\":true},\"type\":\"string\",\"title\":\"文件内容\",\"x-index\":17,\"x-decorator\":\"FormItem\",\"name\":\"null_settingContent\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.file_setting) {\\n    //console.log($deps.settingFile[0].response.data.link)\\n    var link = $deps.file_setting[0].response.data.link\\n    //var link = `http%3A%2F%2F10.10.102.202%3A33006%2Famp%2F1c8ffc057e6af27fe7dc8d096270be85.xml`\\n    if (link) {\\n      const org = sessionStorage.getItem(\\\"curOrg\\\") || \\\"{}\\\"\\n      var orgId = \\\"\\\"\\n      if (org != \\\"{}\\\") orgId = JSON.parse(org).organId || \\\"\\\"\\n      var token = localStorage.getItem(\\\"userToken\\\")\\n      fetch(\\n        `${window.location.origin}/api/efficiency/devops/pipeline/fileContent?url=${link}`,\\n        {\\n          headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n        }\\n      )\\n        .then((response) => response.json())\\n        .then(\\n          ({ data }) => {\\n            $self.initialValue = data\\n          },\\n          () => {}\\n        )\\n    }\\n  }\\n}, [$deps.file_setting])\\n\",\"state\":{\"visible\":\"{{$deps.params_language.startsWith(\\\"java\\\")}}\"}},\"dependencies\":[{\"source\":\"params_language\",\"type\":\"any\",\"property\":\"value\",\"name\":\"params_language\"},{\"source\":\"file_setting\",\"type\":\"Array<object>\",\"property\":\"value\",\"name\":\"file_setting\"}]},\"x-pattern\":\"readOnly\"},\"params_buildTool\":{\"x-component\":\"TreeSelect\",\"x-designable-id\":\"en2aaua08oj\",\"x-display\":\"visible\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"构建工具\",\"x-index\":14,\"required\":false,\"default\":\"\",\"x-decorator\":\"FormItem\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  treeData = [\\n    {\\n      label: \\\"maven\\\",\\n      value: \\\"maven\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          label: \\\"maven3.5\\\",\\n          value: \\\"maven3.5\\\",\\n        },\\n      ],\\n    },\\n    // {\\n    //   label: \\\"gradle\\\",\\n    //   value: \\\"gradle\\\",\\n    //   disabled: true,\\n    //   children: [\\n    //     {\\n    //       label: \\\"gradle4.1\\\",\\n    //       value: \\\"gradle4.1\\\",\\n    //     },\\n    //     {\\n    //       label: \\\"gradle4.2\\\",\\n    //       value: \\\"gradle4.2\\\",\\n    //     },\\n    //     {\\n    //       label: \\\"gradle4.3\\\",\\n    //       value: \\\"gradle4.3\\\",\\n    //     },\\n    //     {\\n    //       label: \\\"gradle4.4\\\",\\n    //       value: \\\"gradle4.4\\\",\\n    //     },\\n    //     {\\n    //       label: \\\"gradle4.5\\\",\\n    //       value: \\\"gradle4.5\\\",\\n    //     },\\n    //     {\\n    //       label: \\\"gradle4.6\\\",\\n    //       value: \\\"gradle4.6\\\",\\n    //     },\\n    //     {\\n    //       label: \\\"gradle4.7\\\",\\n    //       value: \\\"gradle4.7\\\",\\n    //     },\\n    //     {\\n    //       label: \\\"gradle4.8\\\",\\n    //       value: \\\"gradle4.8\\\",\\n    //     },\\n    //     {\\n    //       label: \\\"gradle4.9\\\",\\n    //       value: \\\"gradle4.9\\\",\\n    //     },\\n    //     {\\n    //       label: \\\"gradle4.10\\\",\\n    //       value: \\\"gradle4.10\\\",\\n    //     },\\n    //   ],\\n    // },\\n    {\\n      label: \\\"sdk\\\",\\n      value: \\\"sdk\\\",\\n      disabled: true,\\n      children: [\\n        {\\n          label: \\\"sdk-30\\\",\\n          value: \\\"sdk-30\\\",\\n        },\\n      ],\\n    },\\n  ]\\n  $self.dataSource = treeData\\n}, [$deps.params_language])\\n\",\"state\":{\"visible\":\"{{$deps.params_language.startsWith(\\\"java\\\") || $deps.params_language.startsWith(\\\"openjdk\\\")}}\"}},\"dependencies\":[{\"source\":\"params_language\",\"type\":\"any\",\"property\":\"value\",\"name\":\"params_language\"}]},\"name\":\"params_buildTool\"},\"command2\":{\"x-component\":\"Input.TextArea\",\"x-designable-id\":\"r8k8ml4hijf\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"构建命令\",\"x-index\":15,\"required\":true,\"default\":\"\",\"x-decorator\":\"FormItem\",\"name\":\"command2\"},\"file\":{\"x-component\":\"Input\",\"x-designable-id\":\"aa6kjk1yflm\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"type\":\"string\",\"title\":\"上传文件\",\"x-index\":22,\"required\":true,\"x-decorator\":\"FormItem\",\"name\":\"file\"},\"project_id\":{\"x-component\":\"Select\",\"x-designable-id\":\"t189up47dxd\",\"x-decorator-props\":{\"layout\":\"vertical\",\"labelAlign\":\"left\"},\"x-validator\":[],\"x-component-props\":{},\"title\":\"仓库\",\"x-index\":6,\"required\":true,\"x-decorator\":\"FormItem\",\"name\":\"project_id\",\"x-reactions\":{\"fulfill\":{\"run\":\"$effect(() => {\\n  if ($deps.service_id) {\\n    $self.loading = true\\n    var token = localStorage.getItem(\\\"userToken\\\")\\n    var subSystemId = window.location.search\\n      .split(\\\"subSystemId=\\\")[1]\\n    var gitlabId = 0\\n    var gitlabRepo = \\\"\\\"\\n    if (subSystemId) {\\n      subSystemId = subSystemId.split(\\\"&\\\")[0]\\n      fetch(\\n        `${window.location.origin}/api/cloud/open/pipel