ing = false\\n          $self.dataSource = re\\n        },\\n        () => {}\\n      )\\n  } else if ($deps.language.startsWith(\\\"go\\\")) {\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/repository?format=go&pageNum=1&pageSize=999&kind=0&repositoryType=group`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.records.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"|\\\" + k.url,\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {}\\n      )\\n  } else if ($deps.language.startsWith(\\\"python\\\")) {\\n    fetch(\\n      `${window.location.origin}/api/warehouse/api/repository?format=pypi&pageNum=1&pageSize=999&kind=0&repositoryType=group`,\\n      {\\n        headers: { \\\"Amp-Organ-Id\\\": orgId, Authorization: token },\\n      }\\n    )\\n      .then((response) => response.json())\\n      .then(\\n        ({ data }) => {\\n          const re = data.records.map((k) => ({\\n            ...k,\\n            value: k.id + \\\"|\\\" + k.url,\\n            label: k.name,\\n          }))\\n          $self.loading = false\\n          $self.dataSource = re\\n        },\\n        () => {}\\n      )\\n  }\\n}, [$deps.language])\\n\",\"state\":{\"visible\":\"{{$deps.language.startsWith(\\\"node\\\") || \\n$deps.language.startsWith(\\\"go\\\") || \\n$deps.language.startsWith(\\\"python\\\")}}\"}},\"dependencies\":[{\"source\":\"language\",\"type\":\"any\",\"property\":\"value\",\"name\":\"language\"}]}},\"file_setting\":{\"x-component\":\"Upload.Dragger\",\"x-designable-id\":\"c8br6wkusuv\",\"x-decorator-props\":{\"tooltip\":\"可选项，如需使用指定的settings.xml，请在此处上传文件，通常使用平台内置的即可\"},\"x-component-props\":{\"method\":\"POST\",\"textContent\":\"点击或拖拽文件到此区域上传\",\"maxCount\":1,\"accept\":\".xml\",