        readOnly: false\n      - mountPath: /root/.m2/settings.xml\n        name: config\n        subPath: settings.xml\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      steps {\n        gitClone(stepName: \'代码克隆\', serviceType: \'1\', gitUrl: \'\', gitCredentialId: \'\', serverId: \'1\', gitlabId: \'\', branch: \'\', startParamName_branch: \'\', dmkl_btn1: \'设置为变量\', dmkl_btn_1: \'\', gitPath: \'\')\n      }\n    }\n\n    stage(\'编译构建\') {\n      steps {\n        codeBuild(stepName: \'代码构建\', language: \'node14.17.6\', buildTool: \'maven3.5\', command: \'\'\'rm -rf  package-lock.json\nrm -rf yarn.lock\nrm -rf node_modules\nnpm install --registry=http://192.168.15.107:32481/repository/ahzx/\nnpm run build:prod\ntar -zcvf dist.tar.gz dist\'\'\', file_setting: \'\', proxy: \'\')\n      }\n    }\n\n    stage(\'代码扫描\') {\n      steps {\n        sonarScanByParams(stepName: \'通用代码扫描\', scanPath: \'.\', excludePath: \'\', sonarProject: \'2815979210091364352\', sonarGate: \'0\', waitGate: false, addScan: false, compareBranch: \'\')\n      }\n    }\n\n    stage(\'依赖分析\') {\n      steps {\n        dependAnsysial(stepName: \'依赖检测分析\', dependLanguage: \'js\', scanPath: \'.\', extend: \'\', deepAnalysis: false, doorFlag: false)\n      }\n    }\n\n    stage(\'通用制品上传\') {\n      steps {\n        universalProductUploadFun(stepName: \'通用制品上传\', rawRepository: \'\', startParamName_rawRepository: \"${rawRepository}\", tyzpsc_btn_1: true, tyzpsc_btn1: \'选择已有\', version: \'\', str_version: \'\', startParamName_version: \"${version}\", tyzpsc_btn_2: true, tyzpsc_btn2: \'直接输入\', file: \'dist.tar.gz\', productName: \'\')\n      }\n    }\n\n  }\n}', '[]', '[]', 0, NULL, 1, 0, '2024-05-20 17:45:15', '2024-05-20 17:45:15', 1, 1, '前端-测试环境-自