ps {\n        dependAnsysial(\'依赖检测分析\', \'java\', \'.\', \'\', false, false)\n      }\n    }\n\n    stage(\'镜像构建\') {\n      steps {\n        subSystemImageBuild(\'镜像构建（子系统）\', \"${dockerRepository}\", \'ruoyi\', \'ruoyi-admin/Dockerfile\', \'amd64\', \"${version}_${date}\")\n      }\n    }\n\n    stage(\'配置克隆\') {\n      steps {\n        configRepo(\'配置克隆\', \'1|12\', \'master\', \'config/\')\n      }\n    }\n\n    stage(\'镜像更新\') {\n      steps {\n        k8sApplicationDeploy_v1(\'Kubernetes镜像更新\', \"${deployEnv}\", \"${deployCluster}\", \"${namespace}\", \'ruoyi-admin\', \'1\', \'\')\n      }\n    }\n\n  }\n}', '超级管理员', '0', '0', NULL, NULL);
