n      defaultContainer \'maven\'\n      yaml \'\'\'\napiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: jnlp\n    image: ${env.inboundImage}\n  - name: maven\n    imagePullPolicy: Always\n    image: ${env.agentImage}\n    command:\n    - sleep\n    args:\n    - 99d\n    resources:\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n    volumeMounts:\n      - mountPath: \"/var/run/docker.sock\"\n        name: \"volume-1\"\n        readOnly: false\n      - mountPath: /root/.m2/settings.xml\n        name: config\n        subPath: settings.xml\n  volumes:\n    - hostPath:\n        path: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n    - configMap:\n        items:\n        - key: settings.xml\n          path: settings.xml\n        name: jenkins-agent-config\n      name: config\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      steps {\n        subsystemClone(stepName: \'代码克隆\', startParamName_subSystemBranch: \"${branch}\", subSystemBranch: \'8|master\')\n      }\n    }\n\n    stage(\'代码构建\') {\n      steps {\n        codeBuild(\'代码构建\', \'java8\', \'maven3.5\', \'\'\'mvn clean package\n\'\'\', \'\', \'\'\'\n\'\'\', \'\')\n      }\n    }\n\n    stage(\'代码扫描\') {\n      steps {\n        sonarScanByParams(\'通用代码扫描\', \'\', \'.\', \'2815975024024977408\', \'0\', false, false, \'\')\n      }\n    }\n\n    stage(\'依赖分析\') {\n      steps {\n        dependAnsysial(\'依赖检测分析\', \'java\', \'.\', \'\', false, false)\n      }\n    }\n\n    stage(\'镜像构建\') {\n      steps {\n        subSystemImageBuild(\'镜像构建（子系统）\', \"${dockerRepository}\", \'ruoyi\', \'ruoyi-admin/Dockerfile\', \'amd64\', \"${version}_${date}\")\n      }\n    }\n\n    stage(\'配置克隆\') {\n      steps {\n        configRepo(\'配置克隆\', \'1|12\', \'master\', \'config/\')\n      }\n    }\n\n    stage(\'镜像更新\') {\n      steps {\n        k8sApplicationDeploy_v1(\'Kubernetes镜像更新\', \"${deployEnv}\", \"${deployCluster