Value\":\"-\",\"mulFlag\":false,\"paramName\":\"excludePath\",\"requiredFlag\":true,\"showFlag\":true,\"trim\":false,\"type\":\"string\",\"updateFlag\":true,\"value\":\"-\"},{\"choice\":[],\"defaultValue\":\"f76dhdz012\",\"mulFlag\":false,\"paramName\":\"projectKey\",\"requiredFlag\":true,\"showFlag\":true,\"trim\":false,\"type\":\"string\",\"updateFlag\":true,\"value\":\"3r816b09v7\"},{\"choice\":[],\"defaultValue\":\"-\",\"mulFlag\":false,\"paramName\":\"compareBranch\",\"requiredFlag\":true,\"showFlag\":true,\"trim\":false,\"type\":\"string\",\"updateFlag\":true,\"value\":\"-\"},{\"choice\":[],\"defaultValue\":\"1\",\"mulFlag\":false,\"paramName\":\"job_id\",\"requiredFlag\":true,\"showFlag\":true,\"trim\":false,\"type\":\"string\",\"updateFlag\":true,\"value\":\"1\"},{\"choice\":[],\"defaultValue\":\"2791326471761244160\",\"mulFlag\":false,\"paramName\":\"historyId\",\"requiredFlag\":true,\"showFlag\":true,\"trim\":false,\"type\":\"string\",\"updateFlag\":true,\"value\":\"3405511115037384704\"},{\"choice\":[],\"defaultValue\":\"http://sonarqube-svc.cloudnativehcprod-hc-devops:9000\",\"mulFlag\":false,\"paramName\":\"sonarUrl\",\"requiredFlag\":true,\"showFlag\":true,\"trim\":false,\"type\":\"string\",\"updateFlag\":true,\"value\":\"http://sonarqube-svc:9000\"},{\"choice\":[],\"defaultValue\":\"http://10.10.103.61:31200/demo-system/java11-demo.git\",\"mulFlag\":false,\"paramName\":\"gitRepoUrl\",\"requiredFlag\":true,\"showFlag\":true,\"trim\":false,\"type\":\"string\",\"updateFlag\":true,\"value\":\"http://192.168.15.107:32765/code/ahc-devops/track-issues-svc-v2.git\"},{\"choice\":[],\"defaultValue\":\"http://devops-code-inspect-svc.cloudnativehcprod-hc-devops:8080\",\"mulFlag\":false,\"paramName\":\"codeInspectUrl\",\"requiredFlag\":true,\"showFlag\":true,\"trim\":false,\"type\":\"string\",\"updateFlag\":true,\"value\":\"http://devops-code-inspect-svc:8080\"},{\"choice\":[],\"defaultValue\":\"ALL\",\"mulFlag\":false,\"paramName\":\"runStageName\",\"requiredFlag\":true,\"showFlag\":true,\"trim\":false,\"type\":\"string\",\"updateFlag\":true,\"value\":\"ALL\"}]', '[{\"paramName\":\"language\",\"paramValue\":\"node14\",\"updateFlag\":true}]', '页面手动触发', '', '2024-06-07 08:31:30', '2024-06-07 08:33:11', 101159, 18, 0, 37, '[{\"durationMillis\":2265,\"id\":\"23\",\"name\":\"代码克隆\",\"parallel\":[],\"startTimeMillis\":1717720304735,\"status\":\"SUCCESS\",\"steps\":[\"代码克隆\"]},{\"durationMillis\":83959,\"id\":\"38\",\"name\":\"代码扫描\",\"parallel\":[],\"startTimeMillis\":1717720307015,\"status\":\"SUCCESS\",\"steps\":[\"sonar扫描\"]}]', 'SUCCESS', 0, 0, '2024-06-07 08:31:20', '2024-06-07 08:33:12', 0, NULL, '{\"allFuncName\":[\"script\"],\"gitBranch\":\"bugfix-dev-1-20240606\"}', '0', '0', 'pipeline {\n  agent {\n    kubernetes {\n      cloud \"${env.runCluster}\"\n      defaultContainer \'maven\'\n      yaml \'\'\'apiVersion: \"v1\"\nkind: \"Pod\"\nspec:\n  containers:\n  - image: \"${env.inboundImage}\"\n    name: \"jnlp\"\n  - args:\n    - \"99d\"\n    command:\n    - \"sleep\"\n    image: \"${env.agentImage}\"\n    // image: \"10.10.102.113:8443/devops-release/node14:1.0.0\"\n    imagePullPolicy: Always\n    name: \"maven\"\n    resources:\n      limits:\n        cpu: \"4000m\"\n        memory: \"8192Mi\"\n      requests:\n        cpu: \"100m\"\n        memory: \"100Mi\"\n    volumeMounts:\n    - mountPath: \"/var/run/docker.sock\"\n      name: \"volume-1\"\n      readOnly: false\n  volumes:\n  - hostPath:\n      path: \"/var/run/docker.sock\"\n    name: \"volume-1\"\n\'\'\'\n    }\n\n  }\n  stages {\n    stage(\'代码克隆\') {\n      environment {\n        stageName = \'代码克隆\'\n      }\n      steps {\n        script {\n          echo \'代码克隆\'\n          try{\n            if(gitUser&&gitUser!=\"-\"){\n              arr = gitRepoUrl.split(\"/\")\n              env.project = arr[arr.length -1].replace(\".git\",\"\")\n              projectexit = sh returnStdout: true ,script: \"ls|grep ${project}|tr -d \'\\n\\r\'\"\n\n              urlHead = gitRepoUrl.split(\":\")[0]\n              urlTail = gitRepoUrl.split(\"//\")[1]\n              gitUser = gitUser.replace(\"@\",\"@\")\n              gitPassword = gitPassword.replace(\"@\",\"@\")\n              def a = \"${urlHead}://${gitUser}:${gitPassword}@${urlTail}\"\n              if(projectexit == \'\'){\n                sh \"git clone -b ${branch} ${a} ./\"\n              }\n            }else{\n              checkout([$class: \"GitSCM\",\n              branches: [[name: branch]],\n              userRemoteConfigs: [[\n                credentialsId: env.gitCreadentId,\n                url: gitRepoUrl\n              ]]])\n            }\n            if(\"${commitId}\" != \"-\"){\n              sh \"git checkout ${commitId} \"\n            }\n\n          }catch(Exception e){\n            echo \"${e}\"\n            sh \'\'\'\n            curl \"${codeInspectUrl}/scanTasks/history/${historyId}/error\"\n            exit 1\n            \'\'\'\n          }\n        }\n\n      }\n    }\n\n    stage(\'代码扫描\') {\n      environment {\n        stageName = \'代码扫描\'\n      }\n      steps {\n        script {\n          echo \'sonar扫描\'\n          try{\n            sonarCommit = \"\"\n            sonarInclusion = \"\"\n            sonarExclusion = \"\"\n            compareBaseTime = \"\"\n            if(commitId != \"-\"){\n              sonarCommit = \"sonar.analysis.commitId=${commitId}\"\n              sh \"echo sonar.analysis.commitId=${commitId} >> sonar-project.properties\"\n            }else{\n              commitIdTemp = sh returnStdout: true ,script: \'git rev-parse --verify  HEAD\'\n              sh \"curl ${codeInspectUrl}/scanTasks/history/${historyId}/${commitIdTemp}\"\n              sonarCommit = \"sonar.analysis.commitId=${commitIdTemp}\"\n              sh \"echo sonar.analysis.commitId=${commitIdTemp} >> sonar-project.properties\"\n            }\n            if(compareBranch&&compareBranch!=\"-\"){\n              sonarInclusion = \"sonar.inclusions=-\"\n              changeFile = sh returnStdout: true, script: \"git diff ${compareBranch} --name-only\"\n              if(changeFile){\n                sonarInclusion = \"sonar.inclusions=\"+changeFile.replaceAll(\"\\n\",\",\")\n                sh \"echo ${sonarInclusion} >>sonar-project.properties\"\n              }\n              commitWithDate = sh returnStdout: true, script: \"git log --remotes --pretty=%H@%cd --date=iso|grep ${compareBranch}\"\n              compareBaseTime = \"sonar.analysis.baseTime=\\\"\"+commitWithDate.split(\"@\")[1]+\"\\\"\"\n              sh \"echo ${compareBaseTime} >>sonar-project.properties\"\n            }\n\n            if(excludePath&&excludePath!=\"-\"){\n              sonarExclusion = \"sonar.exclusions=${excludePath}\"\n              sh \"echo sonar.exclusions=${excludePath} >>sonar-project.properties\"\n            }\n            sh \"echo sonar.java.binaries=./>>sonar-project.properties\"\n            sh \"echo sonar.analysis.scanTaskId=${scanTaskId}>>sonar-project.properties\"\n            sh \"echo sonar.branch.name=${branch}>>sonar-project.properties\"\n            sh \"echo sonar.analysis.historyId=${historyId}>>sonar-project.properties\"\n            sh \"echo sonar.host.url=${sonarUrl}>>sonar-project.properties\"\n            sh \"echo sonar.login=${sonarusername}>>sonar-project.properties\"\n            sh \"echo sonar.password=${sonarpassword}>>sonar-project.properties\"\n            sh \"echo sonar.projectKey=${projectKey}>>sonar-project.properties\"\n\n            withEnv([\"PATH+WHATEVER=/usr/local/node-v16.16.0-linux-x64/bin\"]) {\n              sh \"/usr/local/sonar-scanner/bin/sonar-scanner\"\n            }\n\n          }catch(Exception e){\n            echo \"${e}\"\n            sh \'\'\'\n            curl \"${codeInspectUrl}/scanTasks/history/${historyId}/error\"\n            exit 1\n            \'\'\'\n          }\n        }\n\n      }\n    }\n\n  }\n  environment {\n    language = \'node14\'\n  }\n}', '未知', '0', '0', NULL, NULL);
